            id: optionData.id,
            node_id: optionData.node_id,
            text: optionData.text,
            next_node_id: optionData.next_node_id,
            action_type: optionData.action_type,
            action_data: optionData.action_data,
            order_position: optionData.order_position,
            is_active: optionData.is_active
          })
        });

        const result = await response.json();
        if (result.success) {
          alert('Opción creada correctamente!');
          loadChatbotData();
        } else {
          alert('Error: ' + result.error);
        }
      }
      setEditingItem(null);
      setShowForm(false);
    } catch (error) {
      console.error('Error saving option:', error);
      alert('Error al guardar la opción');
    }
  };

  // DELETE NODO
  const handleDeleteNode = async (nodeId: string) => {
    setDeleteTarget({ type: 'node', id: nodeId });
    setShowDeleteDialog(true);
  };

  // Función para confirmar eliminación
  const confirmDelete = async () => {
    if (!deleteTarget) return;

    try {
      if (deleteTarget.type === 'node') {
        const response = await fetch(`http://localhost:8000/test_chatbot_crud.php?node_id=${encodeURIComponent(deleteTarget.id)}`, {
          method: 'DELETE'
        });

        const result = await response.json();
        if (result.success) {
          alert('Nodo eliminado correctamente!');
          loadChatbotData();
        } else {
          alert('Error: ' + result.error);
        }
      } else if (deleteTarget.type === 'option') {
        const response = await fetch(`http://localhost:8000/test_chatbot_crud.php?option_id=${encodeURIComponent(deleteTarget.id)}`, {
          method: 'DELETE'
        });

        const result = await response.json();
        if (result.success) {
          alert('Opción eliminada correctamente!');
          loadChatbotData();
        } else {
          alert('Error: ' + result.error);
        }
      }
    } catch (error) {
      console.error('Error deleting:', error);
      alert('Error al eliminar');
    } finally {
      setShowDeleteDialog(false);
      setDeleteTarget(null);
    }
  };

  // DELETE OPCION
  const handleDeleteOption = async (optionId: string) => {
    setDeleteTarget({ type: 'option', id: optionId });
    setShowDeleteDialog(true);
  };

  const getNodeOptions = (nodeId: string) => {
    return options.filter(option => option.node_id === nodeId).sort((a, b) => a.order_position - b.order_position);
  };

  return (
    <div className="max-w-7xl mx-auto p-6 bg-gray-50 min-h-screen">
      <div className="mb-6">
        <h1 className="text-3xl font-bold text-gray-800 mb-2">Administrador de Chatbot</h1>
        <p className="text-gray-600">Gestiona los nodos, opciones y analíticas de tu chatbot decision tree</p>
      </div>

      {/* Navegación por pestañas */}
      <div className="flex border-b border-gray-200 mb-6">
        <button
          onClick={() => setActiveTab('nodes')}
          className={`px-4 py-2 font-medium text-sm border-b-2 transition-colors ${activeTab === 'nodes'
            ? 'border-blue-500 text-blue-600'
            : 'border-transparent text-gray-500 hover:text-gray-700'
            }`}
        >
          <MessageCircle size={16} className="inline mr-1" />
          Nodos ({nodes.length})
        </button>
        <button
          onClick={() => setActiveTab('options')}
          className={`px-4 py-2 font-medium text-sm border-b-2 transition-colors ${activeTab === 'options'
            ? 'border-blue-500 text-blue-600'
            : 'border-transparent text-gray-500 hover:text-gray-700'
            }`}
        >
          <List size={16} className="inline mr-1" />
          Opciones ({options.length})
        </button>
        <button
          onClick={() => setActiveTab('flow')}
          className={`px-4 py-2 font-medium text-sm border-b-2 transition-colors ${activeTab === 'flow'
            ? 'border-blue-500 text-blue-600'
            : 'border-transparent text-gray-500 hover:text-gray-700'
            }`}
        >
          <Settings size={16} className="inline mr-1" />
          Flujo Visual
        </button>
        <button
          onClick={() => setActiveTab('analytics')}
          className={`px-4 py-2 font-medium text-sm border-b-2 transition-colors ${activeTab === 'analytics'
            ? 'border-blue-500 text-blue-600'
            : 'border-transparent text-gray-500 hover:text-gray-700'
            }`}
        >
          <BarChart3 size={16} className="inline mr-1" />
          Analíticas
        </button>
      </div>

      {/* Contenido de las pestañas */}
      {activeTab === 'nodes' && (
        <div>
          <div className="flex justify-between items-center mb-4">
            <h2 className="text-xl font-semibold text-gray-800">Gestión de Nodos</h2>
            <button
              onClick={() => {
                setEditingItem(null);
                setShowForm(true);
              }}
              className="px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 transition-colors"
            >
              <Plus size={16} className="inline mr-1" />
              Nuevo Nodo
            </button>
          </div>

          <div className="grid gap-4">
            {nodes.map(node => (
              <div key={node.id} className="bg-white rounded-lg shadow-md p-4 border-l-4 border-blue-500">
                <div className="flex justify-between items-start">
                  <div className="flex-1">
                    <div className="flex items-center space-x-2 mb-2">
                      <span className="font-mono text-sm bg-gray-100 px-2 py-1 rounded">{node.id}</span>
                      <span className={`text-xs px-2 py-1 rounded-full ${node.type === 'message' ? 'bg-green-100 text-green-800' :
                        node.type === 'options' ? 'bg-blue-100 text-blue-800' :
                          node.type === 'form' ? 'bg-yellow-100 text-yellow-800' :
                            'bg-purple-100 text-purple-800'
                        }`}>
                        {node.type}
                      </span>
                      {!node.is_active && <span className="text-xs bg-red-100 text-red-800 px-2 py-1 rounded-full">Inactivo</span>}
                    </div>
                    <p className="text-gray-700 mb-2 whitespace-pre-line">{node.content}</p>
                    <div className="text-xs text-gray-500">
                      Opciones disponibles: {getNodeOptions(node.id).length}
                    </div>
                  </div>
                  <div className="flex space-x-2 ml-4">
                    <button
                      onClick={() => {
                        setEditingItem(node);
                        setShowForm(true);
                      }}
                      className="p-2 text-gray-600 hover:text-blue-600 hover:bg-blue-50 rounded"
                    >
                      <Edit2 size={16} />
                    </button>
                    <button
                      onClick={() => handleDeleteNode(node.id)}
                      className="p-2 text-gray-600 hover:text-red-600 hover:bg-red-50 rounded"
                    >
                      <Trash2 size={16} />
                    </button>
                  </div>
                </div>

                {/* Mostrar opciones del nodo */}
                {getNodeOptions(node.id).length > 0 && (
                  <div className="mt-3 pt-3 border-t border-gray-200">
                    <h4 className="text-sm font-medium text-gray-700 mb-2">Opciones:</h4>
                    <div className="space-y-1">
                      {getNodeOptions(node.id).map(option => (
                        <div key={option.id} className="flex items-center text-sm text-gray-600">
                          <span className="mr-2">{option.order_position}.</span>
                          <span className="flex-1">{option.text}</span>
                          {option.next_node_id && (
                            <div className="flex items-center text-xs text-blue-600">
                              <ArrowRight size={12} className="mr-1" />
                              {option.next_node_id}
                            </div>
                          )}
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>
      )}

      {activeTab === 'options' && (
        <div>
          <div className="flex justify-between items-center mb-4">
            <h2 className="text-xl font-semibold text-gray-800">Gestión de Opciones</h2>
            <button
              onClick={() => {
                setEditingItem(null);
                setShowForm(true);
              }}
              className="px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 transition-colors"
            >
              <Plus size={16} className="inline mr-1" />
              Nueva Opción
            </button>
          </div>

          <div className="bg-white rounded-lg shadow-md overflow-hidden">
            <table className="w-full">
              <thead className="bg-gray-50">
                <tr>
                  <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">ID</th>
                  <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Nodo Padre</th>
                  <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Texto</th>
                  <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Siguiente</th>
                  <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Acción</th>
                  <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Orden</th>
                  <th className="px-4 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">Acciones</th>
                </tr>
              </thead>
              <tbody className="bg-white divide-y divide-gray-200">
                {options.map(option => (
                  <tr key={option.id} className={!option.is_active ? 'opacity-50' : ''}>
                    <td className="px-4 py-4 whitespace-nowrap text-sm font-mono text-gray-900">{option.id}</td>
                    <td className="px-4 py-4 whitespace-nowrap text-sm text-gray-700">{option.node_id}</td>
                    <td className="px-4 py-4 text-sm text-gray-700 max-w-xs truncate">{option.text}</td>
                    <td className="px-4 py-4 whitespace-nowrap text-sm text-gray-700">{option.next_node_id || '-'}</td>
                    <td className="px-4 py-4 whitespace-nowrap">
                      <span className={`inline-flex px-2 py-1 text-xs rounded-full ${option.action_type === 'navigate' ? 'bg-blue-100 text-blue-800' :
                        option.action_type === 'submit' ? 'bg-green-100 text-green-800' :
                          option.action_type === 'restart' ? 'bg-yellow-100 text-yellow-800' :
                            'bg-red-100 text-red-800'
                        }`}>
                        {option.action_type}
                      </span>
                    </td>
                    <td className="px-4 py-4 whitespace-nowrap text-sm text-gray-700">{option.order_position}</td>
                    <td className="px-4 py-4 whitespace-nowrap text-right text-sm font-medium">
                      <div className="flex justify-end space-x-2">
                        <button
                          onClick={() => {
                            setEditingItem(option);
                            setShowForm(true);
                          }}
                          className="text-gray-600 hover:text-blue-600"
                        >
                          <Edit2 size={16} />
                        </button>
                        <button
                          onClick={() => handleDeleteOption(option.id)}
                          className="text-gray-600 hover:text-red-600"
                        >
                          <Trash2 size={16} />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {activeTab === 'flow' && (
        <div>
          <h2 className="text-xl font-semibold text-gray-800 mb-4">Visualización del Flujo</h2>
          <div className="bg-white rounded-lg shadow-md p-6">
            <div className="space-y-6">
              {nodes.map(node => (
                <div key={node.id} className="border border-gray-200 rounded-lg p-4">
                  <div className="flex items-center space-x-2 mb-3">
                    <div className="w-3 h-3 bg-blue-500 rounded-full"></div>
                    <span className="font-mono text-sm font-medium">{node.id}</span>
                    <span className="text-xs text-gray-500">({node.type})</span>
                  </div>
                  <p className="text-gray-700 mb-3 text-sm">{node.content}</p>

                  {getNodeOptions(node.id).length > 0 && (
                    <div className="ml-4 space-y-2">
                      {getNodeOptions(node.id).map(option => (
                        <div key={option.id} className="flex items-center space-x-3 p-2 bg-gray-50 rounded">
                          <span className="w-6 h-6 bg-gray-300 text-gray-700 rounded-full text-xs flex items-center justify-center">
                            {option.order_position}
                          </span>
                          <span className="flex-1 text-sm">{option.text}</span>
                          {option.next_node_id && (
                            <div className="flex items-center text-xs text-blue-600">
                              <ArrowRight size={14} className="mr-1" />
                              <span className="bg-blue-100 px-2 py-1 rounded">{option.next_node_id}</span>
                            </div>
                          )}
                          {option.action_data?.url && (
                            <div className="text-xs text-green-600">
                              → {option.action_data.url}
                            </div>
                          )}
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {activeTab === 'analytics' && (
        <div>
          <h2 className="text-xl font-semibold text-gray-800 mb-4">Panel de Analíticas</h2>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
            <div className="bg-white rounded-lg shadow-md p-4">
              <div className="flex items-center">
                <div className="p-2 bg-blue-100 rounded-lg">
                  <MessageCircle className="text-blue-600" size={20} />
                </div>
                <div className="ml-3">
                  <p className="text-sm font-medium text-gray-600">Total Nodos</p>
                  <p className="text-2xl font-semibold text-gray-900">{nodes.length}</p>
                </div>
              </div>
            </div>

            <div className="bg-white rounded-lg shadow-md p-4">
              <div className="flex items-center">
                <div className="p-2 bg-green-100 rounded-lg">
                  <List className="text-green-600" size={20} />
                </div>
                <div className="ml-3">
                  <p className="text-sm font-medium text-gray-600">Total Opciones</p>
                  <p className="text-2xl font-semibold text-gray-900">{options.length}</p>
                </div>
              </div>
            </div>

            <div className="bg-white rounded-lg shadow-md p-4">
              <div className="flex items-center">
                <div className="p-2 bg-yellow-100 rounded-lg">
                  <Settings className="text-yellow-600" size={20} />
                </div>
                <div className="ml-3">
                  <p className="text-sm font-medium text-gray-600">Nodos Activos</p>
                  <p className="text-2xl font-semibold text-gray-900">{nodes.filter(n => n.is_active).length}</p>
                </div>
              </div>
            </div>

            <div className="bg-white rounded-lg shadow-md p-4">
              <div className="flex items-center">
                <div className="p-2 bg-purple-100 rounded-lg">
                  <BarChart3 className="text-purple-600" size={20} />
                </div>
                <div className="ml-3">
                  <p className="text-sm font-medium text-gray-600">Opciones Activas</p>
                  <p className="text-2xl font-semibold text-gray-900">{options.filter(o => o.is_active).length}</p>
                </div>
              </div>
            </div>
          </div>

          <div className="bg-white rounded-lg shadow-md p-6">
            <h3 className="text-lg font-semibold text-gray-800 mb-4">Resumen de Configuración</h3>
            <div className="space-y-4">
              <div>
                <h4 className="font-medium text-gray-700 mb-2">Distribución por Tipo de Nodo</h4>
                <div className="flex flex-wrap gap-2">
                  {['message', 'options', 'form', 'redirect'].map(type => {
                    const count = nodes.filter(n => n.type === type).length;
                    return (
                      <span key={type} className={`px-3 py-1 text-sm rounded-full ${type === 'message' ? 'bg-green-100 text-green-800' :
                        type === 'options' ? 'bg-blue-100 text-blue-800' :
                          type === 'form' ? 'bg-yellow-100 text-yellow-800' :
                            'bg-purple-100 text-purple-800'
                        }`}>
                        {type}: {count}
                      </span>
                    );
                  })}
                </div>
              </div>

              <div>
                <h4 className="font-medium text-gray-700 mb-2">Distribución por Tipo de Acción</h4>
                <div className="flex flex-wrap gap-2">
                  {['navigate', 'submit', 'restart', 'end'].map(actionType => {
                    const count = options.filter(o => o.action_type === actionType).length;
                    return (
                      <span key={actionType} className={`px-3 py-1 text-sm rounded-full ${actionType === 'navigate' ? 'bg-blue-100 text-blue-800' :
                        actionType === 'submit' ? 'bg-green-100 text-green-800' :
                          actionType === 'restart' ? 'bg-yellow-100 text-yellow-800' :
                            'bg-red-100 text-red-800'
                        }`}>
                        {actionType}: {count}
                      </span>
                    );
                  })}
                </div>
              </div>

              <div>
                <h4 className="font-medium text-gray-700 mb-2">Nodos con Más Opciones</h4>
                <div className="space-y-2">
                  {nodes
                    .map(node => ({
                      ...node,
                      optionCount: getNodeOptions(node.id).length
                    }))
                    .sort((a, b) => b.optionCount - a.optionCount)
                    .slice(0, 5)
                    .map(node => (
                      <div key={node.id} className="flex justify-between items-center p-2 bg-gray-50 rounded">
                        <span className="font-mono text-sm">{node.id}</span>
                        <span className="text-sm text-gray-600">{node.optionCount} opciones</span>
                      </div>
                    ))}
                </div>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Formularios modales */}
      {showForm && activeTab === 'nodes' && (
        <NodeForm
          node={editingItem}
          onSave={handleSaveNode}
          onCancel={() => {
            setShowForm(false);
            setEditingItem(null);
          }}
        />
      )}

      {showForm && activeTab === 'options' && (
        <OptionForm
          option={editingItem}
          onSave={handleSaveOption}
          onCancel={() => {
            setShowForm(false);
            setEditingItem(null);
          }}
        />
      )}

      {/* Diálogo de confirmación de eliminación personalizado */}
      {showDeleteDialog && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 max-w-md w-full mx-4">
            <h3 className="text-lg font-semibold text-gray-800 mb-4">
              Confirmar Eliminación
            </h3>
            <p className="text-gray-600 mb-6">
              {deleteTarget?.type === 'node'
                ? '¿Estás seguro de que quieres eliminar este nodo? También se eliminarán sus opciones asociadas.'
                : '¿Estás seguro de que quieres eliminar esta opción?'
              }
            </p>
            <div className="flex justify-end space-x-3">
              <button
                onClick={() => {
                  setShowDeleteDialog(false);
                  setDeleteTarget(null);
                }}
                className="px-4 py-2 text-gray-600 bg-gray-100 rounded-md hover:bg-gray-200 transition-colors"
              >
                Cancelar
              </button>
              <button
                onClick={confirmDelete}
                className="px-4 py-2 bg-red-600 text-white rounded-md hover:bg-red-700 transition-colors"
              >
                Eliminar
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ChatbotAdmin;

// src/components/ChatbotDecisionTree.tsx

import React, { useState, useEffect, useRef } from 'react';
import { MessageCircle, X, RotateCcw } from 'lucide-react';

// Interfaces para el sistema de Decision Tree
interface ChatbotNode {
  id: string;
  type: 'message' | 'options' | 'form' | 'redirect';
  content: string;
  metadata?: {
    delay?: number;
    typing_indicator?: boolean;
    analytics_event?: string;
  };
}

interface ChatbotOption {
  id: string;
  node_id: string;
  text: string;
  next_node_id: string | null;
  action_type: 'navigate' | 'submit' | 'restart' | 'end';
  action_data?: {
    url?: string;
    form_id?: string;
    analytics_event?: string;
  };
  order_position: number;
}

interface Message {
  id: string;
  type: 'bot' | 'user';
  content: string;
  timestamp: Date;
  isTyping?: boolean;
}

interface ChatbotState {
  isOpen: boolean;
  currentNodeId: string;
  messages: Message[];
  isLoading: boolean;
  conversationId: string;
}


const ChatbotDecisionTree: React.FC = () => {
  // Estado principal del chatbot
  const [state, setState] = useState<ChatbotState>({
    isOpen: false,
    currentNodeId: 'welcome',
    messages: [],
    isLoading: false,
    conversationId: ''
  });

  // Datos del chatbot (desde la API)
  const [chatbotData, setChatbotData] = useState<{ nodes: ChatbotNode[]; options: ChatbotOption[] }>({ nodes: [], options: [] });

  // Cargar nodos y opciones desde el endpoint PHP
  useEffect(() => {
    fetch('/api/endpoints/chatbot_decision_tree.php')
      .then(res => res.json())
      .then(data => {
        setChatbotData({
          nodes: data.nodes || [],
          options: data.options || []
        });
      });
  }, []);

  // Estado de carga de datos
  //

  // Referencias
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const chatContainerRef = useRef<HTMLDivElement>(null);

  // URL base de la API
  //

  // Generar ID único para la conversación
  const generateConversationId = () => {
    return `conv_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  };

  // Obtener opciones para el nodo actual
  const getCurrentOptions = (): ChatbotOption[] => {
    return chatbotData.options
      .filter(option => option.node_id === state.currentNodeId)
      .sort((a, b) => a.order_position - b.order_position);
  };

  // Scroll automático al final de los mensajes
  const scrollToBottom = () => {
    setTimeout(() => {
      messagesEndRef.current?.scrollIntoView({
        behavior: 'smooth',
        block: 'end'
      });
    }, 100);
  };

  // Efecto para scroll automático
  useEffect(() => {
    if (state.isOpen) {
      scrollToBottom();
    }
  }, [state.messages, state.isOpen]);

  // Inicializar conversación
  const initializeConversation = async () => {
    const conversationId = generateConversationId();

    setState(prev => ({
      ...prev,
      conversationId,
      messages: [],
      currentNodeId: 'welcome',
      isLoading: true
    }));

    // Simular carga y mostrar mensaje de bienvenida
    setTimeout(() => {
      const welcomeNode = chatbotData.nodes.find(node => node.id === 'welcome');
      if (welcomeNode) {
        addBotMessage(welcomeNode.content, welcomeNode.metadata);
      }

      setState(prev => ({
        ...prev,
        isLoading: false
      }));
    }, 500);

    // Analytics del inicio de conversación
    trackAnalyticsEvent('chatbot_conversation_started', {
      conversation_id: conversationId,
      timestamp: new Date().toISOString()
    });
  };

  // Agregar mensaje del bot con efectos de typing
  const addBotMessage = (content: string, metadata?: ChatbotNode['metadata']) => {
    const messageId = `msg_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

    // Mostrar indicador de typing si está configurado
    if (metadata?.typing_indicator) {
      setState(prev => ({
        ...prev,
        messages: [...prev.messages, {
          id: `typing_${messageId}`,
          type: 'bot' as const,
          content: '',
          timestamp: new Date(),
          isTyping: true
        }]
      }));
    }

    // Agregar mensaje real después del delay
    setTimeout(() => {
      setState(prev => ({
        ...prev,
        messages: [
          ...prev.messages.filter(msg => !msg.isTyping),
          {
            id: messageId,
            type: 'bot' as const,
            content,
            timestamp: new Date()
          }
        ]
      }));

      // Track analytics si está configurado
      if (metadata?.analytics_event) {
        trackAnalyticsEvent(metadata.analytics_event, {
          node_id: state.currentNodeId,
          conversation_id: state.conversationId
        });
      }
    }, metadata?.delay || 0);
  };

  // Agregar mensaje del usuario
  const addUserMessage = (content: string) => {
    const messageId = `msg_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

    setState(prev => ({
      ...prev,
      messages: [...prev.messages, {
        id: messageId,
        type: 'user' as const,
        content,
        timestamp: new Date()
      }]
    }));
  };

  // Manejar selección de opción
  const handleOptionSelect = async (option: ChatbotOption) => {
    // Agregar respuesta del usuario
    addUserMessage(option.text);

    // Track analytics
    if (option.action_data?.analytics_event) {
      trackAnalyticsEvent(option.action_data.analytics_event, {
        option_id: option.id,
        option_text: option.text,
        current_node: state.currentNodeId,
        conversation_id: state.conversationId
      });
    }

    // Procesar acción
    switch (option.action_type) {
      case 'navigate':
        if (option.action_data?.url) {
          // Redirección externa
          setTimeout(() => {
            window.location.href = option.action_data!.url!;
          }, 1000);

          addBotMessage('Te estoy redirigiendo... 🚀', { delay: 500 });
        } else if (option.next_node_id) {
          // Navegación interna
          await navigateToNode(option.next_node_id);
        }
        break;

      case 'restart':
        await restartConversation();
        break;

      case 'end':
        addBotMessage('¡Gracias por usar nuestro chatbot! Si necesitas más ayuda, no dudes en contactarnos. 😊', { delay: 800 });
        break;

      default:
        if (option.next_node_id) {
          await navigateToNode(option.next_node_id);
        }
        break;
    }
  };

  // Navegar a un nodo específico
  const navigateToNode = async (nodeId: string) => {
    const targetNode = chatbotData.nodes.find(node => node.id === nodeId);

    if (targetNode) {
      setState(prev => ({
        ...prev,
        currentNodeId: nodeId
      }));

      // Mostrar mensaje del nodo
      addBotMessage(targetNode.content, targetNode.metadata);
    }
  };

  // Reiniciar conversación
  const restartConversation = async () => {
    setState(prev => ({
      ...prev,
      messages: [],
      currentNodeId: 'welcome',
      isLoading: true
    }));

    setTimeout(() => {
      const welcomeNode = chatbotData.nodes.find(node => node.id === 'welcome');
      if (welcomeNode) {
        addBotMessage(welcomeNode.content, welcomeNode.metadata);
      }

      setState(prev => ({
        ...prev,
        isLoading: false
      }));
    }, 800);
  };

  // Track de eventos de analytics
  const trackAnalyticsEvent = async (eventName: string, eventData: Record<string, any>) => {
    try {
      await fetch('/api/endpoints/chatbot_analytics.php', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          event_name: eventName,
          event_data: eventData,
          conversation_id: state.conversationId
        })
      });
    } catch (e) {
      // Silenciar error en frontend
    }
  };

  // Abrir/cerrar chatbot
  const toggleChatbot = () => {
    if (!state.isOpen) {
      setState(prev => ({ ...prev, isOpen: true }));
      if (state.messages.length === 0) {
        initializeConversation();
      }
    } else {
      setState(prev => ({ ...prev, isOpen: false }));
    }
  };

  // Renderizar mensaje con formato
  const renderMessageContent = (content: string) => {
    return content.split('\n').map((line, index) => (
      <span key={index}>
        {line}
        {index < content.split('\n').length - 1 && <br />}
      </span>
    ));
  };

  return (
    <div className="fixed bottom-4 right-4 z-50 chatbot-fixed">
      {/* Botón del chatbot */}
      {!state.isOpen && (
        <button
          onClick={toggleChatbot}
          className="bg-[#FF4785] hover:bg-[#FF4785]/90 text-white rounded-full p-4 shadow-lg transition-all duration-300 hover:scale-110 group"
          aria-label="Abrir chatbot"
        >
          <MessageCircle size={24} className="group-hover:scale-110 transition-transform" />

          {/* Indicador de mensaje nuevo (opcional) */}
          <div className="absolute -top-1 -right-1 bg-red-500 text-white text-xs rounded-full w-5 h-5 flex items-center justify-center animate-pulse">
            💬
          </div>

          {/* Mensaje de error si lo hay */}

        </button>
      )}

      {/* Ventana del chatbot */}
      {state.isOpen && (
        <div className="bg-white rounded-lg shadow-2xl w-80 h-96 flex flex-col border border-gray-200">
          {/* Header */}
          <div className="bg-[#FF4785] text-white p-4 rounded-t-lg flex items-center justify-between">
            <div className="flex items-center space-x-2">
              <div className="w-8 h-8 bg-white/20 rounded-full flex items-center justify-center">
                💼
              </div>
              <div>
                <h3 className="font-semibold text-sm">Asistente Virtual</h3>
                <p className="text-xs opacity-90">
                  Bubble of Talents
                </p>
              </div>
            </div>

            <div className="flex items-center space-x-2">
              <button
                onClick={restartConversation}
                className="p-1 hover:bg-white/20 rounded-full transition-colors"
                title="Reiniciar conversación"
              >
                <RotateCcw size={16} />
              </button>
              <button
                onClick={toggleChatbot}
                className="p-1 hover:bg-white/20 rounded-full transition-colors"
                aria-label="Cerrar chatbot"
              >
                <X size={16} />
              </button>
            </div>
          </div>

          {/* Mensajes */}
          <div
            ref={chatContainerRef}
            className="flex-1 overflow-y-auto p-4 space-y-3"
          >
            {state.messages.map((message) => (
              <div
                key={message.id}
                className={`flex ${message.type === 'user' ? 'justify-end' : 'justify-start'}`}
              >
                <div
                  className={`max-w-[80%] p-3 rounded-lg text-sm ${message.type === 'user'
                    ? 'bg-[#FF4785] text-white rounded-br-none'
                    : 'bg-gray-100 text-gray-800 rounded-bl-none'
                    }`}
                >
                  {message.isTyping ? (
                    <div className="flex space-x-1">
                      <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce"></div>
                      <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0.1s' }}></div>
                      <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0.2s' }}></div>
                    </div>
                  ) : (
                    renderMessageContent(message.content)
                  )}
                </div>
              </div>
            ))}

            {/* Opciones del nodo actual */}
            {!state.isLoading && !state.messages.some(m => m.isTyping) && (
              <div className="space-y-2 mt-4">
                {getCurrentOptions().map((option) => (
                  <button
                    key={option.id}
                    onClick={() => handleOptionSelect(option)}
                    className="w-full text-left p-3 border border-gray-200 rounded-lg hover:border-[#FF4785] hover:bg-[#FF4785]/5 transition-all duration-200 text-sm group"
                  >
                    <span className="group-hover:text-[#FF4785] transition-colors">
                      {option.text}
                    </span>
                  </button>
                ))}
              </div>
            )}

            <div ref={messagesEndRef} />
          </div>

          {/* Footer con info */}
          <div className="border-t border-gray-200 p-2 text-center">
            <p className="text-xs text-gray-500">
              Powered by Bubble of Talents
            </p>
          </div>
        </div>
      )}
    </div>
  );
};

export default ChatbotDecisionTree;

import React from 'react';
import { FaUsers, FaLightbulb, FaHandsHelping } from 'react-icons/fa';

interface CultureCardProps {
  iconName?: string | null;
  title: string;
  desc: string;
}

const iconComponents: Record<string, React.ComponentType<any>> = {
  FaUsers,
  FaLightbulb,
  FaHandsHelping,
};

export const CultureCard: React.FC<CultureCardProps> = ({ iconName, title, desc }) => {
  const [mousePos, setMousePos] = React.useState({ x: 50, y: 50 });
  const [isHover, setIsHover] = React.useState(false);

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    const rect = e.currentTarget.getBoundingClientRect();
    const x = ((e.clientX - rect.left) / rect.width) * 100;
    const y = ((e.clientY - rect.top) / rect.height) * 100;
    setMousePos({ x, y });
    setIsHover(true);
  };

  const handleMouseLeave = () => {
    setMousePos({ x: 50, y: 50 });
    setIsHover(false);
  };

  return (
    <div
      className="text-center p-6 rounded-lg shadow-sm transition-shadow border border-gray-100 relative overflow-visible cursor-pointer"
      style={{
        background: 'rgba(255,71,133,0.65)',
        boxShadow: isHover
          ? '0 8px 32px 0 rgba(31,38,135,0.18), 0 8px 24px 8px rgba(255,71,133,0.25), 0 16px 40px 0 rgba(47,47,47,0.18)'
          : '0 8px 32px 0 rgba(31, 38, 135, 0.18), 0 4px 16px 0 rgba(255,71,133,0.10)',
        backdropFilter: 'blur(16px) saturate(180%)',
        WebkitBackdropFilter: 'blur(16px) saturate(180%)',
        borderBottom: '8px solid rgba(255,71,133,0.25)',
        borderRight: '4px solid rgba(255,71,133,0.18)',
        transform: isHover ? 'translateY(-6px) scale3d(1.03,1.03,1.03)' : 'none',
        transition: 'box-shadow 0.3s, transform 0.3s',
      }}
      onMouseMove={handleMouseMove}
      onMouseLeave={handleMouseLeave}
    >
      <div
        className="pointer-events-none absolute left-0 top-0 w-full h-full z-10 rounded-lg"
        style={{
          background: `radial-gradient(circle at ${mousePos.x}% ${mousePos.y}%, rgba(0,0,0,0.18) 0%, rgba(0,0,0,0.10) 40%, transparent 80%)`,
          opacity: 0.7,
          transition: 'opacity 0.3s',
        }}
      />
      {iconName && iconComponents[iconName] &&
        React.createElement(iconComponents[iconName], {
          size: 32,
          className: 'mx-auto mb-4 text-white'
        })
      }
      <h3 className="text-xl font-semibold mb-3 text-white">{title}</h3>
      <p className="text-white">{desc}</p>
    </div>
  );
};

import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { env } from '../config/env';
import { parseCv, confirmCv } from '../lib/cvApi';
import { useCvForm } from '../contexts/CvFormContext';
import { CvFormData, cvTemplate, validateMinimumData, ExperienciaLaboral, Educacion, Proyecto } from '../domain/cvSchema';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from './ui/dialog';
import { Button } from './ui/button';
import { Input } from './ui/input';
import { Textarea } from './ui/textarea';
import { Label } from './ui/label';
import { Separator } from './ui/separator';
import { Upload, Loader2, AlertTriangle, CheckCircle2, Plus, X, Info } from 'lucide-react';

/**
 * CvIntake
 * Componente orquestador: subida PDF -> parse AI -> pre-relleno -> edición manual -> confirmación.
 * Requisitos cubiertos:
 * - Uploader (PDF) + botón "Procesar CV".
 * - Botón "Cargar manualmente" forza estado manual.
 * - Modal (CvReviewModal) reutiliza estado global (context) y muestra formulario único.
 * - Manejo de 200 success (prefill) / 422 PARSE_FAILED (cambio a manual con alerta) / otros errores.
 * - Validación básica cliente (email, fechas coherentes inicio <= fin, mínimos).
 * - Confirmación POST JSON a /api/cv/confirm (placeholder backend si no existe aún).
 * - Cancelar guarda borrador (localStorage) y cierra.
 */

interface CvIntakeProps {
  apiBase?: string;              // Base URL backend (por defecto /api)
  onConfirmed?: (data: CvFormData) => void; // Callback tras confirmación exitosa
  storageKey?: string;           // Clave localStorage para borrador
}

// Clave de autosave solicitada
const DRAFT_KEY_DEFAULT = 'cv-intake-draft-v1';

// --- Validación extendida (fechas coherentes) ---
function extraValidate(data: CvFormData): string[] {
  const errs: string[] = [];
  // Experiencias
  data.puestos_anteriores?.forEach((p, idx) => {
    if (p.fecha_inicio && p.fecha_fin && p.fecha_inicio > p.fecha_fin) {
      errs.push(`Experiencia #${idx + 1}: fecha_inicio posterior a fecha_fin`);
    }
  });
  // Educación
  data.educacion?.forEach((e, idx) => {
    if (e.fecha_inicio && e.fecha_fin && e.fecha_inicio > e.fecha_fin) {
      errs.push(`Educación #${idx + 1}: fecha_inicio posterior a fecha_fin`);
    }
  });
  return errs;
}

export const CvIntake: React.FC<CvIntakeProps> = ({ apiBase = env.API_BASE_URL, onConfirmed, storageKey = DRAFT_KEY_DEFAULT }) => {
  const { state, setFile, setFormState, prefillFromAI, switchToManual, setErrors, setFormData, updateField } = useCvForm();
  const { state: flowState, data: formData, errors, originalFile, isLoading } = state;

  const [localFile, setLocalFile] = useState<File | null>(null);
  const [modalOpen, setModalOpen] = useState(false);
  const [alertMsg, setAlertMsg] = useState<string | null>(null);
  const [globalError, setGlobalError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);

  const manualOnly = (import.meta as Record<string, unknown>).env?.VITE_CV_ALLOW_MANUAL_ONLY === 'true';

  // Forzar modo manual si flag activo en montaje y no hay borrador cargado aún
  useEffect(() => {
    if (manualOnly && flowState === 'idle') {
      switchToManual();
      setModalOpen(true);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [manualOnly]);

  // Cargar borrador si existe al montar (sin sobrescribir si ya hay datos AI)
  useEffect(() => {
    if (flowState === 'idle') {
      try {
        const raw = localStorage.getItem(storageKey);
        if (raw) {
          const draft = JSON.parse(raw) as CvFormData;
          setFormData({ ...cvTemplate, ...draft });
          setFormState('manual');
          setModalOpen(true);
        }
      } catch { }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Selección archivo
  const handleFileChange = (file: File | undefined) => {
    if (!file) return;
    setLocalFile(file);
  };

  const processFile = async () => {
    if (!localFile) return;
    setErrors([]);
    setGlobalError(null);
    setAlertMsg(null);
    setFormState('uploading');
    // Guardamos en contexto también (opcional)
    setFile(localFile);

    // Validaciones rápidas cliente
    if (localFile.type !== 'application/pdf') {
      setFormState('idle');
      setGlobalError('Solo se aceptan archivos PDF (application/pdf)');
      return;
    }
    if (localFile.size > 5 * 1024 * 1024) {
      setFormState('idle');
      setGlobalError('El archivo excede 5MB');
      return;
    }

    try {
      console.log('[CvIntake] Iniciando parseo CV', { name: localFile.name, size: localFile.size, type: localFile.type });
      setFormState('parsing');
      const { status, json: payload } = await parseCv(localFile);
      console.log('[CvIntake] Respuesta parse', { status, payload });

      if (status === 200 && payload?.success) {
        prefillFromAI(payload.data || {});
        setModalOpen(true);
        return;
      }
      if (status === 422 && payload?.error?.code === 'PARSE_FAILED') {
        switchToManual();
        setAlertMsg('El PDF no fue legible. Completa la información manualmente.');
        setModalOpen(true);
        return;
      }
      // Otros errores
      setFormState('idle');
      setGlobalError(payload?.error?.message || 'Error inesperado procesando el CV');
    } catch (e) {
      console.error('[CvIntake] Error de red/fetch parse', e);
      setFormState('idle');
      setGlobalError('Fallo de red o servidor no disponible');
    }
  };

  const openManual = () => {
    switchToManual();
    setModalOpen(true);
  };

  const retryAnotherPDF = () => {
    // Reset a estado inicial para permitir nuevo parseo
    setErrors([]);
    setGlobalError(null);
    setAlertMsg(null);
    setFormData(cvTemplate);
    try { localStorage.removeItem(storageKey); } catch { }
    setModalOpen(false);
    setLocalFile(null);
    setFormState('idle');
  };

  const closeModal = () => {
    // Guardar borrador automático al cerrar
    try { localStorage.setItem(storageKey, JSON.stringify(formData)); } catch { }
    setModalOpen(false);
  };

  const clearDraft = () => {
    try { localStorage.removeItem(storageKey); } catch { }
  };

  const handleConfirm = async () => {
    setErrors([]);
    setGlobalError(null);

    const minErrors = validateMinimumData(formData);
    const extra = extraValidate(formData);
    const combined = [...minErrors, ...extra];
    if (combined.length) { setErrors(combined); return; }

    setSaving(true);
    setFormState('saving');
    try {
      const { status, json: payload } = await confirmCv(formData);
      if (status >= 200 && status < 300 && payload?.success !== false) {
        clearDraft();
        setModalOpen(false);
        if (onConfirmed) onConfirmed(formData);
      } else {
        setGlobalError(payload?.error?.message || 'Error al confirmar el CV');
        setFormState('manual'); // vuelve para seguir editando
      }
    } catch (e) {
      setGlobalError('Error de red confirmando CV');
      setFormState('manual');
    } finally {
      setSaving(false);
    }
  };

  // Autosave continuo cuando se edita (manual o ready) y modal abierto
  useEffect(() => {
    if (modalOpen && (flowState === 'manual' || flowState === 'ready')) {
      try { localStorage.setItem(storageKey, JSON.stringify(formData)); } catch { }
    }
  }, [formData, modalOpen, flowState, storageKey]);

  // --- Formulario dinámico ---
  const updateSimpleField = (field: keyof CvFormData, value: string | number | boolean | string[] | undefined) => {
    updateField(field, value);
  };

  function arrayHelpersString(field: keyof CvFormData) {
    const arr = (formData[field] as string[]) || [];
    return {
      items: arr,
      add: (item: string) => updateField(field, [...arr, item]),
      remove: (idx: number) => updateField(field, arr.filter((_, i) => i !== idx)),
      update: (idx: number, item: string) => updateField(field, arr.map((v, i) => i === idx ? item : v))
    };
  }
  function arrayHelpersExp(field: keyof CvFormData) {
    const arr = (formData[field] as ExperienciaLaboral[]) || [];
    return {
      items: arr,
      add: (item: ExperienciaLaboral) => updateField(field, [...arr, item]),
      remove: (idx: number) => updateField(field, arr.filter((_, i) => i !== idx)),
      update: (idx: number, item: ExperienciaLaboral) => updateField(field, arr.map((v, i) => i === idx ? item : v))
    };
  }
  function arrayHelpersEdu(field: keyof CvFormData) {
    const arr = (formData[field] as Educacion[]) || [];
    return {
      items: arr,
      add: (item: Educacion) => updateField(field, [...arr, item]),
      remove: (idx: number) => updateField(field, arr.filter((_, i) => i !== idx)),
      update: (idx: number, item: Educacion) => updateField(field, arr.map((v, i) => i === idx ? item : v))
    };
  }
  function arrayHelpersProj(field: keyof CvFormData) {
    const arr = (formData[field] as Proyecto[]) || [];
    return {
      items: arr,
      add: (item: Proyecto) => updateField(field, [...arr, item]),
      remove: (idx: number) => updateField(field, arr.filter((_, i) => i !== idx)),
      update: (idx: number, item: Proyecto) => updateField(field, arr.map((v, i) => i === idx ? item : v))
    };
  }

  const exp = arrayHelpersExp('puestos_anteriores');
  const edu = arrayHelpersEdu('educacion');
  const cert = arrayHelpersString('certificaciones');
  const proj = arrayHelpersProj('proyectos');

  // Render helpers
  const renderBasicInput = (label: string, field: keyof CvFormData, type: string = 'text') => (
    <div className="space-y-1">
      <Label className="text-xs font-medium text-gray-700">{label}</Label>
      <Input
        type={type}
        className="text-xs"
        value={(formData[field] as string) || ''}
        onChange={(e) => updateSimpleField(field, e.target.value)}
      />
    </div>
  );

  const renderExperiences = () => (
    <div className="space-y-3" role="group" aria-labelledby="exp-label">
      <div className="flex items-center justify-between">
        <h4 id="exp-label" className="text-xs font-semibold flex items-center gap-1">Experiencia Laboral
          <span className="inline-flex items-center" aria-hidden="true" title="Añade puestos anteriores: título, empresa, fechas y breve descripción." aria-label="Ayuda Experiencia Laboral">
            <Info className="h-3 w-3 text-gray-400" />
          </span>
        </h4>
        <Button size="sm" variant="ghost" onClick={() => exp.add({ puesto: '', empresa: '', fecha_inicio: '', fecha_fin: '', descripcion: '' })}><Plus className="h-3 w-3" /></Button>
      </div>
      <div role="list" aria-label="Lista de experiencias">
        {exp.items.map((p, i) => (
          <div key={i} role="listitem" className="p-2 border rounded space-y-2">
            <div className="flex justify-between items-center">
              <span className="text-xs font-medium">Puesto #{i + 1}</span>
              <Button size="sm" variant="ghost" onClick={() => exp.remove(i)}><X className="h-3 w-3" /></Button>
            </div>
            <div className="grid grid-cols-3 gap-2">
              <Input placeholder="Puesto" className="text-xs" value={p.puesto} onChange={e => exp.update(i, { ...p, puesto: e.target.value })} />
              <Input placeholder="Empresa" className="text-xs" value={p.empresa} onChange={e => exp.update(i, { ...p, empresa: e.target.value })} />
              <Input type="date" className="text-xs" value={p.fecha_inicio} onChange={e => exp.update(i, { ...p, fecha_inicio: e.target.value })} />
              <Input type="date" className="text-xs" value={p.fecha_fin} onChange={e => exp.update(i, { ...p, fecha_fin: e.target.value })} />
              <Textarea placeholder="Descripción" className="col-span-3 text-xs min-h-[60px]" value={p.descripcion} onChange={e => exp.update(i, { ...p, descripcion: e.target.value })} />
            </div>
          </div>
        ))}
        {exp.items.length === 0 && <div className="text-xs text-gray-400 italic" role="note">Sin experiencias. Usa + para añadir.</div>}
      </div>
    </div>
  );

  const renderEducation = () => (
    <div className="space-y-3" role="group" aria-labelledby="edu-label">
      <div className="flex items-center justify-between">
        <h4 id="edu-label" className="text-xs font-semibold flex items-center gap-1">Educación
          <span className="inline-flex" aria-hidden="true" title="Añade formaciones: título, institución, fechas y descripción." aria-label="Ayuda Educación">
            <Info className="h-3 w-3 text-gray-400" />
          </span>
        </h4>
        <Button size="sm" variant="ghost" onClick={() => edu.add({ titulo: '', institucion: '', fecha_inicio: '', fecha_fin: '' })}><Plus className="h-3 w-3" /></Button>
      </div>
      <div role="list" aria-label="Lista de educación">
        {edu.items.map((e, i) => (
          <div key={i} role="listitem" className="p-2 border rounded space-y-2">
            <div className="flex justify-between items-center">
              <span className="text-xs font-medium">Educación #{i + 1}</span>
              <Button size="sm" variant="ghost" onClick={() => edu.remove(i)}><X className="h-3 w-3" /></Button>
            </div>
            <div className="grid grid-cols-3 gap-2">
