/**
 * Lazy Loading and Code Splitting Components
 * 
 * Provides React components and utilities for lazy loading and code splitting
 * with enhanced error handling and performance optimization.
 * 
 * @package LazyLoading
 * @author Bubble of Talents Development Team
 * @version 1.0.0
 * @since 2025-01-05
 */

import React, { Suspense, lazy, ComponentType, LazyExoticComponent } from 'react';
import type { ReactNode } from 'react';

/**
 * Enhanced lazy loading with error boundary
 */
export function createLazyComponent<T extends ComponentType<any>>(
    importFn: () => Promise<{ default: T }>,
    fallback?: ReactNode
): LazyExoticComponent<T> {
    const LazyComponent = lazy(async () => {
        try {
            return await importFn();
        } catch (error) {
            console.error('Failed to load component:', error);
            // Return a fallback component in case of error
            return {
                default: (() => (
                    <div className="p-4 text-center text-red-600">
                        Failed to load component. Please refresh the page.
                    </div>
                )) as unknown as T
            };
        }
    });

    // Wrapper component with Suspense
    const WrappedComponent = (props: any) => (
        <Suspense fallback={fallback || <LoadingSpinner />}>
            <LazyComponent {...props} />
        </Suspense>
    );

    return WrappedComponent as LazyExoticComponent<T>;
}

/**
 * Create route-based lazy component
 */
export function createRouteComponent(
    importFn: () => Promise<{ default: ComponentType<any> }>,
    preload: boolean = false
): LazyExoticComponent<ComponentType<any>> {
    if (preload) {
        // Preload after a short delay
        setTimeout(() => {
            importFn().catch(error => {
                console.warn('Failed to preload component:', error);
            });
        }, 100);
    }

    return createLazyComponent(importFn, <RouteLoadingSpinner />);
}

/**
 * Loading spinner component
 */
export function LoadingSpinner(): JSX.Element {
    return (
        <div className="p-4 text-center">
            <div className="inline-block animate-spin rounded-full h-6 w-6 border-b-2 border-blue-600"></div>
            <span className="ml-2 text-gray-600">Loading...</span>
        </div>
    );
}

/**
 * Route loading spinner with full page height
 */
export function RouteLoadingSpinner(): JSX.Element {
    return (
        <div className="flex justify-center items-center h-64">
            <div className="text-center">
                <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600 mx-auto"></div>
                <p className="mt-2 text-gray-600">Loading page...</p>
            </div>
        </div>
    );
}

/**
 * Lazy image component with intersection observer
 */
interface LazyImageProps {
    src: string;
    alt: string;
    className?: string;
    placeholder?: string;
    width?: number;
    height?: number;
}

export function LazyImage({
    src,
    alt,
    className = '',
    placeholder = 'data:image/svg+xml;base64,PHN2ZyB3aWR0aD0iMzIwIiBoZWlnaHQ9IjI0MCIgeG1sbnM9Imh0dHA6Ly93d3cudzMub3JnLzIwMDAvc3ZnIj48cmVjdCB3aWR0aD0iMTAwJSIgaGVpZ2h0PSIxMDAlIiBmaWxsPSIjY2NjIi8+PC9zdmc+',
    width,
    height
}: LazyImageProps): JSX.Element {
    const [imageSrc, setImageSrc] = React.useState(placeholder);
    const [isLoaded, setIsLoaded] = React.useState(false);
    const imgRef = React.useRef<HTMLImageElement>(null);

    React.useEffect(() => {
        const observer = new IntersectionObserver(
            (entries) => {
                entries.forEach(entry => {
                    if (entry.isIntersecting) {
                        setImageSrc(src);
                        observer.disconnect();
                    }
                });
            },
            { threshold: 0.1 }
        );

        if (imgRef.current) {
            observer.observe(imgRef.current);
        }

        return () => observer.disconnect();
    }, [src]);

    const handleLoad = () => {
        setIsLoaded(true);
    };

    return (
        <img
            ref={imgRef}
            src={imageSrc}
            alt={alt}
            className={`${className} ${isLoaded ? 'opacity-100' : 'opacity-75'} transition-opacity duration-300`}
            onLoad={handleLoad}
            width={width}
            height={height}
            loading="lazy"
        />
    );
}

/**
 * Progressive image component with multiple sources
 */
interface ProgressiveImageProps {
    src: string;
    lowQualitySrc?: string;
    alt: string;
    className?: string;
    width?: number;
    height?: number;
}

export function ProgressiveImage({
    src,
    lowQualitySrc,
    alt,
    className = '',
    width,
    height
}: ProgressiveImageProps): JSX.Element {
    const [currentSrc, setCurrentSrc] = React.useState(lowQualitySrc || src);
    const [isHighQualityLoaded, setIsHighQualityLoaded] = React.useState(false);

    React.useEffect(() => {
        if (lowQualitySrc && src !== lowQualitySrc) {
            const img = new Image();
            img.onload = () => {
                setCurrentSrc(src);
                setIsHighQualityLoaded(true);
            };
            img.src = src;
        }
    }, [src, lowQualitySrc]);

    return (
        <img
            src={currentSrc}
            alt={alt}
            className={`${className} ${isHighQualityLoaded ? 'opacity-100' : 'opacity-90'} transition-opacity duration-500`}
            width={width}
            height={height}
            loading="lazy"
        />
    );
}

/**
 * Virtual list component for large datasets
 */
interface VirtualListProps<T> {
    items: T[];
    itemHeight: number;
    containerHeight: number;
    renderItem: (item: T, index: number) => ReactNode;
    className?: string;
}

export function VirtualList<T>({
    items,
    itemHeight,
    containerHeight,
    renderItem,
    className = ''
}: VirtualListProps<T>): JSX.Element {
    const [scrollTop, setScrollTop] = React.useState(0);

    const startIndex = Math.floor(scrollTop / itemHeight);
    const endIndex = Math.min(
        items.length - 1,
        Math.floor((scrollTop + containerHeight) / itemHeight)
    );

    const visibleItems = items.slice(startIndex, endIndex + 1);
    const offsetY = startIndex * itemHeight;

    const handleScroll = (event: React.UIEvent<HTMLDivElement>) => {
        setScrollTop(event.currentTarget.scrollTop);
    };

    return (
        <div
            className={`overflow-auto ${className}`}
            style={{ height: containerHeight }}
            onScroll={handleScroll}
        >
            <div style={{ height: items.length * itemHeight, position: 'relative' }}>
                <div style={{ transform: `translateY(${offsetY}px)` }}>
                    {visibleItems.map((item, index) => (
                        <div key={startIndex + index} style={{ height: itemHeight }}>
                            {renderItem(item, startIndex + index)}
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
}

/**
 * Preload utilities
 */
export const PreloadUtils = {
    /**
     * Preload a component
     */
    preloadComponent: (importFn: () => Promise<any>): void => {
        importFn().catch(error => {
            console.warn('Failed to preload component:', error);
        });
    },

    /**
     * Preload an image
     */
    preloadImage: (src: string): Promise<void> => {
        return new Promise((resolve, reject) => {
            const img = new Image();
            img.onload = () => resolve();
            img.onerror = () => reject(new Error(`Failed to preload image: ${src}`));
            img.src = src;
        });
    },

    /**
     * Preload multiple images
     */
    preloadImages: async (sources: string[]): Promise<void> => {
        await Promise.all(sources.map(src => PreloadUtils.preloadImage(src)));
    },
};

export default {
    createLazyComponent,
    createRouteComponent,
    LoadingSpinner,
    RouteLoadingSpinner,
    LazyImage,
    ProgressiveImage,
    VirtualList,
    PreloadUtils,
};

import React, { useState, useContext } from 'react';
import { AuthContext } from '../contexts/AuthContext';

const Login = () => {
  const authContext = useContext(AuthContext);
  if (!authContext) {
    throw new Error('LoginForm debe estar dentro de un AuthContext.Provider');
  }
  const { login } = authContext;
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const validate = () => {
    if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) {
      setError('Email inválido');
      return false;
    }
    if (password.length < 6) {
      setError('La contraseña debe tener al menos 6 caracteres');
      return false;
    }
    setError('');
    return true;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!validate()) return;
    setLoading(true);
    try {
      await login(email, password);
    } catch (err: any) {
      setError(err.message || 'Error de autenticación');
    } finally {
      setLoading(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} className="login-form">
      <h2>Iniciar sesión</h2>
      <input
        type="email"
        placeholder="Email"
        value={email}
        onChange={e => setEmail(e.target.value)}
        required
      />
      <input
        type="password"
        placeholder="Contraseña"
        value={password}
        onChange={e => setPassword(e.target.value)}
        required
        minLength={6}
      />
      {error && <div className="error">{error}</div>}
      <button type="submit" disabled={loading}>
        {loading ? 'Ingresando...' : 'Ingresar'}
      </button>
    </form>
  );
};

export default Login;

/**
 * Advanced Image Optimization Component
 * 
 * Production-ready image optimization with WebP support, lazy loading,
 * responsive images, and performance monitoring.
 * 
 * @package ImageOptimization
 * @author Bubble Talents Development Team
 * @version 1.0.0
 * @since 2025-01-05
 */

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { ImageOptimization } from '../utils/performance';

/**
 * Image formats supported
 */
type ImageFormat = 'webp' | 'jpeg' | 'png' | 'avif';

/**
 * Image props interface
 */
interface OptimizedImageProps {
    src: string;
    alt: string;
    width?: number;
    height?: number;
    quality?: number;
    formats?: ImageFormat[];
    lazy?: boolean;
    placeholder?: string;
    className?: string;
    onLoad?: () => void;
    onError?: (error: Error) => void;
    priority?: boolean;
    sizes?: string;
    loading?: 'lazy' | 'eager';
}

/**
 * Image loading state
 */
type LoadingState = 'loading' | 'loaded' | 'error';

/**
 * Optimized Image Component with WebP support
 */
export const OptimizedImage: React.FC<OptimizedImageProps> = ({
    src,
    alt,
    width,
    height,
    quality = 80,
    formats = ['webp', 'jpeg'],
    lazy = true,
    placeholder,
    className = '',
    onLoad,
    onError,
    priority = false,
    sizes,
    loading = 'lazy'
}) => {
    const [loadingState, setLoadingState] = useState<LoadingState>('loading');
    const [currentSrc, setCurrentSrc] = useState(placeholder || '');
    const imgRef = useRef<HTMLImageElement>(null);
    const observerRef = useRef<IntersectionObserver | null>(null);

    /**
     * Get optimized image sources for different formats
     */
    const getImageSources = useCallback(() => {
        const sources: { srcSet: string; type: string }[] = [];

        formats.forEach(format => {
            const optimizedUrl = ImageOptimization.getOptimizedImageUrl(
                src,
                width,
                height,
                quality
            );

            // Add format parameter
            const url = new URL(optimizedUrl, window.location.origin);
            url.searchParams.set('f', format);

            sources.push({
                srcSet: url.toString(),
                type: `image/${format}`
            });
        });

        return sources;
    }, [src, width, height, quality, formats]);

    /**
     * Load image with format fallback
     */
    const loadImage = useCallback(async () => {
        try {
            setLoadingState('loading');

            // Get optimized sources
            const sources = getImageSources();
            let loadedSrc = src;

            // Try each format until one works
            for (const source of sources) {
                try {
                    await new Promise<void>((resolve, reject) => {
                        const testImg = new Image();
                        testImg.onload = () => resolve();
                        testImg.onerror = () => reject();
                        testImg.src = source.srcSet;
                    });
                    loadedSrc = source.srcSet;
                    break;
                } catch {
                    // Continue to next format
                }
            }

            setCurrentSrc(loadedSrc);
            setLoadingState('loaded');
            onLoad?.();
        } catch (error) {
            setLoadingState('error');
            onError?.(error as Error);
        }
    }, [src, getImageSources, onLoad, onError]);

    /**
     * Setup intersection observer for lazy loading
     */
    useEffect(() => {
        if (!lazy || priority || !imgRef.current) {
            loadImage();
            return undefined;
        }

        observerRef.current = new IntersectionObserver(
            (entries) => {
                const [entry] = entries;
                if (entry?.isIntersecting) {
                    loadImage();
                    observerRef.current?.unobserve(imgRef.current!);
                }
            },
            {
                rootMargin: '50px 0px',
                threshold: 0.1
            }
        );

        observerRef.current.observe(imgRef.current);

        return () => {
            observerRef.current?.disconnect();
        };
    }, [lazy, priority, loadImage]);

    /**
     * Preload critical images
     */
    useEffect(() => {
        if (priority) {
            const link = document.createElement('link');
            link.rel = 'preload';
            link.as = 'image';
            link.href = currentSrc;
            document.head.appendChild(link);
        }
    }, [priority, currentSrc]);

    return (
        <picture className={`optimized-image ${className}`}>
            {/* Generate source elements for different formats */}
            {getImageSources().map((source, index) => (
                <source
                    key={index}
                    srcSet={source.srcSet}
                    type={source.type}
                    sizes={sizes}
                />
            ))}

            <img
                ref={imgRef}
                src={currentSrc}
                alt={alt}
                width={width}
                height={height}
                loading={loading}
                className={`
                    transition-opacity duration-300
                    ${loadingState === 'loading' ? 'opacity-50' : 'opacity-100'}
                    ${loadingState === 'error' ? 'bg-gray-200' : ''}
                `}
                onLoad={() => {
                    setLoadingState('loaded');
                    onLoad?.();
                }}
                onError={() => {
                    setLoadingState('error');
                    onError?.(new Error('Image failed to load'));
                }}
            />
        </picture>
    );
};

/**
 * Background Image Component with optimization
 */
interface OptimizedBackgroundImageProps {
    src: string;
    children: React.ReactNode;
    className?: string;
    quality?: number;
    lazy?: boolean;
    priority?: boolean;
}

export const OptimizedBackgroundImage: React.FC<OptimizedBackgroundImageProps> = ({
    src,
    children,
    className = '',
    quality = 80,
    lazy = true,
    priority = false
}) => {
    const [backgroundImage, setBackgroundImage] = useState<string>('');
    const [isLoaded, setIsLoaded] = useState(false);
    const elementRef = useRef<HTMLDivElement>(null);

    const loadBackgroundImage = useCallback(async () => {
        try {
            const optimizedUrl = ImageOptimization.getOptimizedImageUrl(src, undefined, undefined, quality);

            // Preload the image
            await new Promise<void>((resolve, reject) => {
                const img = new Image();
                img.onload = () => resolve();
                img.onerror = () => reject();
                img.src = optimizedUrl;
            });

            setBackgroundImage(`url("${optimizedUrl}")`);
            setIsLoaded(true);
        } catch (error) {
            console.warn('Failed to load background image:', error);
        }
    }, [src, quality]);

    useEffect(() => {
        if (!lazy || priority) {
            loadBackgroundImage();
            return undefined;
        }

        const observer = new IntersectionObserver(
            (entries) => {
                const [entry] = entries;
                if (entry?.isIntersecting) {
                    loadBackgroundImage();
                    observer.unobserve(elementRef.current!);
                }
            },
            { rootMargin: '50px 0px' }
        );

        if (elementRef.current) {
            observer.observe(elementRef.current);
        }

        return () => observer.disconnect();
    }, [lazy, priority, loadBackgroundImage]);

    return (
        <div
            ref={elementRef}
            className={`
                ${className}
                transition-all duration-500
                ${isLoaded ? 'opacity-100' : 'opacity-70'}
            `}
            style={{
                backgroundImage,
                backgroundSize: 'cover',
                backgroundPosition: 'center',
                backgroundRepeat: 'no-repeat'
            }}
        >
            {children}
        </div>
    );
};

