  Accordion,
  AccordionSummary,
  AccordionDetails,
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  Switch,
  FormControlLabel,
  Badge,
  Fab,
  Zoom,
  Collapse
} from '@mui/material';
import {
  TrendingUp,
  TrendingDown,
  Insights,
  Psychology,
  AutoGraph,
