  SmartToy
} from '@mui/icons-material';

// Interfaces para tipos de datos
interface AIInsight {
  id: string;
  type: 'recommendation' | 'prediction' | 'alert' | 'opportunity' | 'risk' | 'trend';
  category: 'recruitment' | 'candidate' | 'performance' | 'market' | 'process' | 'quality';
  title: string;
  description: string;
  confidence: number;
  impact: 'critical' | 'high' | 'medium' | 'low';
  priority: number;
  timestamp: Date;
  source: string;
  actionable: boolean;
  actions?: InsightAction[];
  metadata: {
    candidateId?: string;
    positionId?: string;
    recruiterId?: string;
    data?: any;
  };
  status: 'new' | 'viewed' | 'actioned' | 'dismissed';
  tags: string[];
  relatedInsights?: string[];
}

interface InsightAction {
  id: string;
  label: string;
  type: 'primary' | 'secondary' | 'warning' | 'error';
  action: 'navigate' | 'api_call' | 'dialog' | 'external';
  params?: any;
}

interface PredictiveInsight {
  id: string;
  title: string;
  prediction: string;
  probability: number;
  timeframe: string;
  impact: string;
  factors: string[];
  recommendations: string[];
}

interface TrendAnalysis {
  id: string;
  metric: string;
  trend: 'up' | 'down' | 'stable';
  percentage: number;
  period: string;
  significance: 'high' | 'medium' | 'low';
  context: string;
}

interface AIInsightsPanelProps {
  candidateId?: string;
  positionId?: string;
  recruiterId?: string;
  autoRefresh?: boolean;
  refreshInterval?: number;
  maxInsights?: number;
  enablePredictions?: boolean;
  enableTrends?: boolean;
  enableNotifications?: boolean;
  compactMode?: boolean;
}

const AIInsightsPanel: React.FC<AIInsightsPanelProps> = ({
