              {isLoading ? 'Registrando...' : 'Completar registro'}
            </button>
          )}
        </div>

        {step === 1 && (
          <div className="text-center mt-6">
            <p className="text-sm text-gray-600">
              ¿Ya tienes cuenta?{' '}
              <a href="/auth/login" className="text-[#F24495] hover:underline">
                Inicia sesión
              </a>
            </p>
          </div>
        )}
      </form>
    </div>
  );
};

