import React, { useState, useCallback, useMemo, useEffect } from 'react';
import { useValidator } from '../../utils/validator';
import { FormInput } from '../ui/FormInput';
import { FormSelect } from '../ui/FormSelect';
import { FormTextarea } from '../ui/FormTextarea';
import { Button } from '../ui/button';
import { Card, CardHeader, CardTitle, CardContent } from '../ui/card';
import { toast } from '../ui/use-toast';

export interface JobApplicationData {
    firstName: string;
    lastName: string;
    email: string;
    phone: string;
    location: string;
    coverLetter: string;
    salaryExpectation: string;
    availabilityDate: string;
    workPreference: 'remote' | 'hybrid' | 'onsite';
    experience: string;
    portfolio?: string;
    linkedinProfile?: string;
    resumeFile?: File;
}

interface JobApplicationFormProps {
    jobId?: string;
    onSubmit: (data: JobApplicationData) => Promise<void>;
    initialData?: Partial<JobApplicationData>;
    isLoading?: boolean;
    className?: string;
}

// Validation rules for the form
const validationRules = {
    firstName: {
        required: true,
        minLength: 2,
        pattern: /^[a-zA-ZÀ-ÿ\s]+$/,
        errorMessage: 'First name must be at least 2 characters and contain only letters'
    },
    lastName: {
        required: true,
        minLength: 2,
        pattern: /^[a-zA-ZÀ-ÿ\s]+$/,
        errorMessage: 'Last name must be at least 2 characters and contain only letters'
    },
    email: {
        required: true,
        email: true,
        errorMessage: 'Please enter a valid email address'
    },
    phone: {
        required: true,
        pattern: /^[\+]?[1-9][\d]{0,15}$/,
        errorMessage: 'Please enter a valid phone number'
    },
    location: {
        required: true,
        minLength: 3,
        errorMessage: 'Location must be at least 3 characters'
    },
    coverLetter: {
        required: true,
        minLength: 100,
        maxLength: 2000,
        errorMessage: 'Cover letter must be between 100 and 2000 characters'
    },
    salaryExpectation: {
        required: true,
        pattern: /^\d+$/,
        errorMessage: 'Please enter a valid salary amount (numbers only)'
    },
    availabilityDate: {
        required: true,
        minLength: 3,
        errorMessage: 'Please specify your availability'
    },
    workPreference: {
        required: true,
        errorMessage: 'Please select your work preference'
    },
    experience: {
        required: true,
        minLength: 50,
        maxLength: 1000,
        errorMessage: 'Experience description must be between 50 and 1000 characters'
    },
    portfolio: {
        required: false,
        pattern: /^https?:\/\/.+/,
        errorMessage: 'Please enter a valid URL'
    },
    linkedinProfile: {
        required: false,
        pattern: /^https:\/\/(www\.)?linkedin\.com\/in\/.+/,
        errorMessage: 'Please enter a valid LinkedIn profile URL'
    }
};

const workPreferenceOptions = [
    { value: 'remote', label: 'Remote Work' },
    { value: 'hybrid', label: 'Hybrid Work' },
    { value: 'onsite', label: 'On-site Work' }
];

export const JobApplicationForm: React.FC<JobApplicationFormProps> = ({
    jobId,
    onSubmit,
    initialData = {},
    isLoading = false,
    className = ''
}) => {
    // Form state
    const [formData, setFormData] = useState<JobApplicationData>({
        firstName: '',
        lastName: '',
        email: '',
        phone: '',
        location: '',
        coverLetter: '',
        salaryExpectation: '',
        availabilityDate: '',
        workPreference: 'remote',
        experience: '',
        portfolio: '',
        linkedinProfile: '',
        ...initialData
    });

    const [resumeFile, setResumeFile] = useState<File | null>(null);

    // Validation hook
    const {
        errors,
        validate,
        validateAll,
        clearError
    } = useValidator();

    // Check if form is valid
    const isValid = useMemo(() => {
        return Object.keys(errors).length === 0 &&
            formData.firstName &&
            formData.lastName &&
            formData.email &&
            formData.phone &&
            formData.location &&
            formData.coverLetter &&
            formData.experience &&
            formData.salaryExpectation &&
            formData.availabilityDate;
    }, [errors, formData]);

    // Memoized form sections for performance
    const personalInfoSection = useMemo(() => (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <FormInput
                label="First Name"
                name="firstName"
                type="text"
                value={formData.firstName}
                onChange={(e) => updateField('firstName', e.target.value)}
                error={errors.firstName}
                required
                placeholder="Enter your first name"
                data-testid="firstName-input"
                aria-describedby="firstName-error"
            />

            <FormInput
                label="Last Name"
                name="lastName"
                type="text"
                value={formData.lastName}
                onChange={(e) => updateField('lastName', e.target.value)}
                error={errors.lastName}
                required
                placeholder="Enter your last name"
                data-testid="lastName-input"
                aria-describedby="lastName-error"
            />

            <FormInput
                label="Email Address"
                name="email"
                type="email"
                value={formData.email}
                onChange={(e) => updateField('email', e.target.value)}
                error={errors.email}
                required
                placeholder="your.email@example.com"
                data-testid="email-input"
                aria-describedby="email-error"
            />

            <FormInput
                label="Phone Number"
                name="phone"
                type="tel"
                value={formData.phone}
                onChange={(e) => updateField('phone', e.target.value)}
                error={errors.phone}
                required
                placeholder="+1 (555) 123-4567"
                data-testid="phone-input"
                aria-describedby="phone-error"
            />

            <div className="md:col-span-2">
                <FormInput
                    label="Location"
                    name="location"
                    type="text"
                    value={formData.location}
                    onChange={(e) => updateField('location', e.target.value)}
                    error={errors.location}
                    required
                    placeholder="City, Country"
                    data-testid="location-input"
                    aria-describedby="location-error"
                />
            </div>
        </div>
    ), [formData.firstName, formData.lastName, formData.email, formData.phone, formData.location, errors]);

    const professionalInfoSection = useMemo(() => (
        <div className="space-y-6">
            <FormTextarea
                label="Cover Letter"
                name="coverLetter"
                value={formData.coverLetter}
                onChange={(e) => updateField('coverLetter', e.target.value)}
                error={errors.coverLetter}
                required
                placeholder="Tell us why you're interested in this position and how your skills align with our needs..."
                rows={6}
                data-testid="coverLetter-input"
                aria-describedby="coverLetter-error"
            />

            <FormTextarea
                label="Professional Experience"
                name="experience"
                value={formData.experience}
                onChange={(e) => updateField('experience', e.target.value)}
                error={errors.experience}
                required
                placeholder="Describe your relevant work experience, key achievements, and technologies you've worked with..."
                rows={5}
                data-testid="experience-input"
                aria-describedby="experience-error"
            />

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <FormInput
                    label="Salary Expectation (USD/month)"
                    name="salaryExpectation"
                    type="number"
                    value={formData.salaryExpectation}
                    onChange={(e) => updateField('salaryExpectation', e.target.value)}
                    error={errors.salaryExpectation}
                    required
                    placeholder="3000"
                    data-testid="salaryExpectation-input"
                    aria-describedby="salaryExpectation-error"
                />

                <FormInput
                    label="Availability Date"
                    name="availabilityDate"
                    type="text"
                    value={formData.availabilityDate}
                    onChange={(e) => updateField('availabilityDate', e.target.value)}
                    error={errors.availabilityDate}
                    required
                    placeholder="Immediate, 2 weeks, 1 month"
                    data-testid="availabilityDate-input"
                    aria-describedby="availabilityDate-error"
                />
            </div>

            <FormSelect
                label="Work Preference"
                name="workPreference"
                value={formData.workPreference}
                onChange={(e) => updateField('workPreference', e.target.value as 'remote' | 'hybrid' | 'onsite')}
                options={workPreferenceOptions}
                error={errors.workPreference}
                required
                data-testid="workPreference-select"
                aria-describedby="workPreference-error"
            />
        </div>
    ), [formData.coverLetter, formData.experience, formData.salaryExpectation, formData.availabilityDate, formData.workPreference, errors]);

    const optionalInfoSection = useMemo(() => (
        <div className="space-y-6">
            <FormInput
                label="Portfolio URL (Optional)"
                name="portfolio"
                type="url"
                value={formData.portfolio || ''}
                onChange={(e) => updateField('portfolio', e.target.value)}
                error={errors.portfolio}
                placeholder="https://your-portfolio.com"
                data-testid="portfolio-input"
                aria-describedby="portfolio-error"
            />

            <FormInput
                label="LinkedIn Profile (Optional)"
                name="linkedinProfile"
                type="url"
                value={formData.linkedinProfile || ''}
                onChange={(e) => updateField('linkedinProfile', e.target.value)}
                error={errors.linkedinProfile}
                placeholder="https://linkedin.com/in/your-profile"
                data-testid="linkedinProfile-input"
                aria-describedby="linkedinProfile-error"
            />

            <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                    Resume/CV (Optional)
                </label>
                <input
                    type="file"
                    accept=".pdf,.doc,.docx"
                    onChange={handleFileChange}
                    className="block w-full text-sm text-gray-500 file:mr-4 file:py-2 file:px-4 file:rounded-md file:border-0 file:text-sm file:font-medium file:bg-blue-50 file:text-blue-700 hover:file:bg-blue-100"
                    data-testid="resume-input"
                    aria-describedby="resume-help"
                />
                <p id="resume-help" className="text-xs text-gray-500 mt-1">
                    Accepted formats: PDF, DOC, DOCX. Max size: 5MB
                </p>
            </div>
        </div>
    ), [formData.portfolio, formData.linkedinProfile, errors]);

    // Update field handler with validation
    const updateField = useCallback((field: keyof JobApplicationData, value: string) => {
        setFormData(prev => ({ ...prev, [field]: value }));
        // Clear error when user starts typing
        if (errors[field]) {
            clearError(field);
        }
    }, [errors, clearError]);

    // File upload handler
    const handleFileChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            // Validate file size (5MB limit)
            if (file.size > 5 * 1024 * 1024) {
                toast({
                    title: "File too large",
                    description: "Please select a file smaller than 5MB",
                    variant: "destructive"
                });
                return;
            }

            // Validate file type
            const allowedTypes = ['application/pdf', 'application/msword', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'];
            if (!allowedTypes.includes(file.type)) {
                toast({
                    title: "Invalid file type",
                    description: "Please select a PDF, DOC, or DOCX file",
                    variant: "destructive"
                });
                return;
            }

            setResumeFile(file);
        }
    }, []);

    // Form submission handler
    const handleSubmit = useCallback(async (e: React.FormEvent) => {
        e.preventDefault();

        // Validate all fields
        const formIsValid = validateAll(formData, validationRules);

        if (!formIsValid) {
            toast({
                title: "Validation Error",
                description: "Please correct the errors in the form",
                variant: "destructive"
            });
            return;
        }

        try {
            const applicationData = {
                ...formData,
                ...(resumeFile && { resumeFile })
            };

            await onSubmit(applicationData);

            toast({
                title: "Application Submitted",
                description: "Your job application has been submitted successfully!",
                variant: "default"
            });

            // Reset form on successful submission
            setFormData({
                firstName: '',
                lastName: '',
                email: '',
                phone: '',
                location: '',
                coverLetter: '',
                salaryExpectation: '',
                availabilityDate: '',
                workPreference: 'remote',
                experience: '',
                portfolio: '',
                linkedinProfile: ''
            });
            setResumeFile(null);

        } catch (error) {
            console.error('Error submitting application:', error);
            toast({
                title: "Submission Error",
                description: "There was an error submitting your application. Please try again.",
                variant: "destructive"
            });
        }
    }, [formData, resumeFile, validateAll, onSubmit]);

    return (
        <form onSubmit={handleSubmit} className={`space-y-8 ${className}`} noValidate>
            {/* Personal Information */}
            <Card>
                <CardHeader>
                    <CardTitle>Personal Information</CardTitle>
                </CardHeader>
                <CardContent>
                    {personalInfoSection}
                </CardContent>
            </Card>

            {/* Professional Information */}
            <Card>
                <CardHeader>
                    <CardTitle>Professional Information</CardTitle>
                </CardHeader>
                <CardContent>
                    {professionalInfoSection}
                </CardContent>
            </Card>

            {/* Optional Information */}
            <Card>
                <CardHeader>
                    <CardTitle>Additional Information</CardTitle>
                </CardHeader>
                <CardContent>
                    {optionalInfoSection}
                </CardContent>
            </Card>

            {/* Submit Button */}
            <div className="flex justify-end pt-6">
                <Button
                    type="submit"
                    disabled={isLoading || !isValid}
                    className="bg-[#FF4785] hover:bg-[#FF3575] text-white px-8 py-3 text-lg font-medium"
                    data-testid="submit-button"
                >
                    {isLoading ? 'Submitting...' : 'Submit Application'}
                </Button>
            </div>
        </form>
    );
};

import React, { useState } from 'react';
import { Label } from '../ui/label';
import { Input } from '../ui/input';
import { Textarea } from '../ui/textarea';
import { Button } from '../ui/button';
import { Badge } from '../ui/badge';
import { Card, CardContent, CardHeader, CardTitle } from '../ui/card';
import { Separator } from '../ui/separator';
import { Plus, X, FileText } from 'lucide-react';

interface CVData {
  nombre?: string;
  email?: string;
  telefono?: string;
  ubicacion_actual?: string;
  fecha_nacimiento?: string;
  portfolio?: string;
  linkedin?: string;
  otras_redes?: string[];
  resumen_profesional?: string;
  soft_skills?: string[];
  hard_skills?: string[];
  idiomas?: Array<{ idioma: string; nivel: string }>;
  intereses?: string[];
  referencias?: string;
  disponibilidad?: string;
  puestos_anteriores?: Array<{
    puesto: string;
    empresa: string;
    fecha_inicio: string;
    fecha_fin: string;
    descripcion: string;
    responsabilidades?: string[];
  }>;
  educacion?: Array<{
    titulo: string;
    institucion: string;
    fecha_inicio: string;
    fecha_fin: string;
    descripcion?: string;
  }>;
  certificaciones?: string[];
  proyectos?: Array<{
    nombre: string;
    descripcion: string;
    tecnologias?: string[];
  }>;
}

interface ManualCVFormProps {
  onSubmit: (data: CVData) => void;
  initialData?: Partial<CVData>;
  isLoading?: boolean;
}

export function ManualCVForm({ onSubmit, initialData = {}, isLoading = false }: ManualCVFormProps) {
  const [formData, setFormData] = useState<CVData>({
    nombre: '',
    email: '',
    telefono: '',
    ubicacion_actual: '',
    fecha_nacimiento: '',
    portfolio: '',
    linkedin: '',
    otras_redes: [],
    resumen_profesional: '',
    soft_skills: [],
    hard_skills: [],
    idiomas: [],
    intereses: [],
    referencias: '',
    disponibilidad: '',
    puestos_anteriores: [],
    educacion: [],
    certificaciones: [],
    proyectos: [],
    ...initialData
  });

  const [errors, setErrors] = useState<{ [key: string]: string }>({});

  const handleFieldChange = (field: string, value: any) => {
    setFormData(prev => ({
      ...prev,
      [field]: value
    }));
    // Limpiar error cuando el usuario empiece a escribir
    if (errors[field]) {
      setErrors(prev => ({
        ...prev,
        [field]: ''
      }));
    }
  };

  const handleArrayFieldChange = (field: string, index: number, value: any) => {
    setFormData(prev => ({
      ...prev,
      [field]: (prev[field as keyof CVData] as any[])?.map((item, i) =>
        i === index ? value : item
      ) || []
    }));
  };

  const addArrayItem = (field: string, emptyItem: any) => {
    setFormData(prev => ({
      ...prev,
      [field]: [...((prev[field as keyof CVData] as any[]) || []), emptyItem]
    }));
  };

  const removeArrayItem = (field: string, index: number) => {
    setFormData(prev => ({
      ...prev,
      [field]: (prev[field as keyof CVData] as any[])?.filter((_, i) => i !== index) || []
    }));
  };

  const addSkill = (skillType: 'hard_skills' | 'soft_skills', skill: string) => {
    if (skill.trim()) {
      addArrayItem(skillType, skill.trim());
    }
  };

  const validateForm = (): boolean => {
    const newErrors: { [key: string]: string } = {};

    if (!formData.nombre?.trim()) {
      newErrors.nombre = 'El nombre es requerido';
    }

    if (!formData.email?.trim()) {
      newErrors.email = 'El email es requerido';
    } else if (!/\S+@\S+\.\S+/.test(formData.email)) {
      newErrors.email = 'El email no es válido';
    }

    if (!formData.telefono?.trim()) {
      newErrors.telefono = 'El teléfono es requerido';
    }

    if (!formData.ubicacion_actual?.trim()) {
      newErrors.ubicacion_actual = 'La ubicación es requerida';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (validateForm()) {
      onSubmit(formData);
    }
  };

  const renderSkillInput = (skillType: 'hard_skills' | 'soft_skills', label: string) => {
    const skills = formData[skillType] || [];
    const [newSkill, setNewSkill] = useState('');

    return (
      <div className="space-y-3">
        <Label className="text-sm font-medium">{label}</Label>

        {/* Skills existentes */}
        <div className="flex flex-wrap gap-2">
          {skills.map((skill, index) => (
            <Badge key={index} variant="secondary" className="px-2 py-1">
              {skill}
              <Button
                variant="ghost"
                size="sm"
                className="ml-1 h-4 w-4 p-0"
                onClick={() => removeArrayItem(skillType, index)}
              >
                <X className="h-3 w-3" />
              </Button>
            </Badge>
          ))}
        </div>

        {/* Input para nueva skill */}
        <div className="flex space-x-2">
          <Input
            placeholder={`Agregar ${label.toLowerCase()}`}
            value={newSkill}
            onChange={(e) => setNewSkill(e.target.value)}
            onKeyPress={(e) => {
              if (e.key === 'Enter') {
                e.preventDefault();
                addSkill(skillType, newSkill);
                setNewSkill('');
              }
            }}
          />
          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={() => {
              addSkill(skillType, newSkill);
              setNewSkill('');
            }}
          >
            <Plus className="h-4 w-4" />
          </Button>
        </div>
      </div>
    );
  };

  const renderExperienceSection = () => {
    const puestos = formData.puestos_anteriores || [];

    return (
      <div className="space-y-4">
        <div className="flex items-center justify-between">
          <Label className="text-sm font-medium">Experiencia Laboral</Label>
          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={() => addArrayItem('puestos_anteriores', {
              puesto: '',
              empresa: '',
              fecha_inicio: '',
              fecha_fin: '',
              descripcion: ''
            })}
          >
            <Plus className="h-4 w-4 mr-1" />
            Agregar Experiencia
          </Button>
        </div>

        {puestos.map((puesto, index) => (
          <Card key={index}>
            <CardHeader className="pb-3">
              <div className="flex items-center justify-between">
                <CardTitle className="text-sm">Experiencia {index + 1}</CardTitle>
                <Button
                  type="button"
                  variant="ghost"
                  size="sm"
                  onClick={() => removeArrayItem('puestos_anteriores', index)}
                >
                  <X className="h-4 w-4" />
                </Button>
              </div>
            </CardHeader>
            <CardContent className="space-y-3">
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <Label className="text-xs">Puesto *</Label>
                  <Input
                    value={puesto.puesto}
                    onChange={(e) => handleArrayFieldChange('puestos_anteriores', index, {
                      ...puesto,
                      puesto: e.target.value
                    })}
                    placeholder="Ej: Desarrollador Frontend"
                  />
                </div>
                <div>
                  <Label className="text-xs">Empresa *</Label>
                  <Input
                    value={puesto.empresa}
                    onChange={(e) => handleArrayFieldChange('puestos_anteriores', index, {
                      ...puesto,
                      empresa: e.target.value
                    })}
                    placeholder="Ej: Tech Company S.A."
                  />
                </div>
                <div>
                  <Label className="text-xs">Fecha Inicio</Label>
                  <Input
                    type="date"
                    value={puesto.fecha_inicio}
                    onChange={(e) => handleArrayFieldChange('puestos_anteriores', index, {
                      ...puesto,
                      fecha_inicio: e.target.value
                    })}
                  />
                </div>
                <div>
                  <Label className="text-xs">Fecha Fin</Label>
                  <Input
                    type="date"
                    value={puesto.fecha_fin}
                    onChange={(e) => handleArrayFieldChange('puestos_anteriores', index, {
                      ...puesto,
                      fecha_fin: e.target.value
                    })}
                    placeholder="Dejar vacío si es actual"
                  />
                </div>
              </div>
              <div>
                <Label className="text-xs">Descripción del Puesto</Label>
                <Textarea
                  value={puesto.descripcion}
                  onChange={(e) => handleArrayFieldChange('puestos_anteriores', index, {
                    ...puesto,
                    descripcion: e.target.value
                  })}
                  placeholder="Describe tus responsabilidades y logros..."
                  rows={3}
                />
              </div>
            </CardContent>
          </Card>
        ))}

        {puestos.length === 0 && (
          <div className="text-center py-8 text-gray-500">
            <FileText className="h-8 w-8 mx-auto mb-2" />
            <p>No has agregado experiencia laboral aún</p>
            <p className="text-sm">Haz clic en "Agregar Experiencia" para comenzar</p>
          </div>
        )}
      </div>
    );
  };

  const renderEducationSection = () => {
    const educacion = formData.educacion || [];

    return (
      <div className="space-y-4">
        <div className="flex items-center justify-between">
          <Label className="text-sm font-medium">Educación</Label>
          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={() => addArrayItem('educacion', {
              titulo: '',
              institucion: '',
              fecha_inicio: '',
              fecha_fin: '',
              descripcion: ''
            })}
          >
            <Plus className="h-4 w-4 mr-1" />
            Agregar Educación
          </Button>
        </div>

        {educacion.map((edu, index) => (
          <Card key={index}>
            <CardHeader className="pb-3">
              <div className="flex items-center justify-between">
                <CardTitle className="text-sm">Educación {index + 1}</CardTitle>
                <Button
                  type="button"
                  variant="ghost"
                  size="sm"
                  onClick={() => removeArrayItem('educacion', index)}
                >
                  <X className="h-4 w-4" />
                </Button>
              </div>
            </CardHeader>
            <CardContent className="space-y-3">
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <Label className="text-xs">Título/Grado *</Label>
                  <Input
                    value={edu.titulo}
                    onChange={(e) => handleArrayFieldChange('educacion', index, {
                      ...edu,
                      titulo: e.target.value
                    })}
                    placeholder="Ej: Ingeniería en Sistemas"
                  />
                </div>
                <div>
                  <Label className="text-xs">Institución *</Label>
                  <Input
                    value={edu.institucion}
                    onChange={(e) => handleArrayFieldChange('educacion', index, {
                      ...edu,
                      institucion: e.target.value
                    })}
                    placeholder="Ej: Universidad Nacional"
                  />
                </div>
                <div>
                  <Label className="text-xs">Fecha Inicio</Label>
                  <Input
                    type="date"
                    value={edu.fecha_inicio}
                    onChange={(e) => handleArrayFieldChange('educacion', index, {
                      ...edu,
                      fecha_inicio: e.target.value
                    })}
                  />
                </div>
                <div>
                  <Label className="text-xs">Fecha Fin</Label>
                  <Input
                    type="date"
                    value={edu.fecha_fin}
                    onChange={(e) => handleArrayFieldChange('educacion', index, {
                      ...edu,
                      fecha_fin: e.target.value
                    })}
                  />
                </div>
              </div>
            </CardContent>
          </Card>
        ))}

        {educacion.length === 0 && (
          <div className="text-center py-8 text-gray-500">
            <FileText className="h-8 w-8 mx-auto mb-2" />
            <p>No has agregado educación aún</p>
            <p className="text-sm">Haz clic en "Agregar Educación" para comenzar</p>
          </div>
        )}
      </div>
    );
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-8">
      {/* Información Personal */}
      <Card>
        <CardHeader>
          <CardTitle>Información Personal</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <Label htmlFor="nombre">Nombre Completo *</Label>
              <Input
                id="nombre"
                value={formData.nombre}
                onChange={(e) => handleFieldChange('nombre', e.target.value)}
                className={errors.nombre ? 'border-red-500' : ''}
              />
              {errors.nombre && <p className="text-sm text-red-500 mt-1">{errors.nombre}</p>}
            </div>

            <div>
              <Label htmlFor="email">Email *</Label>
              <Input
                id="email"
                type="email"
                value={formData.email}
                onChange={(e) => handleFieldChange('email', e.target.value)}
                className={errors.email ? 'border-red-500' : ''}
              />
              {errors.email && <p className="text-sm text-red-500 mt-1">{errors.email}</p>}
            </div>

            <div>
              <Label htmlFor="telefono">Teléfono *</Label>
              <Input
                id="telefono"
                type="tel"
                value={formData.telefono}
                onChange={(e) => handleFieldChange('telefono', e.target.value)}
                className={errors.telefono ? 'border-red-500' : ''}
              />
              {errors.telefono && <p className="text-sm text-red-500 mt-1">{errors.telefono}</p>}
            </div>

            <div>
              <Label htmlFor="ubicacion">Ubicación *</Label>
              <Input
                id="ubicacion"
                value={formData.ubicacion_actual}
                onChange={(e) => handleFieldChange('ubicacion_actual', e.target.value)}
                className={errors.ubicacion_actual ? 'border-red-500' : ''}
              />
              {errors.ubicacion_actual && <p className="text-sm text-red-500 mt-1">{errors.ubicacion_actual}</p>}
            </div>

            <div>
              <Label htmlFor="linkedin">LinkedIn</Label>
              <Input
                id="linkedin"
                value={formData.linkedin}
                onChange={(e) => handleFieldChange('linkedin', e.target.value)}
                placeholder="https://linkedin.com/in/tu-perfil"
              />
            </div>

            <div>
              <Label htmlFor="portfolio">Portfolio/Sitio Web</Label>
              <Input
                id="portfolio"
                value={formData.portfolio}
                onChange={(e) => handleFieldChange('portfolio', e.target.value)}
                placeholder="https://tu-portfolio.com"
              />
            </div>
          </div>

          <div>
            <Label htmlFor="resumen">Resumen Profesional</Label>
            <Textarea
              id="resumen"
              value={formData.resumen_profesional}
              onChange={(e) => handleFieldChange('resumen_profesional', e.target.value)}
              placeholder="Describe brevemente tu perfil profesional..."
              rows={4}
            />
          </div>
        </CardContent>
      </Card>

      {/* Habilidades */}
      <Card>
        <CardHeader>
          <CardTitle>Habilidades</CardTitle>
        </CardHeader>
        <CardContent className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {renderSkillInput('hard_skills', 'Habilidades Técnicas')}
            {renderSkillInput('soft_skills', 'Habilidades Blandas')}
          </div>
        </CardContent>
      </Card>

      <Separator />

      {/* Experiencia Laboral */}
      <Card>
        <CardHeader>
          <CardTitle>Experiencia Laboral</CardTitle>
        </CardHeader>
        <CardContent>
          {renderExperienceSection()}
        </CardContent>
      </Card>

      <Separator />

      {/* Educación */}
      <Card>
        <CardHeader>
          <CardTitle>Educación</CardTitle>
        </CardHeader>
        <CardContent>
          {renderEducationSection()}
        </CardContent>
      </Card>

      {/* Botón Submit */}
      <div className="flex justify-end space-x-3 pt-6">
        <Button type="submit" disabled={isLoading} className="min-w-[120px]">
          {isLoading ? 'Guardando...' : 'Guardar Información'}
        </Button>
      </div>
    </form>
  );
}

import React, { useState, useEffect } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter } from '../ui/dialog';
import { Button } from '../ui/button';
import { Input } from '../ui/input';
import { Label } from '../ui/label';
import { Textarea } from '../ui/textarea';
import { Separator } from '../ui/separator';
import { CheckCircle, Edit, Save, X, Plus, Upload, FileText, Loader2 } from 'lucide-react';
import { useCvForm } from '../../contexts/CvFormContext';
import { CvFormData, validateMinimumData } from '../../domain/cvSchema';

interface CVData {
  // bt_candidates - Campos principales
  nombre?: string;
  email?: string;
  telefono?: string;
  ubicacion_actual?: string;
  fecha_nacimiento?: string;
  portfolio?: string;
  linkedin?: string;
  otras_redes?: string[];
  resumen_profesional?: string;
  soft_skills?: string[];
  hard_skills?: string[];
  idiomas?: Array<{ idioma: string; nivel: string }>;
  intereses?: string[];
  referencias?: string;
  disponibilidad?: string;
  cv_original_file?: string;
  cv_text_file?: string;
  cv_json_file?: string;
  data_source?: 'ai_processing' | 'manual_entry' | 'hybrid';

  // bt_candidate_experiences
  puestos_anteriores?: Array<{
    puesto: string;
    empresa: string;
    fecha_inicio: string;
    fecha_fin: string;
    descripcion: string;
    responsabilidades?: string[];
    ubicacion?: string;
    actual?: boolean;
  }>;

  // bt_candidate_education
  educacion?: Array<{
    titulo: string;
    campo_estudio?: string;
    institucion: string;
    fecha_inicio: string;
    fecha_fin: string;
    nivel_educativo?: string;
    descripcion?: string;
  }>;

  // bt_candidate_certifications - Detalles expandidos
  certificaciones?: string[];
  certificaciones_detalle?: Array<{
    nombre_certificacion: string;
    emisor?: string;
    fecha_emision?: string;
    fecha_expiracion?: string;
  }>;

  // bt_candidate_languages - Detalles expandidos
  idiomas_detalle?: Array<{
    idioma: string;
    nivel_competencia?: string;
  }>;

  // bt_candidate_projects
  proyectos?: Array<{
    nombre: string;
    descripcion: string;
    tecnologias?: string[];
    fecha_inicio?: string;
    fecha_fin?: string;
    url?: string;
  }>;

  // bt_candidate_references - Detalles expandidos
  referencias_detalle?: Array<{
    nombre_referencia: string;
    empresa_referencia?: string;
    email_referencia?: string;
    telefono_referencia?: string;
    notas?: string;
  }>;

  // bt_candidate_skills - Habilidades adicionales
  habilidades_adicionales?: string[];

  // bt_candidate_routing - Información de enrutamiento
  routing?: {
    categoria_departamento_id?: number;
    departamento_id?: number;
    reclutador_id?: string;
    fuente?: 'ai' | 'manual';
    razon?: string;
    fecha_asignacion?: string;
  };
}

interface UnifiedCVFormProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (validatedData: CvFormData) => void;
}

export function UnifiedCVForm({
  isOpen,
  onClose,
  onSave
}: UnifiedCVFormProps) {
  // Usar el contexto global del formulario CV
  const {
    state: cvFormState,
    updateField,
    setErrors,
    resetForm,
    switchToManual,
    setFile,
    setLoading
  } = useCvForm();

  const { state: formState, data: formData, errors, isLoading } = cvFormState;

  const [editingField, setEditingField] = useState<string | null>(null);

  const handleFieldEdit = (field: string, value: any) => {
    updateField(field as keyof CvFormData, value);
  };

  const handleArrayFieldEdit = (field: string, index: number, newValue: any) => {
    const currentArray = (formData[field as keyof CvFormData] as any[]) || [];
    const updatedArray = currentArray.map((item, i) => i === index ? newValue : item);
    updateField(field as keyof CvFormData, updatedArray);
  };

  const addArrayItem = (field: string, newItem: any) => {
    const currentArray = (formData[field as keyof CvFormData] as any[]) || [];
    updateField(field as keyof CvFormData, [...currentArray, newItem]);
  };

  const removeArrayItem = (field: string, index: number) => {
    const currentArray = (formData[field as keyof CvFormData] as any[]) || [];
    const updatedArray = currentArray.filter((_, i) => i !== index);
    updateField(field as keyof CvFormData, updatedArray);
  };

  const handleSave = () => {
    const validationErrors = validateMinimumData(formData);
    if (validationErrors.length > 0) {
      setErrors(validationErrors);
      return;
    }
    onSave(formData);
  };

  const renderEditableField = (label: string, field: string, value: any, type: 'text' | 'email' | 'tel' | 'date' | 'textarea' | 'url' = 'text') => {
    const isEditing = editingField === field;

    return (
      <div className="space-y-1">
        <div className="flex items-center justify-between">
          <Label className="text-xs font-medium text-gray-700">{label}</Label>
          <Button
            variant="ghost"
            size="sm"
            onClick={() => setEditingField(isEditing ? null : field)}
          >
            {isEditing ? <Save className="h-3 w-3" /> : <Edit className="h-3 w-3" />}
          </Button>
        </div>

        {isEditing ? (
          type === 'textarea' ? (
            <Textarea
              value={value || ''}
              onChange={(e) => handleFieldEdit(field, e.target.value)}
              className="min-h-[50px] text-xs"
            />
          ) : (
            <Input
              type={type}
              value={value || ''}
              onChange={(e) => handleFieldEdit(field, e.target.value)}
              className="text-xs"
            />
          )
        ) : (
          <div className="p-2 bg-gray-50 rounded text-xs min-h-[36px] flex items-center">
            {value || <span className="text-gray-400 italic">No especificado - Click editar</span>}
          </div>
        )}
      </div>
    );
  };

  const renderSkillsSection = (label: string, field: string, skills: string[] = []) => {
    return (
      <div className="space-y-2">
        <div className="flex items-center justify-between">
          <Label className="text-xs font-medium text-gray-700">{label}</Label>
          <Button
            variant="ghost"
            size="sm"
            onClick={() => addArrayItem(field, '')}
          >
            <Plus className="h-3 w-3" />
          </Button>
        </div>

        <div className="space-y-1">
          {skills.map((skill, index) => (
            <div key={index} className="flex items-center space-x-2">
              <Input
                className="text-xs"
                value={skill}
                onChange={(e) => handleArrayFieldEdit(field, index, e.target.value)}
                placeholder={`${label} ${index + 1}`}
              />
              <Button
                variant="ghost"
                size="sm"
                onClick={() => removeArrayItem(field, index)}
              >
                <X className="h-3 w-3" />
              </Button>
            </div>
          ))}
        </div>

        {skills.length === 0 && (
          <div className="p-2 bg-gray-50 rounded text-xs text-gray-400 italic">
            Click + para agregar {label.toLowerCase()}
          </div>
        )}
      </div>
    );
  };

  const renderExperienceSection = () => {
    const puestos = formData.puestos_anteriores || [];

    return (
      <div className="space-y-4">
        <div className="flex items-center justify-between">
          <Label className="text-sm font-medium text-gray-700">Experiencia Laboral</Label>
          <Button
            variant="ghost"
            size="sm"
            onClick={() => addArrayItem('puestos_anteriores', {
              puesto: '',
              empresa: '',
              fecha_inicio: '',
              fecha_fin: '',
              descripcion: '',
              responsabilidades: [],
              ubicacion: '',
              actual: false
            })}
          >
            <Plus className="h-3 w-3 mr-1" />
            <span className="text-xs">Agregar</span>
          </Button>
        </div>

        {puestos.map((puesto, index) => (
          <div key={index} className="p-3 border rounded-lg space-y-2">
            <div className="flex justify-between items-start">
              <h4 className="text-xs font-medium">Puesto {index + 1}</h4>
              <Button
                variant="ghost"
                size="sm"
                onClick={() => removeArrayItem('puestos_anteriores', index)}
              >
                <X className="h-3 w-3" />
              </Button>
            </div>

            <div className="grid grid-cols-3 gap-2">
              <div>
                <Label className="text-xs">Puesto</Label>
                <Input
                  className="text-xs"
                  value={puesto.puesto}
                  onChange={(e) => handleArrayFieldEdit('puestos_anteriores', index, {
                    ...puesto,
                    puesto: e.target.value
                  })}
                  placeholder="Ej: Developer"
                />
              </div>
              <div>
                <Label className="text-xs">Empresa</Label>
                <Input
                  className="text-xs"
                  value={puesto.empresa}
                  onChange={(e) => handleArrayFieldEdit('puestos_anteriores', index, {
                    ...puesto,
                    empresa: e.target.value
                  })}
                  placeholder="Ej: TechCorp"
                />
              </div>
              <div>
                <Label className="text-xs">Ubicación</Label>
                <Input
                  className="text-xs"
                  value={puesto.ubicacion || ''}
                  onChange={(e) => handleArrayFieldEdit('puestos_anteriores', index, {
                    ...puesto,
                    ubicacion: e.target.value
                  })}
                  placeholder="Ej: Madrid"
                />
              </div>
              <div>
                <Label className="text-xs">Fecha Inicio</Label>
                <Input
                  className="text-xs"
                  type="date"
                  value={puesto.fecha_inicio}
                  onChange={(e) => handleArrayFieldEdit('puestos_anteriores', index, {
                    ...puesto,
                    fecha_inicio: e.target.value
                  })}
                />
              </div>
              <div>
                <Label className="text-xs">Fecha Fin</Label>
                <Input
                  className="text-xs"
                  type="date"
                  value={puesto.fecha_fin}
                  onChange={(e) => handleArrayFieldEdit('puestos_anteriores', index, {
                    ...puesto,
                    fecha_fin: e.target.value
                  })}
                  disabled={puesto.actual}
                />
              </div>
              <div className="flex items-center space-x-2">
                <input
                  type="checkbox"
                  checked={puesto.actual || false}
                  onChange={(e) => handleArrayFieldEdit('puestos_anteriores', index, {
                    ...puesto,
                    actual: e.target.checked,
                    fecha_fin: e.target.checked ? '' : puesto.fecha_fin
                  })}
                />
                <Label className="text-xs">Actual</Label>
              </div>
            </div>

            <div>
              <Label className="text-xs">Descripción</Label>
              <Textarea
                className="text-xs min-h-[50px]"
                value={puesto.descripcion}
                onChange={(e) => handleArrayFieldEdit('puestos_anteriores', index, {
                  ...puesto,
                  descripcion: e.target.value
                })}
                placeholder="Describe las responsabilidades y logros..."
              />
            </div>
          </div>
        ))}

        {puestos.length === 0 && (
          <div className="p-3 bg-gray-50 rounded text-xs text-gray-400 italic">
            Click + para agregar experiencia laboral
          </div>
        )}
      </div>
    );
  };

  const renderEducationSection = () => {
    const educacion = formData.educacion || [];

    return (
      <div className="space-y-4">
        <div className="flex items-center justify-between">
          <Label className="text-sm font-medium text-gray-700">Educación</Label>
          <Button
            variant="ghost"
            size="sm"
            onClick={() => addArrayItem('educacion', {
              titulo: '',
              campo_estudio: '',
              institucion: '',
              fecha_inicio: '',
              fecha_fin: '',
              nivel_educativo: '',
              descripcion: ''
            })}
          >
            <Plus className="h-3 w-3 mr-1" />
            <span className="text-xs">Agregar</span>
          </Button>
        </div>

        {educacion.map((edu, index) => (
          <div key={index} className="p-3 border rounded-lg space-y-2">
            <div className="flex justify-between items-start">
              <h4 className="text-xs font-medium">Educación {index + 1}</h4>
              <Button
                variant="ghost"
                size="sm"
                onClick={() => removeArrayItem('educacion', index)}
              >
                <X className="h-3 w-3" />
              </Button>
            </div>

            <div className="grid grid-cols-3 gap-2">
              <div>
                <Label className="text-xs">Título</Label>
                <Input
                  className="text-xs"
                  value={edu.titulo}
                  onChange={(e) => handleArrayFieldEdit('educacion', index, {
                    ...edu,
                    titulo: e.target.value
                  })}
                  placeholder="Ej: Grado en Informática"
                />
              </div>
              <div>
                <Label className="text-xs">Campo de Estudio</Label>
                <Input
                  className="text-xs"
                  value={edu.campo_estudio || ''}
                  onChange={(e) => handleArrayFieldEdit('educacion', index, {
                    ...edu,
                    campo_estudio: e.target.value
                  })}
                  placeholder="Ej: Informática"
                />
              </div>
              <div>
                <Label className="text-xs">Institución</Label>
                <Input
                  className="text-xs"
                  value={edu.institucion}
                  onChange={(e) => handleArrayFieldEdit('educacion', index, {
                    ...edu,
                    institucion: e.target.value
                  })}
                  placeholder="Ej: Universidad Complutense"
                />
              </div>
              <div>
                <Label className="text-xs">Fecha Inicio</Label>
                <Input
                  className="text-xs"
                  type="date"
                  value={edu.fecha_inicio}
                  onChange={(e) => handleArrayFieldEdit('educacion', index, {
                    ...edu,
                    fecha_inicio: e.target.value
                  })}
                />
              </div>
              <div>
                <Label className="text-xs">Fecha Fin</Label>
                <Input
                  className="text-xs"
                  type="date"
                  value={edu.fecha_fin}
                  onChange={(e) => handleArrayFieldEdit('educacion', index, {
                    ...edu,
                    fecha_fin: e.target.value
                  })}
                />
              </div>
              <div>
                <Label className="text-xs">Nivel</Label>
                <Input
                  className="text-xs"
                  value={edu.nivel_educativo || ''}
                  onChange={(e) => handleArrayFieldEdit('educacion', index, {
                    ...edu,
                    nivel_educativo: e.target.value
                  })}
                  placeholder="Ej: Grado, Máster"
                />
              </div>
            </div>
          </div>
        ))}

        {educacion.length === 0 && (
          <div className="p-3 bg-gray-50 rounded text-xs text-gray-400 italic">
            Click + para agregar educación
          </div>
        )}
      </div>
    );
  };

  const getModalTitle = () => {
    switch (formState) {
      case 'ready':
        return (
          <>
            <CheckCircle className="h-5 w-5 text-green-500" />
            <span>Validar Datos Extraídos del CV</span>
          </>
        );
      case 'manual':
        return (
          <>
            <Edit className="h-5 w-5 text-blue-500" />
            <span>Completar Información Manualmente</span>
          </>
        );
      case 'uploading':
        return (
          <>
            <Upload className="h-5 w-5 text-blue-500" />
            <span>Subiendo Archivo</span>
          </>
        );
      case 'parsing':
        return (
          <>
            <Loader2 className="h-5 w-5 text-blue-500 animate-spin" />
            <span>Procesando con IA</span>
          </>
        );
      case 'saving':
        return (
          <>
            <Loader2 className="h-5 w-5 text-green-500 animate-spin" />
            <span>Guardando Información</span>
          </>
        );
      default:
        return (
          <>
            <FileText className="h-5 w-5 text-gray-500" />
            <span>Registro de CV</span>
          </>
        );
    }
  };

  const getModalDescription = () => {
    switch (formState) {
      case 'ready':
        return "La IA ha extraído la siguiente información de tu CV. Por favor, revisa y edita cualquier dato que necesite corrección antes de guardar.";
      case 'manual':
        return "No se pudo procesar automáticamente tu CV. Por favor, completa manualmente la información de tu perfil profesional.";
      case 'uploading':
        return "Tu archivo se está subiendo al servidor...";
      case 'parsing':
        return "Estamos procesando tu CV con inteligencia artificial para extraer la información...";
      case 'saving':
        return "Guardando tu información en el sistema...";
      case 'idle':
        return "Sube tu CV en PDF para procesarlo automáticamente o completa manualmente tu información.";
      default:
        return "Completa tu información profesional.";
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-5xl max-h-[95vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center space-x-2">
            {getModalTitle()}
          </DialogTitle>
          <DialogDescription>
            {getModalDescription()}
          </DialogDescription>
        </DialogHeader>

        {/* Mostrar errores si los hay */}
        {errors.length > 0 && (
          <div className="bg-red-50 border border-red-200 rounded-md p-3">
            <div className="flex">
              <X className="h-4 w-4 text-red-400 mt-0.5" />
              <div className="ml-2">
                <h4 className="text-sm font-medium text-red-800">
                  Se encontraron los siguientes errores:
                </h4>
                <ul className="mt-1 text-sm text-red-700 list-disc list-inside">
                  {errors.map((error, index) => (
                    <li key={index}>{error}</li>
                  ))}
                </ul>
              </div>
            </div>
          </div>
        )}

        {/* Componente de subida de archivo (solo si está en idle) */}
        {formState === 'idle' && (
          <div className="space-y-4">
            <h3 className="text-sm font-semibold border-b pb-2">Subir CV</h3>
            <div className="border-2 border-dashed border-gray-300 rounded-lg p-6 text-center">
              <Upload className="mx-auto h-8 w-8 text-gray-400" />
              <div className="mt-2">
                <label htmlFor="cv-upload" className="cursor-pointer">
                  <span className="text-sm text-blue-600 hover:text-blue-500">
                    Sube tu CV en PDF
                  </span>
                  <input
                    id="cv-upload"
                    type="file"
                    accept=".pdf"
                    className="hidden"
                    onChange={(e) => {
                      const file = e.target.files?.[0];
                      if (file) {
                        setFile(file);
                      }
                    }}
                  />
                </label>
                <span className="text-sm text-gray-500"> o </span>
                <Button
                  variant="outline"
                  size="sm"
                  onClick={switchToManual}
                >
                  Completar manualmente
                </Button>
              </div>
              <p className="text-xs text-gray-500 mt-2">
                Acepta archivos PDF hasta 10MB
              </p>
            </div>
          </div>
        )}

        {/* Estados de carga */}
        {(formState === 'uploading' || formState === 'parsing' || formState === 'saving') && (
          <div className="flex items-center justify-center p-8">
            <div className="text-center">
              <Loader2 className="mx-auto h-8 w-8 animate-spin text-blue-500" />
              <p className="mt-2 text-sm text-gray-600">
                {formState === 'uploading' && 'Subiendo archivo...'}
                {formState === 'parsing' && 'Procesando con IA...'}
                {formState === 'saving' && 'Guardando información...'}
              </p>
            </div>
          </div>
        )}

        {/* Formulario (solo si está en ready o manual) */}
        {(formState === 'ready' || formState === 'manual') && (
          <div className="space-y-6">
            {/* Información Personal */}
            <div className="space-y-4">
              <h3 className="text-sm font-semibold border-b pb-2">Información Personal</h3>

              <div className="grid grid-cols-3 gap-3">
                {renderEditableField('Nombre', 'nombre', formData.nombre)}
                {renderEditableField('Email', 'email', formData.email, 'email')}
                {renderEditableField('Teléfono', 'telefono', formData.telefono, 'tel')}
                {renderEditableField('Ubicación', 'ubicacion_actual', formData.ubicacion_actual)}
                {renderEditableField('Fecha Nacimiento', 'fecha_nacimiento', formData.fecha_nacimiento, 'date')}
                {renderEditableField('LinkedIn', 'linkedin', formData.linkedin, 'url')}
                {renderEditableField('Portfolio', 'portfolio', formData.portfolio, 'url')}
                {renderEditableField('Disponibilidad', 'disponibilidad', formData.disponibilidad)}
              </div>

              <div>
                {renderEditableField('Resumen Profesional', 'resumen_profesional', formData.resumen_profesional, 'textarea')}
              </div>
            </div>

            <Separator />

            {/* Habilidades */}
            <div className="space-y-4">
              <h3 className="text-sm font-semibold border-b pb-2">Habilidades</h3>

              <div className="grid grid-cols-3 gap-3">
                {renderSkillsSection('Hard Skills', 'hard_skills', formData.hard_skills)}
                {renderSkillsSection('Soft Skills', 'soft_skills', formData.soft_skills)}
                {renderSkillsSection('Habilidades Adicionales', 'habilidades_adicionales', formData.habilidades_adicionales)}
              </div>
            </div>

            <Separator />

            {/* Experiencia Laboral */}
            {renderExperienceSection()}

            <Separator />

            {/* Educación */}
            {renderEducationSection()}

            <Separator />

            {/* Información Adicional */}
            <div className="space-y-4">
              <h3 className="text-sm font-semibold border-b pb-2">Información Adicional</h3>

              <div className="grid grid-cols-3 gap-3">
                {renderSkillsSection('Certificaciones', 'certificaciones', formData.certificaciones)}
                {renderSkillsSection('Intereses', 'intereses', formData.intereses)}
                {renderSkillsSection('Otras Redes', 'otras_redes', formData.otras_redes)}
              </div>

              <div>
                {renderEditableField('Referencias', 'referencias', formData.referencias, 'textarea')}
              </div>
            </div>
          </div>
        )}

        <DialogFooter className="mt-6">
          <Button variant="outline" onClick={onClose} disabled={isLoading}>
            Cancelar
          </Button>
          {(formState === 'ready' || formState === 'manual') && (
            <Button onClick={handleSave} disabled={isLoading}>
              {isLoading ? 'Guardando...' : 'Guardar y Continuar'}
            </Button>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter } from '../ui/dialog';
import { Button } from '../ui/button';
import { Input } from '../ui/input';
import { Label } from '../ui/label';
import { Textarea } from '../ui/textarea';
import { Badge } from '../ui/badge';
import { Separator } from '../ui/separator';
import { CheckCircle, Edit, Save, X } from 'lucide-react';

interface CVData {
  // bt_candidates - Campos principales
  nombre?: string;
  email?: string;
  telefono?: string;
  ubicacion_actual?: string;
  fecha_nacimiento?: string;
  portfolio?: string;
  linkedin?: string;
  otras_redes?: string[];
  resumen_profesional?: string;
  soft_skills?: string[];
  hard_skills?: string[];
  idiomas?: Array<{ idioma: string; nivel: string }>;
  intereses?: string[];
  referencias?: string;
  disponibilidad?: string;
  cv_original_file?: string;
  cv_text_file?: string;
  cv_json_file?: string;
  data_source?: 'ai_processing' | 'manual_entry' | 'hybrid';

  // bt_candidate_experiences
  puestos_anteriores?: Array<{
    puesto: string;
    empresa: string;
    fecha_inicio: string;
    fecha_fin: string;
    descripcion: string;
    responsabilidades?: string[];
    ubicacion?: string;
    actual?: boolean;
  }>;

  // bt_candidate_education
  educacion?: Array<{
    titulo: string;
    campo_estudio?: string;
    institucion: string;
    fecha_inicio: string;
    fecha_fin: string;
    nivel_educativo?: string;
    descripcion?: string;
  }>;

  // bt_candidate_certifications - Detalles expandidos
  certificaciones?: string[];
  certificaciones_detalle?: Array<{
    nombre_certificacion: string;
    emisor?: string;
    fecha_emision?: string;
    fecha_expiracion?: string;
  }>;

  // bt_candidate_languages - Detalles expandidos
  idiomas_detalle?: Array<{
    idioma: string;
    nivel_competencia?: string;
  }>;

  // bt_candidate_projects
  proyectos?: Array<{
    nombre: string;
    descripcion: string;
    tecnologias?: string[];
    fecha_inicio?: string;
    fecha_fin?: string;
    url?: string;
  }>;

  // bt_candidate_references - Detalles expandidos
  referencias_detalle?: Array<{
    nombre_referencia: string;
    empresa_referencia?: string;
    email_referencia?: string;
    telefono_referencia?: string;
    notas?: string;
  }>;

  // bt_candidate_skills - Habilidades adicionales
  habilidades_adicionales?: string[];

  // bt_candidate_routing - Información de enrutamiento
  routing?: {
    categoria_departamento_id?: number;
    departamento_id?: number;
    reclutador_id?: string;
    fuente?: 'ai' | 'manual';
    razon?: string;
    fecha_asignacion?: string;
  };
}

interface CVValidationModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (validatedData: CVData) => void;
  cvData: CVData;
  isLoading?: boolean;
}

export function CVValidationModal({
  isOpen,
  onClose,
  onSave,
  cvData,
  isLoading = false
}: CVValidationModalProps) {
  const [editedData, setEditedData] = useState<CVData>(cvData);
  const [editingField, setEditingField] = useState<string | null>(null);

  const handleFieldEdit = (field: string, value: any) => {
    setEditedData(prev => ({
      ...prev,
      [field]: value
    }));
  };

  const handleArrayFieldEdit = (field: string, index: number, newValue: any) => {
    setEditedData(prev => ({
      ...prev,
      [field]: (prev[field as keyof CVData] as any[])?.map((item, i) =>
        i === index ? newValue : item
      ) || []
    }));
  };

  const addArrayItem = (field: string, emptyItem: any) => {
    setEditedData(prev => ({
      ...prev,
      [field]: [...((prev[field as keyof CVData] as any[]) || []), emptyItem]
    }));
  };

  const removeArrayItem = (field: string, index: number) => {
    setEditedData(prev => ({
      ...prev,
      [field]: (prev[field as keyof CVData] as any[])?.filter((_, i) => i !== index) || []
    }));
  };

  const handleSave = () => {
    onSave(editedData);
  };

  const renderEditableField = (label: string, field: string, value: any, type: 'text' | 'email' | 'tel' | 'date' | 'textarea' = 'text') => {
    const isEditing = editingField === field;

    return (
      <div className="space-y-1">
        <div className="flex items-center justify-between">
          <Label className="text-xs font-medium text-gray-700">{label}</Label>
          <Button
            variant="ghost"
            size="sm"
            onClick={() => setEditingField(isEditing ? null : field)}
          >
            {isEditing ? <Save className="h-3 w-3" /> : <Edit className="h-3 w-3" />}
          </Button>
        </div>

        {isEditing ? (
          type === 'textarea' ? (
            <Textarea
              value={value || ''}
              onChange={(e) => handleFieldEdit(field, e.target.value)}
              className="min-h-[50px] text-xs"
            />
          ) : (
            <Input
              type={type}
              value={value || ''}
              onChange={(e) => handleFieldEdit(field, e.target.value)}
              className="text-xs"
            />
          )
        ) : (
          <div className="p-2 bg-gray-50 rounded text-xs">
            {value || <span className="text-gray-400 italic">No especificado</span>}
          </div>
        )}
      </div>
    );
  };

  const renderSkillsSection = (label: string, field: string, skills: string[] = []) => {
    return (
      <div className="space-y-1">
        <div className="flex items-center justify-between">
          <Label className="text-xs font-medium text-gray-700">{label}</Label>
          <Button
            variant="ghost"
            size="sm"
            onClick={() => addArrayItem(field, '')}
          >
            <span className="text-xs">+</span>
          </Button>
        </div>

        <div className="space-y-1">
          {skills.map((skill, index) => (
            <div key={index} className="flex items-center space-x-1">
              <Input
                value={skill}
                onChange={(e) => handleArrayFieldEdit(field, index, e.target.value)}
                className="flex-1 text-xs"
              />
              <Button
                variant="ghost"
                size="sm"
                onClick={() => removeArrayItem(field, index)}
              >
                <X className="h-3 w-3" />
              </Button>
            </div>
          ))}
        </div>

        {skills.length === 0 && (
          <div className="p-2 bg-gray-50 rounded text-xs text-gray-400 italic">
            No hay {label.toLowerCase()}
          </div>
        )}
      </div>
    );
  };

  const renderExperienceSection = () => {
    const puestos = editedData.puestos_anteriores || [];

    return (
      <div className="space-y-4">
        <div className="flex items-center justify-between">
          <Label className="text-sm font-medium text-gray-700">Experiencia Laboral</Label>
          <Button
            variant="ghost"
            size="sm"
            onClick={() => addArrayItem('puestos_anteriores', {
              puesto: '',
              empresa: '',
              fecha_inicio: '',
              fecha_fin: '',
              descripcion: '',
              responsabilidades: [],
              ubicacion: '',
              actual: false
            })}
          >
            <span className="text-xs">Agregar</span>
          </Button>
        </div>

        {puestos.map((puesto, index) => (
          <div key={index} className="p-3 border rounded-lg space-y-2">
            <div className="flex justify-between items-start">
              <h4 className="text-xs font-medium">Puesto {index + 1}</h4>
              <Button
                variant="ghost"
                size="sm"
                onClick={() => removeArrayItem('puestos_anteriores', index)}
              >
                <X className="h-3 w-3" />
              </Button>
            </div>

            <div className="grid grid-cols-3 gap-2">
              <div>
                <Label className="text-xs">Puesto</Label>
                <Input
                  className="text-xs"
                  value={puesto.puesto}
                  onChange={(e) => handleArrayFieldEdit('puestos_anteriores', index, {
                    ...puesto,
                    puesto: e.target.value
                  })}
                />
              </div>
              <div>
                <Label className="text-xs">Empresa</Label>
                <Input
                  className="text-xs"
                  value={puesto.empresa}
                  onChange={(e) => handleArrayFieldEdit('puestos_anteriores', index, {
                    ...puesto,
                    empresa: e.target.value
                  })}
                />
              </div>
              <div>
                <Label className="text-xs">Ubicación</Label>
                <Input
                  className="text-xs"
                  value={puesto.ubicacion || ''}
                  onChange={(e) => handleArrayFieldEdit('puestos_anteriores', index, {
                    ...puesto,
                    ubicacion: e.target.value
                  })}
                />
              </div>
              <div>
                <Label className="text-xs">Fecha Inicio</Label>
                <Input
                  className="text-xs"
                  type="date"
                  value={puesto.fecha_inicio}
                  onChange={(e) => handleArrayFieldEdit('puestos_anteriores', index, {
                    ...puesto,
                    fecha_inicio: e.target.value
                  })}
                />
              </div>
              <div>
                <Label className="text-xs">Fecha Fin</Label>
                <Input
                  className="text-xs"
                  type="date"
                  value={puesto.fecha_fin}
                  onChange={(e) => handleArrayFieldEdit('puestos_anteriores', index, {
                    ...puesto,
                    fecha_fin: e.target.value
                  })}
                />
              </div>
              <div className="flex items-center space-x-2">
                <input
                  type="checkbox"
                  checked={puesto.actual || false}
                  onChange={(e) => handleArrayFieldEdit('puestos_anteriores', index, {
                    ...puesto,
                    actual: e.target.checked
                  })}
                />
                <Label className="text-xs">Actual</Label>
              </div>
            </div>

            <div>
              <Label className="text-xs">Descripción</Label>
              <Textarea
                className="text-xs min-h-[50px]"
                value={puesto.descripcion}
                onChange={(e) => handleArrayFieldEdit('puestos_anteriores', index, {
                  ...puesto,
                  descripcion: e.target.value
                })}
              />
            </div>
          </div>
        ))}

        {puestos.length === 0 && (
          <div className="p-3 bg-gray-50 rounded text-xs text-gray-400 italic">
            No se encontró experiencia laboral
          </div>
        )}
      </div>
    );
  };

  const renderEducationSection = () => {
    const educacion = editedData.educacion || [];

    return (
      <div className="space-y-4">
        <div className="flex items-center justify-between">
          <Label className="text-sm font-medium text-gray-700">Educación</Label>
          <Button
            variant="ghost"
            size="sm"
            onClick={() => addArrayItem('educacion', {
              titulo: '',
              campo_estudio: '',
              institucion: '',
              fecha_inicio: '',
              fecha_fin: '',
              nivel_educativo: '',
              descripcion: ''
            })}
          >
            <span className="text-xs">Agregar</span>
          </Button>
        </div>

        {educacion.map((edu, index) => (
          <div key={index} className="p-3 border rounded-lg space-y-2">
            <div className="flex justify-between items-start">
              <h4 className="text-xs font-medium">Educación {index + 1}</h4>
              <Button
                variant="ghost"
                size="sm"
                onClick={() => removeArrayItem('educacion', index)}
              >
                <X className="h-3 w-3" />
              </Button>
            </div>

            <div className="grid grid-cols-3 gap-2">
              <div>
                <Label className="text-xs">Título</Label>
                <Input
                  className="text-xs"
                  value={edu.titulo}
                  onChange={(e) => handleArrayFieldEdit('educacion', index, {
                    ...edu,
                    titulo: e.target.value
                  })}
                />
              </div>
              <div>
                <Label className="text-xs">Campo de Estudio</Label>
                <Input
                  className="text-xs"
                  value={edu.campo_estudio || ''}
                  onChange={(e) => handleArrayFieldEdit('educacion', index, {
                    ...edu,
