/**
 * Accessible Modal Component
 * 
 * Implements WCAG AA compliant modal with focus management,
 * keyboard navigation, and proper ARIA attributes.
 * 
 * @package Components/UI
 * @author Bubble of Talents Development Team
 * @version 1.0.0
 * @since 2025-01-05
 */

import React, { useEffect, useRef } from 'react';
import { createPortal } from 'react-dom';
import { useFocusTrap, useAnnouncer, useKeyboardNavigation } from '../../utils/accessibility';

interface AccessibleModalProps {
    isOpen: boolean;
    onClose: () => void;
    title: string;
    children: React.ReactNode;
    size?: 'sm' | 'md' | 'lg' | 'xl';
    closeOnOverlayClick?: boolean;
    closeOnEscape?: boolean;
    className?: string;
    role?: 'dialog' | 'alertdialog';
    'aria-describedby'?: string;
}

/**
 * AccessibleModal Component
 * 
 * Features:
 * - Focus trapping
 * - Keyboard navigation (Escape to close)
 * - Proper ARIA attributes
 * - Screen reader announcements
 * - Backdrop click handling
 * - Semantic HTML structure
 */
export const AccessibleModal: React.FC<AccessibleModalProps> = ({
    isOpen,
    onClose,
    title,
    children,
    size = 'md',
    closeOnOverlayClick = true,
    closeOnEscape = true,
    className = '',
    role = 'dialog',
    'aria-describedby': ariaDescribedBy,
}) => {
    const modalRef = useFocusTrap(isOpen) as React.RefObject<HTMLDivElement>;
    const announce = useAnnouncer();
    const previousActiveElement = useRef<HTMLElement | null>(null);

    // Store focus before opening modal
    useEffect(() => {
        if (isOpen) {
            previousActiveElement.current = document.activeElement as HTMLElement;
            announce(`${role === 'alertdialog' ? 'Alert dialog' : 'Dialog'} opened: ${title}`, 'polite');
            // Prevent body scroll
            document.body.style.overflow = 'hidden';
        } else {
            // Restore body scroll
            document.body.style.overflow = '';
            // Restore focus
            if (previousActiveElement.current) {
                previousActiveElement.current.focus();
            }
        }

        return () => {
            document.body.style.overflow = '';
        };
    }, [isOpen, announce, title, role]);

    // Keyboard navigation
    if (closeOnEscape) {
        useKeyboardNavigation({
            onEscape: onClose,
        });
    } else {
        useKeyboardNavigation({});
    }

    // Handle overlay click
    const handleOverlayClick = (event: React.MouseEvent) => {
        if (closeOnOverlayClick && event.target === event.currentTarget) {
            onClose();
        }
    };

    // Size classes
    const sizeClasses = {
        sm: 'max-w-sm',
        md: 'max-w-md',
        lg: 'max-w-lg',
        xl: 'max-w-xl',
    };

    if (!isOpen) return null;

    const modalContent = (
        <div
            className="fixed inset-0 z-50 overflow-y-auto"
            role="presentation"
        >
            {/* Backdrop */}
            <div
                className="fixed inset-0 bg-black bg-opacity-50 transition-opacity"
                onClick={handleOverlayClick}
                aria-hidden="true"
            />

            {/* Modal container */}
            <div className="flex min-h-full items-center justify-center p-4">
                <div
                    ref={modalRef}
                    role={role}
                    aria-modal="true"
                    aria-labelledby="modal-title"
                    aria-describedby={ariaDescribedBy}
                    className={`
                        relative w-full ${sizeClasses[size]} 
                        bg-white rounded-lg shadow-xl 
                        transform transition-all
                        ${className}
                    `}
                >
                    {/* Header */}
                    <div className="flex items-center justify-between p-6 border-b border-gray-200">
                        <h2
                            id="modal-title"
                            className="text-xl font-semibold text-gray-900"
                        >
                            {title}
                        </h2>
                        <button
                            type="button"
                            onClick={onClose}
                            className="
                                rounded-md text-gray-400 hover:text-gray-600 
                                focus:outline-none focus:ring-2 focus:ring-blue-500
                                p-2 -m-2
                            "
                            aria-label="Close dialog"
                        >
                            <svg
                                className="h-6 w-6"
                                fill="none"
                                viewBox="0 0 24 24"
                                stroke="currentColor"
                                aria-hidden="true"
                            >
                                <path
                                    strokeLinecap="round"
                                    strokeLinejoin="round"
                                    strokeWidth={2}
                                    d="M6 18L18 6M6 6l12 12"
                                />
                            </svg>
                        </button>
                    </div>

                    {/* Content */}
                    <div className="p-6">
                        {children}
                    </div>
                </div>
            </div>
        </div>
    );

    // Render in portal to avoid z-index issues
    return createPortal(modalContent, document.body);
};

export default AccessibleModal;

/**
 * Componente AdaptiveImage
 * 
 * Este componente extiende las capacidades de LazyImage para trabajar
 * de forma óptima con conexiones lentas o sin conexión.
 * Características:
 * - Carga imágenes progresivamente con baja calidad primero
 * - Maneja casos sin conexión con placeholders o imágenes en caché
 * - Adapta la estrategia según la calidad de conexión
 * - Reintentos inteligentes para conexiones inestables
 */

import React, { useState, useEffect } from 'react';
import { useOnlineStatus } from '../../hooks/useOnlineStatus';

interface AdaptiveImageProps extends React.ImgHTMLAttributes<HTMLImageElement> {
  src: string;
  alt: string;
  fallbackSrc?: string;
  lowQualitySrc?: string;
  placeholderColor?: string;
  retryCount?: number;
  retryDelay?: number;
  threshold?: number;
  loadingIndicator?: React.ReactNode;
  offline?: boolean;
}

const AdaptiveImage: React.FC<AdaptiveImageProps> = ({
  src,
  alt,
  fallbackSrc,
  lowQualitySrc,
  placeholderColor = '#f1f5f9',
  retryCount = 3,
  retryDelay = 2000,
  threshold = 0.1,
  loadingIndicator,
  offline = false,
  ...props
}) => {
  const [loaded, setLoaded] = useState(false);
  const [error, setError] = useState(false);
  const [retry, setRetry] = useState(0);
  const [imageSrc, setImageSrc] = useState<string>(lowQualitySrc || src);
  const { isOnline, connectionQuality } = useOnlineStatus();

  // Estilos base para el contenedor y la imagen
  const containerStyle: React.CSSProperties = {
    position: 'relative',
    overflow: 'hidden',
    backgroundColor: placeholderColor,
    width: props.width ? `${props.width}px` : '100%',
    height: props.height ? `${props.height}px` : 'auto',
    ...(props.style as React.CSSProperties),
  };

  const imageStyle: React.CSSProperties = {
    display: 'block',
    width: '100%',
    height: '100%',
    objectFit: (props as any).objectFit || 'cover',
    transition: 'opacity 0.3s ease-in-out, filter 0.5s ease-in-out',
    opacity: loaded ? 1 : 0,
    filter: loaded ? 'none' : 'blur(10px)',
  };

  // Manejar carga de imagen con reintentos
  useEffect(() => {
    if (!isOnline && offline) {
      // Si estamos sin conexión y la imagen tiene modo offline, no intentamos cargar
      return undefined;
    }

    let isMounted = true;
    let retryTimeout: NodeJS.Timeout;

    const img = new Image();

    const handleLoad = () => {
      if (isMounted) {
        if (lowQualitySrc && img.src !== src) {
          // Si cargamos primero la versión de baja calidad, ahora cargar la versión completa
          img.src = src;
        } else {
          setLoaded(true);
          setImageSrc(src);
        }
      }
    };

    const handleError = () => {
      if (isMounted) {
        if (retry < retryCount && isOnline) {
          // Reintentar después de un retraso
          retryTimeout = setTimeout(() => {
            setRetry(prev => prev + 1);
          }, retryDelay);
        } else {
          setError(true);
          // Usar imagen de respaldo si está disponible
          if (fallbackSrc) {
            setImageSrc(fallbackSrc);
            setLoaded(true);
          }
        }
      }
    };

    // Determinar la estrategia de carga según la calidad de conexión
    const loadImage = () => {
      img.onload = handleLoad;
      img.onerror = handleError;

      // Si la conexión es lenta, priorizar la versión de baja calidad
      if (connectionQuality === 'poor' && lowQualitySrc) {
        img.src = lowQualitySrc;
      } else {
        img.src = src;
      }
    };

    loadImage();

    return () => {
      isMounted = false;
      clearTimeout(retryTimeout);
      img.onload = null;
      img.onerror = null;
    };
  }, [
    src,
    lowQualitySrc,
    fallbackSrc,
    retry,
    retryCount,
    retryDelay,
    isOnline,
    connectionQuality,
    offline
  ]);

  // Usar IntersectionObserver para carga perezosa si está disponible
  useEffect(() => {
    // Saltarse si la imagen ya está cargada o no hay soporte para IntersectionObserver
    if (loaded || !('IntersectionObserver' in window)) {
      return undefined;
    }

    const imgElement = document.getElementById(`adaptive-img-${src.replace(/\W/g, '')}`);
    if (!imgElement) return undefined;

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            // Actualizar la estrategia de carga cuando la imagen entra en el viewport
            observer.unobserve(imgElement);
          }
        });
      },
      { threshold }
    );

    observer.observe(imgElement);

    return () => {
      observer.unobserve(imgElement);
    };
  }, [src, loaded, threshold]);

  // Mostrar placeholder en modo offline si no está marcada como disponible offline
  if (!isOnline && !offline) {
    return (
      <div style={containerStyle} className={props.className}>
        <div
          style={{
            width: '100%',
            height: '100%',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            backgroundColor: placeholderColor,
            color: '#64748b',
            fontSize: '0.875rem',
          }}
        >
          <span>Imagen no disponible sin conexión</span>
        </div>
      </div>
    );
  }

  return (
    <div style={containerStyle} className={props.className}>
      <img
        id={`adaptive-img-${src.replace(/\W/g, '')}`}
        src={imageSrc}
        alt={alt}
        style={imageStyle}
        loading="lazy"
        onLoad={() => setLoaded(true)}
        onError={() => setError(true)}
        {...props}
      />

      {!loaded && !error && (
        <div
          style={{
            position: 'absolute',
            top: 0,
            left: 0,
            width: '100%',
            height: '100%',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            backgroundColor: placeholderColor,
          }}
        >
          {loadingIndicator || (
            <div style={{ width: '24px', height: '24px', border: '2px solid #e2e8f0', borderTopColor: '#3b82f6', borderRadius: '50%', animation: 'spin 1s linear infinite' }} />
          )}
        </div>
      )}

      {error && !fallbackSrc && (
        <div
          style={{
            position: 'absolute',
            top: 0,
            left: 0,
            width: '100%',
            height: '100%',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            backgroundColor: placeholderColor,
            color: '#64748b',
            fontSize: '0.875rem',
          }}
        >
          <span>Error al cargar la imagen</span>
        </div>
      )}

      <style dangerouslySetInnerHTML={{
        __html: `
        @keyframes spin {
          0% { transform: rotate(0deg); }
          100% { transform: rotate(360deg); }
        }
        `
      }} />
    </div>
  );
};

export default AdaptiveImage;

/**
 * Componente OfflineDetector
 * 
 * Este componente monitorea el estado de conectividad y muestra
 * notificaciones apropiadas cuando el usuario está sin conexión o
 * cuando la conexión se recupera.
 */

import React, { useEffect, useState } from 'react';
import { useOnlineStatus } from '../../hooks/useOnlineStatus';

// Estilos para las notificaciones
const notificationStyles = {
  container: {
    position: 'fixed',
    bottom: '20px',
    left: '50%',
    transform: 'translateX(-50%)',
    zIndex: 9999,
    display: 'flex',
    flexDirection: 'column',
    gap: '10px',
    width: '90%',
    maxWidth: '400px',
  } as React.CSSProperties,
  notification: {
    padding: '12px 16px',
    borderRadius: '8px',
    boxShadow: '0 4px 12px rgba(0, 0, 0, 0.15)',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'space-between',
    animation: 'slideUp 0.3s ease-out forwards',
  } as React.CSSProperties,
  offline: {
    backgroundColor: '#fef2f2',
    color: '#b91c1c',
    border: '1px solid #fee2e2',
  },
  online: {
    backgroundColor: '#ecfdf5',
    color: '#047857',
    border: '1px solid #d1fae5',
  },
  icon: {
    marginRight: '12px',
    fontSize: '1.2rem',
  },
  message: {
    flex: 1,
    fontSize: '0.9rem',
    fontWeight: 500,
  },
  closeButton: {
    background: 'none',
    border: 'none',
    cursor: 'pointer',
    fontSize: '1rem',
    color: 'inherit',
    opacity: 0.7,
  },
};

type Notification = {
  id: string;
  type: 'offline' | 'online';
  message: string;
  autoClose?: boolean;
};

const OfflineDetector: React.FC = () => {
  const { isOnline, wasOffline, connectionQuality } = useOnlineStatus();
  const [notifications, setNotifications] = useState<Notification[]>([]);

  // Añadir una notificación
  const addNotification = (type: 'offline' | 'online', message: string, autoClose = true) => {
    const id = Date.now().toString();
    setNotifications(prev => [...prev, { id, type, message, autoClose }]);

    // Auto-cerrar después de 5 segundos si autoClose es true
    if (autoClose) {
      setTimeout(() => {
        removeNotification(id);
      }, 5000);
    }
  };

  // Eliminar una notificación
  const removeNotification = (id: string) => {
    setNotifications(prev => prev.filter(notification => notification.id !== id));
  };

  // Mostrar notificaciones según el cambio de estado de conexión
  useEffect(() => {
    if (!isOnline) {
      addNotification(
        'offline',
        'Sin conexión a Internet. Algunas funciones pueden no estar disponibles.',
        false
      );
    } else if (wasOffline) {
      addNotification(
        'online',
        'Conexión restablecida. Todas las funciones están disponibles.',
        true
      );
    }
  }, [isOnline, wasOffline]);

  // Mostrar advertencia si la calidad de conexión es mala
  useEffect(() => {
    if (isOnline && connectionQuality === 'poor') {
      addNotification(
        'offline',
        'Conexión a Internet inestable. El rendimiento puede verse afectado.',
        true
      );
    }
  }, [connectionQuality, isOnline]);

  if (notifications.length === 0) {
    return null;
  }

  return (
    <div style={notificationStyles.container}>
      {notifications.map((notification) => (
        <div
          key={notification.id}
          style={{
            ...notificationStyles.notification,
            ...(notification.type === 'offline' ? notificationStyles.offline : notificationStyles.online),
          }}
        >
          <span style={notificationStyles.icon}>
            {notification.type === 'offline' ? '📶' : '✅'}
          </span>
          <span style={notificationStyles.message}>{notification.message}</span>
          <button
            style={notificationStyles.closeButton}
            onClick={() => removeNotification(notification.id)}
            aria-label="Cerrar notificación"
          >
            ×
          </button>
        </div>
      ))}
    </div>
  );
};

export default OfflineDetector;

