interface SocialAuthData {
    token?: string;
    access_token?: string;
    id_token?: string;
    provider_user_id?: string;
    email?: string;
    name?: string;
    picture?: string;
}

// Extendemos la interfaz User importada para mantener compatibilidad
interface AuthContextType {
    isLoggedIn: boolean;
    user: User | null;
    isLoading: boolean;
    login: (email: string, password: string, rememberMe?: boolean) => Promise<boolean>;
    candidateLogin: (email: string, password: string) => Promise<boolean>;
    staffLogin: (email: string, password: string) => Promise<boolean>;
    loginWithSocial: (provider: string, userData: SocialAuthData) => Promise<boolean>;
    logout: () => Promise<void>;
    refreshSession: () => Promise<void>;
    isInitialized: boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

// Exportar el contexto explícitamente
export { AuthContext };

export function AuthProvider({ children }: { children: ReactNode }) {
    const [isLoggedIn, setIsLoggedIn] = useState<boolean>(false);
    const [user, setUser] = useState<User | null>(null);
    const [isLoading, setIsLoading] = useState<boolean>(true);
    const [isInitialized, setIsInitialized] = useState<boolean>(false);

    useEffect(() => {
        initializeAuth();
    }, []);

    const initializeAuth = async () => {
        try {
            setIsLoading(true);

            // Intentar verificar sesión con cookies HTTP-only
            const { isValid, user: sessionUser } = await SecureAuthManager.verifySession();

            if (isValid && sessionUser) {
                setUser(sessionUser);
                setIsLoggedIn(true);
                console.log('Session restored from secure cookies');
            } else {
                // Si no existe una sesión válida, no intentamos restaurar
                // credenciales desde localStorage.  El uso de localStorage
                // para tokens de autenticación está desaconsejado, tal como
                // se indicó en la auditoría, ya que queda expuesto a XSS.
                setUser(null);
                setIsLoggedIn(false);
                console.log('No valid session found');
            }

            setIsInitialized(true);
        } catch (error) {
            console.error('Auth initialization error:', error);
            setUser(null);
            setIsLoggedIn(false);
            setIsInitialized(true);
        } finally {
            setIsLoading(false);
        }
    };

    const login = async (email: string, password: string, rememberMe = false): Promise<boolean> => {
        try {
            setIsLoading(true);

            // Sanitizar email
            const sanitizedEmail = InputSanitizer.sanitizeEmail(email);
            if (!sanitizedEmail) {
                console.error('Login failed: invalid email format');
                return false;
            }

            // Intentar login seguro
            const credentials: LoginCredentials = {
                email: sanitizedEmail,
                password, // No sanitizamos la contraseña
                rememberMe
            };

            const authResponse = await SecureAuthManager.login(credentials);

            if (authResponse.success && authResponse.user) {
                setUser(authResponse.user);
                setIsLoggedIn(true);

                // Limpiar localStorage si existía (migración completa)
                localStorage.removeItem('isLoggedIn');
                localStorage.removeItem('userEmail');
                localStorage.removeItem('userId');
                localStorage.removeItem('userRole');
                localStorage.removeItem('userName');

                console.log('Secure login successful');
                return true;
            } else {
                console.error('Login failed:', authResponse.message);
                return false;
            }
        } catch (error) {
            console.error('Login error:', error);
            return false;
        } finally {
            setIsLoading(false);
        }
    };

    const candidateLogin = async (email: string, password: string): Promise<boolean> => {
        try {
            setIsLoading(true);

            // Sanitizar email
            const sanitizedEmail = InputSanitizer.sanitizeEmail(email);
            if (!sanitizedEmail) {
                console.error('Candidate login failed: invalid email format');
                return false;
            }

            // Intentar candidate login usando endpoint específico
            const credentials: LoginCredentials = {
                email: sanitizedEmail,
                password, // No sanitizamos la contraseña
                rememberMe: false
            };

            const authResponse = await SecureAuthManager.candidateLogin(credentials);

            if (authResponse.success && authResponse.user) {
                setUser(authResponse.user);
                setIsLoggedIn(true);

                console.log('Secure candidate login successful');
                return true;
            } else {
                console.error('Candidate login failed:', authResponse.message);
                return false;
            }
        } catch (error) {
            console.error('Candidate login error:', error);
            return false;
        } finally {
            setIsLoading(false);
        }
    };

    const staffLogin = async (email: string, password: string): Promise<boolean> => {
        try {
            setIsLoading(true);

            // Sanitizar email
            const sanitizedEmail = InputSanitizer.sanitizeEmail(email);
            if (!sanitizedEmail) {
                console.error('Staff login failed: invalid email format');
                return false;
            }

            // Intentar staff login usando endpoint específico
            const credentials: LoginCredentials = {
                email: sanitizedEmail,
                password, // No sanitizamos la contraseña
                rememberMe: false
            };

            const authResponse = await SecureAuthManager.staffLogin(credentials);

            if (authResponse.success && authResponse.user) {
                setUser(authResponse.user);
                setIsLoggedIn(true);

                console.log('Secure staff login successful');
                return true;
            } else {
                console.error('Staff login failed:', authResponse.message);
                return false;
            }
        } catch (error) {
            console.error('Staff login error:', error);
            return false;
        } finally {
            setIsLoading(false);
        }
    };

    const loginWithSocial = async (provider: string, userData: SocialAuthData): Promise<boolean> => {
        try {
            setIsLoading(true);

            // Sanitizar provider
            const sanitizedProvider = InputSanitizer.sanitizeText(provider);

            // Usar método seguro de login social
            const authResponse = await SecureAuthManager.socialLogin(sanitizedProvider, userData.token || userData.access_token || '');

            if (authResponse.success && authResponse.user) {
                setUser(authResponse.user);
                setIsLoggedIn(true);

                // Limpiar localStorage si existía (migración completa)
                localStorage.removeItem('isLoggedIn');
                localStorage.removeItem('userEmail');
                localStorage.removeItem('userId');
                localStorage.removeItem('userRole');
                localStorage.removeItem('userName');

                console.log(`Secure ${provider} login successful`);
                return true;
            } else {
                console.error('Social login failed:', authResponse.message);
                return false;
            }
        } catch (error) {
            console.error('Social login error:', error);
            return false;
        } finally {
            setIsLoading(false);
        }
    };

    const logout = async (): Promise<void> => {
        try {
            setIsLoading(true);

            // Usar método seguro de logout
            await SecureAuthManager.logout();

            // Limpiar estado local
            setUser(null);
            setIsLoggedIn(false);

            // Asegurar que localStorage también esté limpio
            localStorage.removeItem('isLoggedIn');
            localStorage.removeItem('userEmail');
            localStorage.removeItem('userId');
            localStorage.removeItem('userRole');
            localStorage.removeItem('userName');

            console.log('Secure logout successful');
        } catch (error) {
            console.error('Logout error:', error);
            // Forzar limpieza local incluso si hay error
            setUser(null);
            setIsLoggedIn(false);
        } finally {
            setIsLoading(false);
        }
    };

    const refreshSession = async (): Promise<void> => {
        try {
            console.log('Refreshing session...');

            // Usar método seguro de refresh
            const success = await SecureAuthManager.refreshToken();

            if (success) {
                // Actualizar usuario después del refresh
                const { isValid, user: refreshedUser } = await SecureAuthManager.verifySession();
                if (isValid && refreshedUser) {
                    setUser(refreshedUser);
                }
                console.log('Session refreshed successfully');
            } else {
                console.log('Session refresh failed, logging out');
                await logout();
            }
        } catch (error) {
            console.error('Session refresh error:', error);
            await logout();
        }
    };

    const value: AuthContextType = {
        isLoggedIn,
        user,
        isLoading,
        login,
        candidateLogin,
        staffLogin,
        loginWithSocial,
        logout,
        refreshSession,
        isInitialized
    };

    return (
        <AuthContext.Provider value={value}>
            {children}
        </AuthContext.Provider>
    );
}

// Hook personalizado para usar el contexto
export function useAuth() {
    const context = useContext(AuthContext);
    if (context === undefined) {
        throw new Error('useAuth must be used within an AuthProvider');
    }
    return context;
}

// Export por defecto
export default AuthContext;

import { createContext, useContext, ReactNode } from 'react';

// Definir tipos simples para evitar problemas
interface User {
  id: string;
  email: string;
  role: string;
  name?: string;
}

interface AuthContextType {
  isLoggedIn: boolean;
  user: User | null;
  isLoading: boolean;
  login: (email: string, password: string, rememberMe?: boolean) => Promise<boolean>;
  logout: () => Promise<void>;
  refreshSession: () => Promise<void>;
  isInitialized: boolean;
}

// Crear el contexto
const AuthContext = createContext<AuthContextType | undefined>(undefined);

// Provider simple para evitar problemas de compilación
export function AuthProvider({ children }: { children: ReactNode }) {
  // Valores por defecto para que compile en producción
  const value: AuthContextType = {
    isLoggedIn: false,
    user: null,
    isLoading: false,
    login: async () => false,
    logout: async () => { },
    refreshSession: async () => { },
    isInitialized: true
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
}

// Hook para usar el contexto
export function useAuth(): AuthContextType {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
}

export default AuthContext;

import React, { createContext, useContext, useReducer, ReactNode } from 'react';
import {
  CvFormContextState,
  CvFormAction,
  cvFormReducer,
  initialCvFormState,
  CvFormData,
  CvFormState
} from '../domain/cvSchema';

/**
 * Contexto React para el estado global del formulario CV
 * 
 * Maneja los estados finitos:
 * - idle: aún no subió PDF
 * - uploading: subiendo archivo
 * - parsing: esperando IA
 * - ready: form con datos pre-rellenados
 * - manual: falló IA o usuario elige carga manual
 * - saving: enviando confirmación
 */

interface CvFormContextType {
  state: CvFormContextState;
  dispatch: React.Dispatch<CvFormAction>;

  // Actions helpers
  setFormState: (newState: CvFormState) => void;
  setFormData: (data: CvFormData) => void;
  updateField: (field: keyof CvFormData, value: any) => void;
  setErrors: (errors: string[]) => void;
  setLoading: (loading: boolean) => void;
  setFile: (file: File) => void;
  resetForm: () => void;
  prefillFromAI: (data: CvFormData) => void;
  switchToManual: () => void;
}

const CvFormContext = createContext<CvFormContextType | undefined>(undefined);

interface CvFormProviderProps {
  children: ReactNode;
}

export const CvFormProvider: React.FC<CvFormProviderProps> = ({ children }) => {
  const [state, dispatch] = useReducer(cvFormReducer, initialCvFormState);

  // Helper functions para simplificar el uso
  const setFormState = (newState: CvFormState) => {
    dispatch({ type: 'SET_STATE', payload: newState });
  };

  const setFormData = (data: CvFormData) => {
    dispatch({ type: 'SET_DATA', payload: data });
  };

  const updateField = (field: keyof CvFormData, value: any) => {
    dispatch({ type: 'UPDATE_FIELD', payload: { field, value } });
  };

  const setErrors = (errors: string[]) => {
    dispatch({ type: 'SET_ERRORS', payload: errors });
  };

  const setLoading = (loading: boolean) => {
    dispatch({ type: 'SET_LOADING', payload: loading });
  };

  const setFile = (file: File) => {
    dispatch({ type: 'SET_FILE', payload: file });
  };

  const resetForm = () => {
    dispatch({ type: 'RESET_FORM' });
  };

  const prefillFromAI = (data: CvFormData) => {
    dispatch({ type: 'PREFILL_FROM_AI', payload: data });
  };

  const switchToManual = () => {
    dispatch({ type: 'SWITCH_TO_MANUAL' });
  };

  const contextValue: CvFormContextType = {
    state,
    dispatch,
    setFormState,
    setFormData,
    updateField,
    setErrors,
    setLoading,
    setFile,
    resetForm,
    prefillFromAI,
    switchToManual
  };

  return (
    <CvFormContext.Provider value={contextValue}>
      {children}
    </CvFormContext.Provider>
  );
};

// Hook personalizado para usar el contexto
export const useCvForm = (): CvFormContextType => {
  const context = useContext(CvFormContext);
  if (!context) {
    throw new Error('useCvForm debe ser usado dentro de un CvFormProvider');
  }
  return context;
};

// Hook para obtener solo el estado actual
export const useCvFormState = () => {
  const { state } = useCvForm();
  return state;
};

// Hook para obtener solo los datos del formulario
export const useCvFormData = () => {
  const { state } = useCvForm();
  return state.data;
};

// Hook para obtener solo el estado finito actual
export const useCvFormCurrentState = () => {
  const { state } = useCvForm();
  return state.state;
};

import React, { createContext, useContext, useEffect, useState } from 'react';

interface PerformanceContextType {
  metrics: {
    fcp: number | null; // First Contentful Paint
    lcp: number | null; // Largest Contentful Paint
    fid: number | null; // First Input Delay
    cls: number | null; // Cumulative Layout Shift
    ttfb: number | null; // Time to First Byte
    networkInfo: {
      effectiveType: string | null;
      downlink: number | null;
      rtt: number | null;
    };
  };
  isLowEndDevice: boolean;
  isLowEndNetwork: boolean;
  prefetch: (url: string, as?: string) => void;
  preconnect: (url: string, crossorigin?: boolean) => void;
}

const defaultContext: PerformanceContextType = {
  metrics: {
    fcp: null,
    lcp: null,
    fid: null,
    cls: null,
    ttfb: null,
    networkInfo: {
      effectiveType: null,
      downlink: null,
      rtt: null
    }
  },
  isLowEndDevice: false,
  isLowEndNetwork: false,
  prefetch: () => { },
  preconnect: () => { }
};

const PerformanceContext = createContext<PerformanceContextType>(defaultContext);

export const usePerformance = () => useContext(PerformanceContext);

interface PerformanceProviderProps {
  children: React.ReactNode;
}

export const PerformanceProvider: React.FC<PerformanceProviderProps> = ({ children }) => {
  const [metrics, setMetrics] = useState(defaultContext.metrics);
  const [isLowEndDevice, setIsLowEndDevice] = useState(false);
  const [isLowEndNetwork, setIsLowEndNetwork] = useState(false);

  // Detectar dispositivos y redes de bajo rendimiento
  useEffect(() => {
    // Detectar dispositivos de bajo rendimiento
    const deviceMemory = (navigator as any).deviceMemory;
    const hardwareConcurrency = navigator.hardwareConcurrency || 0;

    if (deviceMemory && deviceMemory < 4 || hardwareConcurrency < 4) {
      setIsLowEndDevice(true);
    }

    // Detectar conexiones de red lentas
    if ('connection' in navigator) {
      const connection = (navigator as any).connection;

      if (connection) {
        const effectiveType = connection.effectiveType;
        const downlink = connection.downlink;

        setMetrics(prev => ({
          ...prev,
          networkInfo: {
            effectiveType: effectiveType || null,
            downlink: downlink || null,
            rtt: connection.rtt || null
          }
        }));

        if (effectiveType === 'slow-2g' || effectiveType === '2g' || effectiveType === '3g' || downlink < 1) {
          setIsLowEndNetwork(true);
        }

        // Escuchar cambios en la conexión
        connection.addEventListener('change', () => {
          setMetrics(prev => ({
            ...prev,
            networkInfo: {
              effectiveType: connection.effectiveType || null,
              downlink: connection.downlink || null,
              rtt: connection.rtt || null
            }
          }));

          setIsLowEndNetwork(
            connection.effectiveType === 'slow-2g' ||
            connection.effectiveType === '2g' ||
            connection.effectiveType === '3g' ||
            connection.downlink < 1
          );
        });
      }
    }
  }, []);

  // Medir Web Vitals
  useEffect(() => {
    if (typeof window !== 'undefined' && 'PerformanceObserver' in window) {
      // First Contentful Paint (FCP)
      const fcpObserver = new PerformanceObserver((entryList) => {
        const entries = entryList.getEntries();
        if (entries.length > 0) {
          const fcp = entries[0].startTime;
          setMetrics(prev => ({ ...prev, fcp }));
        }
      });

      try {
        fcpObserver.observe({ type: 'paint', buffered: true });
      } catch (e) {
        console.warn('FCP measurement not supported', e);
      }

      // Largest Contentful Paint (LCP)
      const lcpObserver = new PerformanceObserver((entryList) => {
        const entries = entryList.getEntries();
        const lastEntry = entries[entries.length - 1];
        if (lastEntry) {
          const lcp = lastEntry.startTime;
          setMetrics(prev => ({ ...prev, lcp }));
        }
      });

      try {
        lcpObserver.observe({ type: 'largest-contentful-paint', buffered: true });
      } catch (e) {
        console.warn('LCP measurement not supported', e);
      }

      // First Input Delay (FID)
      const fidObserver = new PerformanceObserver((entryList) => {
        const entries = entryList.getEntries();
        if (entries.length > 0) {
          const firstInput = entries[0];
          const fid = firstInput.processingStart - firstInput.startTime;
          setMetrics(prev => ({ ...prev, fid }));
        }
      });

      try {
        fidObserver.observe({ type: 'first-input', buffered: true });
      } catch (e) {
        console.warn('FID measurement not supported', e);
      }

      // Layout Shifts (CLS)
      let clsValue = 0;
      const clsEntries: any[] = [];

      const clsObserver = new PerformanceObserver((entryList) => {
        const entries = entryList.getEntries() as any[];

        entries.forEach(entry => {
          // Solo contar si no fue causado por interacción del usuario
          if (!entry.hadRecentInput) {
            clsValue += entry.value;
            clsEntries.push(entry);
            setMetrics(prev => ({ ...prev, cls: clsValue }));
          }
        });
      });

      try {
        clsObserver.observe({ type: 'layout-shift', buffered: true });
      } catch (e) {
        console.warn('CLS measurement not supported', e);
      }

      // Time to First Byte (TTFB)
      const navigationEntries = performance.getEntriesByType('navigation');
      if (navigationEntries.length > 0) {
        const navigationEntry = navigationEntries[0] as PerformanceNavigationTiming;
        const ttfb = navigationEntry.responseStart;
        setMetrics(prev => ({ ...prev, ttfb }));
      }

      return () => {
        fcpObserver.disconnect();
        lcpObserver.disconnect();
        fidObserver.disconnect();
        clsObserver.disconnect();
      };
    }

    return undefined;
  }, []);

  // Función para prefetch de recursos
  const prefetch = (url: string, as: string = 'fetch') => {
    if (isLowEndNetwork) return; // No hacer prefetch en redes lentas

    const linkElement = document.createElement('link');
    linkElement.rel = 'prefetch';
    linkElement.href = url;
    linkElement.as = as;
    document.head.appendChild(linkElement);
  };

  // Función para preconnect a orígenes
  const preconnect = (url: string, crossorigin: boolean = true) => {
    const linkElement = document.createElement('link');
    linkElement.rel = 'preconnect';
    linkElement.href = url;
    if (crossorigin) {
      linkElement.crossOrigin = 'anonymous';
    }
    document.head.appendChild(linkElement);
  };

  return (
    <PerformanceContext.Provider
      value={{
        metrics,
        isLowEndDevice,
        isLowEndNetwork,
        prefetch,
        preconnect
      }}
    >
      {children}
    </PerformanceContext.Provider>
  );
};

export default PerformanceProvider;

/**
 * Schema unificado para CV - espejo del contrato backend
 * 
 * Proporciona:
 * - CvFormData: tipado TypeScript completo
 * - cvTemplate: estructura base para el formulario
 * - Estados finitos del formulario
 */

// Estados finitos del formulario CV
export type CvFormState =
  | 'idle'      // aún no subió PDF
  | 'uploading' // subiendo archivo
  | 'parsing'   // esperando IA
  | 'ready'     // form con datos pre-rellenados
  | 'manual'    // falló IA o usuario elige carga manual
  | 'saving';   // enviando confirmación

// Tipo para idiomas simples
export interface IdiomaSimple {
  idioma: string;
  nivel: string;
}

// Tipo para experiencia laboral
export interface ExperienciaLaboral {
  puesto: string;
  empresa: string;
  fecha_inicio: string;
  fecha_fin: string;
  descripcion: string;
  responsabilidades?: string[];
  ubicacion?: string;
  actual?: boolean;
}

// Tipo para educación
export interface Educacion {
  titulo: string;
  campo_estudio?: string;
  institucion: string;
  fecha_inicio: string;
  fecha_fin: string;
  nivel_educativo?: string;
  descripcion?: string;
}

// Tipo para certificación detallada
export interface CertificacionDetalle {
  nombre_certificacion: string;
  emisor?: string;
  fecha_emision?: string;
  fecha_expiracion?: string;
}

// Tipo para idioma detallado
export interface IdiomaDetalle {
  idioma: string;
  nivel_competencia?: string;
}

// Tipo para proyecto
