}

interface CVAnalysisStats {
  totalFiles: number;
  completedAnalysis: number;
  averageScore: number;
  topSkills: Array<{ skill: string; frequency: number }>;
  experienceDistribution: Array<{ range: string; count: number }>;
  educationLevels: Array<{ level: string; count: number }>;
  languageDistribution: Array<{ language: string; count: number }>;
  locationDistribution: Array<{ location: string; count: number }>;
}

interface UseCVAnalysisReturn {
  // Estado
  files: CVFile[];
  processing: boolean;
  error: string | null;
  stats: CVAnalysisStats;
  batchProgress: number;

  // Acciones principales
  uploadFiles: (files: FileList | File[]) => Promise<void>;
  analyzeCV: (fileId: string, options?: Partial<CVAnalysisRequest>) => Promise<void>;
  analyzeBatch: (fileIds?: string[], options?: Partial<CVAnalysisRequest>) => Promise<void>;
  removeFile: (fileId: string) => void;
  clearAll: () => void;
  retryAnalysis: (fileId: string) => Promise<void>;

  // Funcionalidades avanzadas
  compareCVs: (fileId1: string, fileId2: string) => Promise<CVComparisonResult>;
  rankCVs: (positionRequirements: CVAnalysisFilters) => CVFile[];
  searchCVs: (query: string, filters?: CVAnalysisFilters) => CVFile[];
  exportResults: (format: 'json' | 'csv' | 'pdf') => Promise<string | Blob>;

  // Utilidades
  getFilteredFiles: (filters: CVAnalysisFilters) => CVFile[];
  getTopCandidates: (count: number, criteria?: 'score' | 'experience' | 'skills') => CVFile[];
  generateReport: (fileIds?: string[]) => Promise<{
    summary: string;
    insights: string[];
    recommendations: string[];
    charts: any[];
  }>;

  // Validación y helpers
  validateFile: (file: File) => { valid: boolean; error?: string };
  getFilePreview: (fileId: string) => Promise<string>;
  downloadOriginal: (fileId: string) => void;

  // Estado de configuración
  config: UseCVAnalysisProps;
  updateConfig: (newConfig: Partial<UseCVAnalysisProps>) => void;
}

const useCVAnalysis = ({
  autoAnalyze = true,
  batchProcessing = false,
  maxFileSize = 10, // 10MB por defecto
  supportedFormats = ['pdf', 'doc', 'docx', 'txt'],
  enhancedAnalysis = true,
  realTimeProcessing = false
}: UseCVAnalysisProps = {}): UseCVAnalysisReturn => {

  // Estado principal
  const [state, setState] = useState<CVAnalysisState>({
    files: [],
    processing: false,
    error: null,
    totalProcessed: 0,
    successCount: 0,
    errorCount: 0,
    averageProcessingTime: 0,
    batchProgress: 0
  });

  // Configuración del hook
  const [config, setConfig] = useState({
    autoAnalyze,
    batchProcessing,
    maxFileSize,
    supportedFormats,
    enhancedAnalysis,
    realTimeProcessing
  });

  // Servicio de análisis de CV
  const cvAnalysisService = useMemo(() => new CVAnalysisService(), []);

  // Referencias para tracking de progreso
  const progressRef = useRef<{ [fileId: string]: number }>({});
  const processingTimesRef = useRef<number[]>([]);

  // Función para validar archivo
  const validateFile = useCallback((file: File): { valid: boolean; error?: string } => {
    // Verificar tamaño
    if (file.size > config.maxFileSize * 1024 * 1024) {
      return {
        valid: false,
        error: `El archivo excede el tamaño máximo de ${config.maxFileSize}MB`
      };
    }

    // Verificar formato
    const fileExtension = file.name.split('.').pop()?.toLowerCase();
    if (!fileExtension || !config.supportedFormats.includes(fileExtension)) {
      return {
        valid: false,
        error: `Formato no soportado. Formatos permitidos: ${config.supportedFormats.join(', ')}`
      };
    }

    return { valid: true };
  }, [config.maxFileSize, config.supportedFormats]);

  // Función para subir archivos
  const uploadFiles = useCallback(async (files: FileList | File[]) => {
    const fileArray = Array.from(files);
    const newFiles: CVFile[] = [];

    // Validar y procesar cada archivo
    for (const file of fileArray) {
      const validation = validateFile(file);

      if (!validation.valid) {
        setState(prev => ({ ...prev, error: validation.error! }));
        continue;
      }

      const cvFile: CVFile = {
        id: `cv-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
        file,
        name: file.name,
        size: file.size,
        type: file.type,
        uploadedAt: new Date(),
        status: 'pending',
        progress: 0
      };

      newFiles.push(cvFile);
    }

    // Actualizar estado con nuevos archivos
    setState(prev => ({
      ...prev,
      files: [...prev.files, ...newFiles],
      error: null
    }));

    // Auto-analizar si está habilitado
    if (config.autoAnalyze) {
      for (const cvFile of newFiles) {
        await analyzeCV(cvFile.id);
      }
    }
  }, [config.autoAnalyze, validateFile]);

  // Función para analizar un CV individual
  const analyzeCV = useCallback(async (
    fileId: string,
    options: Partial<CVAnalysisRequest> = {}
  ) => {
    const file = state.files.find(f => f.id === fileId);
    if (!file) return;

    const startTime = Date.now();

    // Actualizar estado del archivo
    setState(prev => ({
      ...prev,
      files: prev.files.map(f =>
        f.id === fileId
          ? { ...f, status: 'processing', progress: 0, error: undefined }
          : f
      ),
      processing: true,
      error: null
    }));

    try {
      // Preparar request para el análisis
      const analysisRequest: CVAnalysisRequest = {
        fileContent: await file.file.text(),
        fileName: file.file.name,
        fileType: file.file.type.includes('pdf') ? 'pdf' : 'txt',
        options: {
          extractSkills: true,
          extractExperience: true,
          extractEducation: true,
          extractContact: true,
          analyzeQuality: config.enhancedAnalysis,
          ...options
        }
      };

      // Simular progreso durante el análisis
      const progressInterval = setInterval(() => {
        setState(prev => ({
          ...prev,
          files: prev.files.map(f =>
            f.id === fileId && f.status === 'processing'
              ? { ...f, progress: Math.min(f.progress + Math.random() * 20, 90) }
              : f
          )
        }));
      }, 500);

      // Realizar análisis
      const result = await cvAnalysisService.analyzeCV(analysisRequest);

      clearInterval(progressInterval);

      // Calcular tiempo de procesamiento
      const processingTime = Date.now() - startTime;
      processingTimesRef.current.push(processingTime);

      // Actualizar estado con resultado
      setState(prev => {
        const newSuccessCount = prev.successCount + 1;
        const newTotalProcessed = prev.totalProcessed + 1;
        const newAverageTime = processingTimesRef.current.reduce((a, b) => a + b, 0) / processingTimesRef.current.length;

        return {
          ...prev,
          files: prev.files.map(f =>
            f.id === fileId
              ? {
                ...f,
                status: 'completed',
                progress: 100,
                result,
                error: undefined
              }
              : f
          ),
          processing: prev.files.filter(f => f.status === 'processing').length <= 1,
          successCount: newSuccessCount,
          totalProcessed: newTotalProcessed,
          averageProcessingTime: newAverageTime
        };
      });

    } catch (error) {
      setState(prev => ({
        ...prev,
        files: prev.files.map(f =>
          f.id === fileId
            ? {
              ...f,
              status: 'error',
              progress: 0,
              error: error instanceof Error ? error.message : 'Error de análisis'
            }
            : f
        ),
        processing: prev.files.filter(f => f.status === 'processing').length <= 1,
        errorCount: prev.errorCount + 1,
        totalProcessed: prev.totalProcessed + 1
      }));
    }
  }, [state.files, config.enhancedAnalysis, cvAnalysisService]);

  // Función para análisis en lote
  const analyzeBatch = useCallback(async (
    fileIds?: string[],
    options: Partial<CVAnalysisRequest> = {}
  ) => {
    const filesToAnalyze = fileIds
      ? state.files.filter(f => fileIds.includes(f.id) && f.status === 'pending')
      : state.files.filter(f => f.status === 'pending');

    if (filesToAnalyze.length === 0) return;

    setState(prev => ({ ...prev, processing: true, batchProgress: 0 }));

    // Procesar archivos secuencialmente o en paralelo según configuración
    if (config.batchProcessing) {
      // Procesamiento en lotes pequeños para evitar sobrecarga
      const batchSize = 3;
      const batches = [];

      for (let i = 0; i < filesToAnalyze.length; i += batchSize) {
        batches.push(filesToAnalyze.slice(i, i + batchSize));
      }

      for (let i = 0; i < batches.length; i++) {
        const batch = batches[i];

        // Procesar lote en paralelo
        await Promise.all(
          batch.map(file => analyzeCV(file.id, options))
        );

        // Actualizar progreso del lote
        const progress = ((i + 1) / batches.length) * 100;
        setState(prev => ({ ...prev, batchProgress: progress }));
      }
    } else {
      // Procesamiento secuencial
      for (let i = 0; i < filesToAnalyze.length; i++) {
        await analyzeCV(filesToAnalyze[i].id, options);

        const progress = ((i + 1) / filesToAnalyze.length) * 100;
        setState(prev => ({ ...prev, batchProgress: progress }));
      }
    }

    setState(prev => ({ ...prev, processing: false, batchProgress: 100 }));
  }, [state.files, config.batchProcessing, analyzeCV]);

  // Función para comparar CVs
  const compareCVs = useCallback(async (
    fileId1: string,
    fileId2: string
  ): Promise<CVComparisonResult> => {
    const file1 = state.files.find(f => f.id === fileId1);
    const file2 = state.files.find(f => f.id === fileId2);

    if (!file1?.result || !file2?.result) {
      throw new Error('Ambos CVs deben estar analizados para poder compararlos');
    }

    // Análisis de similitud
    const skills1 = file1.result.extractedData.skills;
    const skills2 = file2.result.extractedData.skills;
    const commonSkills = skills1.filter(skill => skills2.includes(skill));
    const uniqueSkills1 = skills1.filter(skill => !skills2.includes(skill));
    const uniqueSkills2 = skills2.filter(skill => !skills1.includes(skill));

    const similarityScore = (commonSkills.length * 2) / (skills1.length + skills2.length) * 100;

    // Comparación de experiencia
    const exp1 = file1.result.extractedData.totalExperience;
    const exp2 = file2.result.extractedData.totalExperience;

    return {
      file1,
      file2,
      similarityScore: Math.round(similarityScore),
      commonSkills,
      uniqueSkills1,
      uniqueSkills2,
      experienceComparison: {
        file1Years: exp1,
        file2Years: exp2,
        difference: Math.abs(exp1 - exp2)
      },
      strengthComparison: {
        file1Strengths: file1.result.aiAnalysis.strengths,
        file2Strengths: file2.result.aiAnalysis.strengths,
        commonStrengths: file1.result.aiAnalysis.strengths.filter(s =>
          file2.result!.aiAnalysis.strengths.includes(s)
        )
      },
      recommendation: similarityScore > 70
        ? 'Candidatos muy similares, considerar diferenciadores únicos'
        : 'Candidatos complementarios, evaluar según requisitos específicos'
    };
  }, [state.files]);

  // Función para ranking de CVs
  const rankCVs = useCallback((positionRequirements: CVAnalysisFilters): CVFile[] => {
    return state.files
      .filter(f => f.status === 'completed' && f.result)
      .map(file => {
        let score = 0;
        const data = file.result!.extractedData;

        // Puntuación por habilidades requeridas
        if (positionRequirements.requiredSkills) {
          const matchedRequired = data.skills.filter(skill =>
            positionRequirements.requiredSkills!.includes(skill)
          ).length;
          score += (matchedRequired / positionRequirements.requiredSkills.length) * 40;
        }

        // Puntuación por habilidades preferidas
        if (positionRequirements.preferredSkills) {
          const matchedPreferred = data.skills.filter(skill =>
            positionRequirements.preferredSkills!.includes(skill)
          ).length;
          score += (matchedPreferred / positionRequirements.preferredSkills.length) * 20;
        }

        // Puntuación por experiencia
        if (positionRequirements.minExperience) {
          if (data.totalExperience >= positionRequirements.minExperience) {
            score += 20;
          }
        }

        // Puntuación por educación
        if (positionRequirements.education) {
          const hasRequiredEducation = data.education.some(edu =>
            positionRequirements.education!.includes(edu.degree)
          );
          if (hasRequiredEducation) score += 20;
        }

        return { ...file, calculatedScore: Math.round(score) };
      })
      .sort((a, b) => (b as any).calculatedScore - (a as any).calculatedScore);
  }, [state.files]);

  // Función para búsqueda de CVs
  const searchCVs = useCallback((query: string, filters?: CVAnalysisFilters): CVFile[] => {
    const searchTerms = query.toLowerCase().split(' ');

    return state.files
      .filter(f => f.status === 'completed' && f.result)
      .filter(file => {
        const data = file.result!.extractedData;
        const searchableContent = [
          data.personalInfo.name,
          data.personalInfo.email,
          ...data.skills,
          ...data.education.map(e => e.institution + ' ' + e.degree),
          ...data.workExperience.map(w => w.company + ' ' + w.position),
          data.summary
        ].join(' ').toLowerCase();

        // Verificar si todos los términos de búsqueda están presentes
        const matchesQuery = searchTerms.every(term =>
          searchableContent.includes(term)
        );

        if (!matchesQuery) return false;

        // Aplicar filtros adicionales
        if (filters) {
          if (filters.minExperience && data.totalExperience < filters.minExperience) return false;
          if (filters.maxExperience && data.totalExperience > filters.maxExperience) return false;
          if (filters.requiredSkills && !filters.requiredSkills.every(skill => data.skills.includes(skill))) return false;
          if (filters.education && !data.education.some(edu => filters.education!.includes(edu.degree))) return false;
          if (filters.languages && !filters.languages.every(lang => data.languages.includes(lang))) return false;
        }

        return true;
      });
  }, [state.files]);

  // Función para exportar resultados
  const exportResults = useCallback(async (format: 'json' | 'csv' | 'pdf'): Promise<string | Blob> => {
    const completedFiles = state.files.filter(f => f.status === 'completed' && f.result);

    if (format === 'json') {
      const data = completedFiles.map(file => ({
        fileName: file.name,
        analysisDate: file.result!.metadata.analysisDate,
        score: file.result!.overallScore,
        extractedData: file.result!.extractedData,
        aiAnalysis: file.result!.aiAnalysis
      }));
      return JSON.stringify(data, null, 2);
    }

    if (format === 'csv') {
      const headers = [
        'Archivo', 'Nombre', 'Email', 'Teléfono', 'Experiencia Total',
        'Habilidades', 'Educación', 'Score Global', 'Fecha Análisis'
      ];

      const rows = completedFiles.map(file => {
        const data = file.result!.extractedData;
        return [
          file.name,
          data.personalInfo.name,
          data.personalInfo.email,
          data.personalInfo.phone,
          data.totalExperience,
          data.skills.join('; '),
          data.education.map(e => `${e.degree} - ${e.institution}`).join('; '),
          file.result!.overallScore,
          file.result!.metadata.analysisDate.toLocaleDateString()
        ].map(field => `"${String(field).replace(/"/g, '""')}"`);
      });

      return [headers.join(','), ...rows.map(row => row.join(','))].join('\n');
    }

    // Para PDF, retornar un Blob (implementación simplificada)
    const pdfContent = completedFiles.map(file =>
      `CV: ${file.name}\nScore: ${file.result!.overallScore}\nHabilidades: ${file.result!.extractedData.skills.join(', ')}\n\n`
    ).join('');

    return new Blob([pdfContent], { type: 'application/pdf' });
  }, [state.files]);

  // Funciones de utilidad adicionales
  const removeFile = useCallback((fileId: string) => {
    setState(prev => ({
      ...prev,
      files: prev.files.filter(f => f.id !== fileId)
    }));
  }, []);

  const clearAll = useCallback(() => {
    setState({
      files: [],
      processing: false,
      error: null,
      totalProcessed: 0,
      successCount: 0,
      errorCount: 0,
      averageProcessingTime: 0,
      batchProgress: 0
    });
    progressRef.current = {};
    processingTimesRef.current = [];
  }, []);

  const retryAnalysis = useCallback(async (fileId: string) => {
    setState(prev => ({
      ...prev,
      files: prev.files.map(f =>
        f.id === fileId
          ? { ...f, status: 'pending', progress: 0, error: undefined, result: undefined }
          : f
      )
    }));

    await analyzeCV(fileId);
  }, [analyzeCV]);

  // Estadísticas calculadas
  const stats = useMemo((): CVAnalysisStats => {
    const completedFiles = state.files.filter(f => f.status === 'completed' && f.result);

    if (completedFiles.length === 0) {
      return {
        totalFiles: state.files.length,
        completedAnalysis: 0,
        averageScore: 0,
        topSkills: [],
        experienceDistribution: [],
        educationLevels: [],
        languageDistribution: [],
        locationDistribution: []
      };
    }

    // Recopilar todas las habilidades
    const allSkills: string[] = [];
    const experienceYears: number[] = [];
    const educationLevels: string[] = [];
    const languages: string[] = [];
    const locations: string[] = [];
    let totalScore = 0;

    completedFiles.forEach(file => {
      const data = file.result!.extractedData;
      allSkills.push(...data.skills);
      experienceYears.push(data.totalExperience);
      educationLevels.push(...data.education.map(e => e.degree));
      languages.push(...data.languages);
      if (data.personalInfo.location) {
        locations.push(data.personalInfo.location);
      }
      totalScore += file.result!.overallScore;
    });

    // Calcular frecuencias
    const skillFreq = allSkills.reduce((acc, skill) => {
      acc[skill] = (acc[skill] || 0) + 1;
      return acc;
    }, {} as Record<string, number>);

    const eduFreq = educationLevels.reduce((acc, edu) => {
      acc[edu] = (acc[edu] || 0) + 1;
      return acc;
    }, {} as Record<string, number>);

    const langFreq = languages.reduce((acc, lang) => {
      acc[lang] = (acc[lang] || 0) + 1;
      return acc;
    }, {} as Record<string, number>);

    const locFreq = locations.reduce((acc, loc) => {
      acc[loc] = (acc[loc] || 0) + 1;
      return acc;
    }, {} as Record<string, number>);

    // Distribución de experiencia
    const expDistribution = [
      { range: '0-2 años', count: experienceYears.filter(exp => exp <= 2).length },
      { range: '3-5 años', count: experienceYears.filter(exp => exp >= 3 && exp <= 5).length },
      { range: '6-10 años', count: experienceYears.filter(exp => exp >= 6 && exp <= 10).length },
      { range: '10+ años', count: experienceYears.filter(exp => exp > 10).length }
    ];

    return {
      totalFiles: state.files.length,
      completedAnalysis: completedFiles.length,
      averageScore: Math.round(totalScore / completedFiles.length),
      topSkills: Object.entries(skillFreq)
        .sort(([, a], [, b]) => b - a)
        .slice(0, 10)
        .map(([skill, frequency]) => ({ skill, frequency })),
      experienceDistribution: expDistribution,
      educationLevels: Object.entries(eduFreq)
        .sort(([, a], [, b]) => b - a)
        .map(([level, count]) => ({ level, count })),
      languageDistribution: Object.entries(langFreq)
        .sort(([, a], [, b]) => b - a)
        .slice(0, 5)
        .map(([language, count]) => ({ language, count })),
      locationDistribution: Object.entries(locFreq)
        .sort(([, a], [, b]) => b - a)
        .slice(0, 5)
        .map(([location, count]) => ({ location, count }))
    };
  }, [state.files]);

  // Funciones auxiliares adicionales
  const getFilteredFiles = useCallback((filters: CVAnalysisFilters): CVFile[] => {
    return searchCVs('', filters);
  }, [searchCVs]);

  const getTopCandidates = useCallback((
    count: number,
    criteria: 'score' | 'experience' | 'skills' = 'score'
  ): CVFile[] => {
    const completedFiles = state.files.filter(f => f.status === 'completed' && f.result);

    return completedFiles
      .sort((a, b) => {
        switch (criteria) {
          case 'score':
            return b.result!.overallScore - a.result!.overallScore;
          case 'experience':
            return b.result!.extractedData.totalExperience - a.result!.extractedData.totalExperience;
          case 'skills':
            return b.result!.extractedData.skills.length - a.result!.extractedData.skills.length;
          default:
            return 0;
        }
      })
      .slice(0, count);
  }, [state.files]);

  const generateReport = useCallback(async (fileIds?: string[]) => {
    const filesToReport = fileIds
      ? state.files.filter(f => fileIds.includes(f.id) && f.status === 'completed')
      : state.files.filter(f => f.status === 'completed');

    const summary = `Análisis completado de ${filesToReport.length} CVs con un score promedio de ${stats.averageScore}`;

    const insights = [
      `Habilidad más demandada: ${stats.topSkills[0]?.skill || 'N/A'}`,
      `Experiencia promedio: ${stats.experienceDistribution.find(d => d.count > 0)?.range || 'N/A'}`,
      `Nivel educativo más común: ${stats.educationLevels[0]?.level || 'N/A'}`
    ];

    const recommendations = [
      'Considerar diversificar fuentes de candidatos para mayor variedad de perfiles',
      'Enfocar búsquedas en las habilidades más demandadas identificadas',
      'Implementar procesos de screening basados en los patrones encontrados'
    ];

    return {
      summary,
      insights,
      recommendations,
      charts: [
        { type: 'skills', data: stats.topSkills },
        { type: 'experience', data: stats.experienceDistribution },
        { type: 'education', data: stats.educationLevels }
      ]
    };
  }, [state.files, stats]);

  const getFilePreview = useCallback(async (fileId: string): Promise<string> => {
    const file = state.files.find(f => f.id === fileId);
    if (!file) throw new Error('Archivo no encontrado');

    // Simular generación de preview
    return `Preview del archivo: ${file.name}`;
  }, [state.files]);

  const downloadOriginal = useCallback((fileId: string) => {
    const file = state.files.find(f => f.id === fileId);
    if (!file) return;

    const url = URL.createObjectURL(file.file);
    const a = document.createElement('a');
    a.href = url;
    a.download = file.name;
    a.click();
    URL.revokeObjectURL(url);
  }, [state.files]);

  const updateConfig = useCallback((newConfig: Partial<UseCVAnalysisProps>) => {
    setConfig(prev => ({ ...prev, ...newConfig }));
  }, []);

  return {
    // Estado
    files: state.files,
    processing: state.processing,
    error: state.error,
    stats,
    batchProgress: state.batchProgress,

    // Acciones principales
    uploadFiles,
    analyzeCV,
    analyzeBatch,
    removeFile,
    clearAll,
    retryAnalysis,

    // Funcionalidades avanzadas
    compareCVs,
    rankCVs,
    searchCVs,
    exportResults,

    // Utilidades
    getFilteredFiles,
    getTopCandidates,
    generateReport,

    // Validación y helpers
    validateFile,
    getFilePreview,
    downloadOriginal,

    // Configuración
    config,
    updateConfig
  };
};

export default useCVAnalysis;

// Tipos exportados
export type {
  UseCVAnalysisProps,
  CVFile,
  CVAnalysisFilters,
  CVComparisonResult,
  CVAnalysisStats,
  UseCVAnalysisReturn
};

/**
 * Intelligent Preloader for Critical Routes
 * Precarga componentes en el momento óptimo para mejorar UX
 */

import { useEffect } from 'react';

export const useIntelligentPreloader = () => {
  useEffect(() => {
    // Preload después del initial render para no afectar FCP
    const timeoutId = setTimeout(() => {
      // Precargar componentes críticos después de 2 segundos
      preloadCriticalComponents();
    }, 2000);

    return () => clearTimeout(timeoutId);
  }, []);

  const preloadCriticalComponents = async () => {
    try {
      // Precargar en orden de prioridad
      const preloadPromises = [
        // Dashboard components (alta probabilidad de uso)
        import('../pages/dashboard/CDDashboard'),
        import('../pages/jobs/Index'),

        // Precargar UploadCV solo si el user está logueado
        localStorage.getItem('auth_token') ?
          import('../components/UploadCVOptimized') :
          Promise.resolve(),

        // Precargar Estadísticas solo para usuarios HR/Admin
        shouldPreloadStats() ?
          import('../pages/dashboard/EstadisticasOptimized') :
          Promise.resolve(),
      ];

      await Promise.allSettled(preloadPromises);
      console.log('🚀 Critical components preloaded');
    } catch (error) {
      console.warn('⚠️ Preload failed:', error);
    }
  };

  const shouldPreloadStats = (): boolean => {
    const userRole = localStorage.getItem('user_role');
    return userRole === 'hr' || userRole === 'admin' || userRole === 'recruiter';
  };
};

// Hook para precargar cuando el usuario hace hover sobre enlaces
export const useHoverPreload = () => {
  const preloadOnHover = (importFn: () => Promise<any>) => {
    return {
      onMouseEnter: () => {
        // Precargar cuando el usuario hace hover
        importFn().catch(console.warn);
      }
    };
  };

  return { preloadOnHover };
};

export default useIntelligentPreloader;

import { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { IntelligentMatching } from '../services/ai/IntelligentMatching';

// Interfaces para el hook
interface UseIntelligentSearchProps {
  searchType: 'candidates' | 'positions' | 'companies';
  autoSearch?: boolean;
  debounceDelay?: number;
  maxResults?: number;
  enableSemanticSearch?: boolean;
  enableFacetedSearch?: boolean;
  cacheResults?: boolean;
}

interface SearchFilters {
  // Filtros generales
  query?: string;
  location?: string;
  remote?: boolean;
  dateRange?: {
    start: Date;
    end: Date;
  };

  // Filtros para candidatos
  skills?: string[];
  experience?: {
    min: number;
    max: number;
  };
  education?: string[];
  certifications?: string[];
  languages?: string[];
  availability?: 'immediate' | 'twoWeeks' | 'month' | 'negotiable';
  salaryExpectation?: {
    min: number;
    max: number;
    currency: string;
  };

  // Filtros para posiciones
  department?: string[];
  level?: ('entry' | 'mid' | 'senior' | 'lead' | 'executive')[];
  employmentType?: ('fullTime' | 'partTime' | 'contract' | 'internship')[];
  industry?: string[];
  companySize?: ('startup' | 'small' | 'medium' | 'large' | 'enterprise')[];
  benefits?: string[];

  // Filtros avanzados de IA
  culturalFit?: number;
  riskTolerance?: 'low' | 'medium' | 'high';
  innovationLevel?: number;
  teamworkScore?: number;
  leadershipPotential?: number;
}

interface SearchResult {
  id: string;
  type: 'candidate' | 'position' | 'company';
  title: string;
  subtitle?: string;
  description: string;
  score: number;
  relevanceScore: number;
  culturalFitScore?: number;
  metadata: Record<string, any>;
  highlights: string[];
  avatar?: string;
  tags: string[];
  lastUpdated: Date;
  aiInsights?: {
    matchReason: string;
    strengthAreas: string[];
    concerns: string[];
    recommendations: string[];
  };
}

interface SearchFacet {
  field: string;
  label: string;
  values: Array<{
    value: string;
    label: string;
    count: number;
    selected: boolean;
  }>;
}

interface SearchSuggestion {
  text: string;
  type: 'query' | 'skill' | 'location' | 'company';
  count?: number;
}

interface SearchState {
  results: SearchResult[];
  facets: SearchFacet[];
  suggestions: SearchSuggestion[];
  loading: boolean;
  error: string | null;
  totalCount: number;
  hasMore: boolean;
  currentPage: number;
  searchTime: number;
  lastQuery: string;
}

interface UseIntelligentSearchReturn {
  // Estado
  results: SearchResult[];
  facets: SearchFacet[];
  suggestions: SearchSuggestion[];
  loading: boolean;
  error: string | null;
  totalCount: number;
  hasMore: boolean;
  currentPage: number;
  searchTime: number;
  lastQuery: string;

  // Acciones
  search: (query: string, filters?: SearchFilters) => Promise<void>;
  loadMore: () => Promise<void>;
  applyFilters: (filters: SearchFilters) => Promise<void>;
  clearFilters: () => void;
  clearSearch: () => void;
  retrySearch: () => Promise<void>;

  // Utilidades
  exportResults: (format: 'json' | 'csv') => string;
  saveSearch: (name: string) => void;
  getSavedSearches: () => Array<{ name: string; query: string; filters: SearchFilters; date: Date }>;
  deleteSavedSearch: (name: string) => void;

  // Estado de filtros
  activeFilters: SearchFilters;
  hasActiveFilters: boolean;

  // Funcionalidades avanzadas
  semanticSearchEnabled: boolean;
  toggleSemanticSearch: () => void;
  getSearchInsights: () => {
    topSkills: string[];
    commonLocations: string[];
    averageScore: number;
    searchTrends: Array<{ term: string; frequency: number }>;
  };
}

const useIntelligentSearch = ({
  searchType,
  autoSearch = false,
  debounceDelay = 300,
  maxResults = 50,
  enableSemanticSearch = true,
  enableFacetedSearch = true,
  cacheResults = true
}: UseIntelligentSearchProps): UseIntelligentSearchReturn => {

  // Estado principal
  const [state, setState] = useState<SearchState>({
    results: [],
    facets: [],
    suggestions: [],
    loading: false,
    error: null,
    totalCount: 0,
    hasMore: true,
    currentPage: 1,
    searchTime: 0,
    lastQuery: ''
  });

  // Filtros activos
  const [filters, setFilters] = useState<SearchFilters>({});

  // Configuración de búsqueda semántica
  const [semanticSearchEnabled, setSemanticSearchEnabled] = useState(enableSemanticSearch);

  // Cache de resultados
  const cacheRef = useRef<Map<string, SearchResult[]>>(new Map());

  // Referencia para debounce
  const debounceRef = useRef<NodeJS.Timeout>();

  // Instancia del servicio de matching inteligente
  const intelligentMatching = useMemo(() => new IntelligentMatching(), []);

  // Función principal de búsqueda
  const performSearch = useCallback(async (
    query: string,
    searchFilters: SearchFilters = {},
    append: boolean = false
  ) => {
    const startTime = Date.now();

    setState(prev => ({
      ...prev,
      loading: true,
      error: null,
      lastQuery: query
    }));

    try {
      // Verificar cache si está habilitado
      const cacheKey = `${query}-${JSON.stringify(searchFilters)}-${state.currentPage}`;
      if (cacheResults && cacheRef.current.has(cacheKey) && !append) {
        const cachedResults = cacheRef.current.get(cacheKey)!;
        setState(prev => ({
          ...prev,
          results: cachedResults,
          loading: false,
          searchTime: Date.now() - startTime
        }));
        return;
      }

      // Preparar parámetros de búsqueda
      const searchParams = {
        query,
        type: searchType,
        filters: { ...filters, ...searchFilters },
        semanticSearch: semanticSearchEnabled,
        facetedSearch: enableFacetedSearch,
        page: append ? state.currentPage + 1 : 1,
        limit: maxResults
      };

      // Simular búsqueda inteligente (aquí iría la integración real con la API)
      const mockResults = await simulateIntelligentSearch(searchParams);

      // Procesar resultados con IA
      const processedResults = await Promise.all(
        mockResults.results.map(async (result) => {
          if (searchType === 'candidates' && result.type === 'candidate') {
            // Análisis de matching inteligente para candidatos
            const matchingResults = await intelligentMatching.performMatching({
              candidateId: result.id,
              jobId: 'mock-job-id', // En producción vendría de los parámetros de búsqueda
              filters: {
                skillsWeight: 0.3,
                experienceWeight: 0.3,
                cultureWeight: 0.2,
                locationWeight: 0.1,
                salaryWeight: 0.1
              }
            });

            const matchingResult = matchingResults[0];

            return {
              ...result,
              culturalFitScore: matchingResult?.culturalFit?.overallFit || 0,
              aiInsights: {
                matchReason: matchingResult?.recommendations?.join(', ') || '',
                strengthAreas: matchingResult?.breakdown?.skillsMatch?.details || [],
                concerns: matchingResult?.riskFactors?.map(rf => rf.description) || [],
                recommendations: matchingResult?.recommendations || []
              }
            };
          }
          return result;
        })
      );

      // Actualizar estado
      setState(prev => ({
        ...prev,
        results: append ? [...prev.results, ...processedResults] : processedResults,
        facets: mockResults.facets,
        suggestions: mockResults.suggestions,
        loading: false,
        totalCount: mockResults.totalCount,
        hasMore: mockResults.hasMore,
        currentPage: append ? prev.currentPage + 1 : 1,
        searchTime: Date.now() - startTime
      }));

      // Guardar en cache
      if (cacheResults) {
        cacheRef.current.set(cacheKey, processedResults);
      }

    } catch (error) {
      setState(prev => ({
        ...prev,
        loading: false,
        error: error instanceof Error ? error.message : 'Error en la búsqueda',
        searchTime: Date.now() - startTime
      }));
    }
  }, [searchType, filters, semanticSearchEnabled, enableFacetedSearch, maxResults, cacheResults, state.currentPage, intelligentMatching]);

  // Función de búsqueda con debounce
  const search = useCallback((query: string, searchFilters?: SearchFilters) => {
    // Limpiar debounce anterior
    if (debounceRef.current) {
      clearTimeout(debounceRef.current);
    }

    return new Promise<void>((resolve) => {
      debounceRef.current = setTimeout(async () => {
        await performSearch(query, searchFilters);
        resolve();
      }, debounceDelay);
    });
  }, [performSearch, debounceDelay]);

  // Cargar más resultados
  const loadMore = useCallback(async () => {
    if (state.hasMore && !state.loading && state.lastQuery) {
      await performSearch(state.lastQuery, filters, true);
    }
  }, [state.hasMore, state.loading, state.lastQuery, filters, performSearch]);

  // Aplicar filtros
  const applyFilters = useCallback(async (newFilters: SearchFilters) => {
    setFilters(prev => ({ ...prev, ...newFilters }));
    if (state.lastQuery) {
      setState(prev => ({ ...prev, currentPage: 1 }));
      await performSearch(state.lastQuery, newFilters);
    }
  }, [state.lastQuery, performSearch]);

  // Limpiar filtros
  const clearFilters = useCallback(() => {
    setFilters({});
    if (state.lastQuery) {
      setState(prev => ({ ...prev, currentPage: 1 }));
      performSearch(state.lastQuery, {});
    }
  }, [state.lastQuery, performSearch]);

  // Limpiar búsqueda
  const clearSearch = useCallback(() => {
    setState({
      results: [],
      facets: [],
      suggestions: [],
      loading: false,
      error: null,
      totalCount: 0,
      hasMore: true,
      currentPage: 1,
      searchTime: 0,
      lastQuery: ''
    });
    setFilters({});
    cacheRef.current.clear();
  }, []);

  // Reintentar búsqueda
  const retrySearch = useCallback(async () => {
    if (state.lastQuery) {
      await performSearch(state.lastQuery, filters);
    }
  }, [state.lastQuery, filters, performSearch]);

  // Alternar búsqueda semántica
  const toggleSemanticSearch = useCallback(() => {
    setSemanticSearchEnabled(prev => !prev);
  }, []);

  // Exportar resultados
  const exportResults = useCallback((format: 'json' | 'csv') => {
    const data = state.results.map(result => ({
      id: result.id,
      type: result.type,
      title: result.title,
      subtitle: result.subtitle || '',
      score: result.score,
      relevanceScore: result.relevanceScore,
      culturalFitScore: result.culturalFitScore || 0,
      tags: result.tags.join('; '),
      lastUpdated: result.lastUpdated.toISOString(),
      highlights: result.highlights.join('; ')
    }));

    if (format === 'json') {
      return JSON.stringify(data, null, 2);
    } else {
      const headers = Object.keys(data[0] || {});
      const csvContent = [
        headers.join(','),
        ...data.map(row => headers.map(header =>
          `"${String(row[header as keyof typeof row]).replace(/"/g, '""')}"`
        ).join(','))
      ].join('\n');
      return csvContent;
    }
  }, [state.results]);

  // Guardar búsqueda
  const saveSearch = useCallback((name: string) => {
    const savedSearches = JSON.parse(localStorage.getItem('intelligent-searches') || '[]');
    const newSearch = {
      name,
      query: state.lastQuery,
      filters,
      date: new Date()
    };

    const updatedSearches = [...savedSearches.filter((s: any) => s.name !== name), newSearch];
    localStorage.setItem('intelligent-searches', JSON.stringify(updatedSearches));
  }, [state.lastQuery, filters]);

  // Obtener búsquedas guardadas
  const getSavedSearches = useCallback(() => {
    return JSON.parse(localStorage.getItem('intelligent-searches') || '[]');
  }, []);

  // Eliminar búsqueda guardada
  const deleteSavedSearch = useCallback((name: string) => {
    const savedSearches = JSON.parse(localStorage.getItem('intelligent-searches') || '[]');
    const updatedSearches = savedSearches.filter((s: any) => s.name !== name);
    localStorage.setItem('intelligent-searches', JSON.stringify(updatedSearches));
  }, []);

  // Obtener insights de búsqueda
  const getSearchInsights = useCallback(() => {
    const allTags = state.results.flatMap(r => r.tags);
    const skillCounts = allTags.reduce((acc, tag) => {
      acc[tag] = (acc[tag] || 0) + 1;
      return acc;
    }, {} as Record<string, number>);

    const locations = state.results
      .map(r => r.metadata.location)
      .filter(Boolean)
      .reduce((acc, loc) => {
        acc[loc] = (acc[loc] || 0) + 1;
        return acc;
      }, {} as Record<string, number>);

    return {
      topSkills: Object.entries(skillCounts)
        .sort(([, a], [, b]) => (b as number) - (a as number))
        .slice(0, 10)
        .map(([skill]) => skill),
      commonLocations: Object.entries(locations)
        .sort(([, a], [, b]) => (b as number) - (a as number))
        .slice(0, 5)
        .map(([location]) => location),
      averageScore: state.results.length > 0
        ? state.results.reduce((sum, r) => sum + r.score, 0) / state.results.length
        : 0,
      searchTrends: Object.entries(skillCounts)
        .sort(([, a], [, b]) => (b as number) - (a as number))
        .slice(0, 5)
        .map(([term, frequency]) => ({ term, frequency }))
    };
  }, [state.results]);

  // Verificar si hay filtros activos
  const hasActiveFilters = useMemo(() => {
    return Object.keys(filters).length > 0;
  }, [filters]);

  // Limpiar debounce al desmontar
  useEffect(() => {
    return () => {
      if (debounceRef.current) {
        clearTimeout(debounceRef.current);
      }
    };
  }, []);

  return {
    // Estado
    results: state.results,
    facets: state.facets,
    suggestions: state.suggestions,
    loading: state.loading,
    error: state.error,
    totalCount: state.totalCount,
    hasMore: state.hasMore,
    currentPage: state.currentPage,
    searchTime: state.searchTime,
    lastQuery: state.lastQuery,

    // Acciones
    search,
    loadMore,
    applyFilters,
    clearFilters,
    clearSearch,
    retrySearch,

    // Utilidades
    exportResults,
    saveSearch,
    getSavedSearches,
    deleteSavedSearch,

    // Estado de filtros
    activeFilters: filters,
    hasActiveFilters,

    // Funcionalidades avanzadas
    semanticSearchEnabled,
    toggleSemanticSearch,
    getSearchInsights
  };
};

// Función de simulación de búsqueda (reemplazar con API real)
const simulateIntelligentSearch = async (params: any) => {
  // Simular delay de API
  await new Promise(resolve => setTimeout(resolve, 800));

  // Generar resultados mock basados en el tipo de búsqueda
  const mockResults: SearchResult[] = [];
