/**
 * Hook para manejar operaciones offline en la aplicación
 * Proporciona funciones para cachear datos, manejar solicitudes offline
 * y sincronizar datos cuando se recupera la conexión.
 */

import { useState, useEffect } from 'react';
import { useOnlineStatus } from './useOnlineStatus';
import { offlineDataManager } from '../services/OfflineDataManager';

interface UseOfflineOperationsOptions {
  automaticSync?: boolean;
  syncInterval?: number;
}

export function useOfflineOperations(options: UseOfflineOperationsOptions = {}) {
  const { automaticSync = true, syncInterval = 60000 } = options;
  const { isOnline } = useOnlineStatus();
  const [isSyncing, setIsSyncing] = useState(false);
  const [lastSyncTime, setLastSyncTime] = useState<Date | null>(null);
  const [pendingOperations, setPendingOperations] = useState<number>(0);

  // Función para cargar datos con soporte offline
  const fetchWithOfflineSupport = async <T>(
    url: string,
    options?: RequestInit & { cacheTTL?: number }
  ): Promise<T> => {
    const cacheTTL = options?.cacheTTL || 60; // Default 60 minutes

    try {
      // Si estamos online, intentar obtener datos frescos
      if (isOnline) {
        const response = await fetch(url, options);
        if (!response.ok) {
          throw new Error(`Error fetching data: ${response.status}`);
        }

        const data = await response.json();

        // Guardar en caché para uso offline
        await offlineDataManager.cacheApiResponse(url, data, cacheTTL);

        return data;
      } else {
        // Si estamos offline, intentar obtener datos de la caché
        const cachedData = await offlineDataManager.getCachedApiResponse(url);
        if (cachedData) {
          return cachedData;
        }

        throw new Error('No hay conexión y no se encontraron datos en caché');
      }
    } catch (error) {
      // Si hay un error al obtener datos frescos, intentar usar caché
      const cachedData = await offlineDataManager.getCachedApiResponse(url);
      if (cachedData) {
        return cachedData;
      }

      throw error;
    }
  };

  // Función para enviar datos con soporte offline
  const sendWithOfflineSupport = async <T>(
    url: string,
    method: string,
    data: any,
    options?: RequestInit
  ): Promise<T | null> => {
    const requestOptions: RequestInit = {
      method,
      headers: {
        'Content-Type': 'application/json',
        ...(options?.headers || {})
      },
      body: JSON.stringify(data),
      ...options
    };

    try {
      // Si estamos online, enviar inmediatamente
      if (isOnline) {
        const response = await fetch(url, requestOptions);

        if (!response.ok) {
          throw new Error(`Error sending data: ${response.status}`);
        }

        return await response.json();
      } else {
        // Si estamos offline, guardar para enviar más tarde
        await offlineDataManager.addPendingRequest({
          url,
          method,
          body: data,
          headers: requestOptions.headers as Record<string, string>
        });

        // Actualizar contador de operaciones pendientes
        setPendingOperations(prev => prev + 1);

        return null;
      }
    } catch (error) {
      // Si hay un error al enviar, guardar para intentar más tarde
      await offlineDataManager.addPendingRequest({
        url,
        method,
        body: data,
        headers: requestOptions.headers as Record<string, string>
      });

      // Actualizar contador de operaciones pendientes
      setPendingOperations(prev => prev + 1);

      throw error;
    }
  };

  // Función para guardar borrador de formulario
  const saveFormDraft = async (formId: string, formData: any): Promise<void> => {
    await offlineDataManager.saveFormDraft(formId, formData);
  };

  // Función para recuperar borrador de formulario
  const getFormDraft = async (formId: string): Promise<any> => {
    return await offlineDataManager.getFormDraft(formId);
  };

  // Función para eliminar borrador de formulario
  const deleteFormDraft = async (formId: string): Promise<void> => {
    await offlineDataManager.deleteFormDraft(formId);
  };

  // Función para sincronizar datos pendientes
  const syncPendingOperations = async (): Promise<void> => {
    if (!isOnline || isSyncing) {
      return;
    }

    setIsSyncing(true);

    try {
      // Obtener todas las operaciones pendientes
      const pendingRequests = await offlineDataManager.getPendingRequests();
      let successCount = 0;

      // Intentar enviar cada operación pendiente
      for (const request of pendingRequests) {
        try {
          const response = await fetch(request.url, {
            method: request.method,
            headers: request.headers || { 'Content-Type': 'application/json' },
            body: request.body ? JSON.stringify(request.body) : null
          });

          if (response.ok) {
            // Si la operación se completó con éxito, eliminarla de pendientes
            await offlineDataManager.removePendingRequest(request.id);
            successCount++;
          }
        } catch (error) {
          console.error(`Error al sincronizar operación pendiente:`, error);
        }
      }

      // Actualizar contador de operaciones pendientes
      const remaining = pendingRequests.length - successCount;
      setPendingOperations(remaining);

      // Actualizar último tiempo de sincronización
      setLastSyncTime(new Date());

    } catch (error) {
      console.error('Error en sincronización de datos:', error);
    } finally {
      setIsSyncing(false);
    }
  };

  // Sincronización automática cuando se recupera la conexión
  useEffect(() => {
    if (isOnline && automaticSync && pendingOperations > 0) {
      syncPendingOperations();
    }
  }, [isOnline, automaticSync, pendingOperations]);

  // Sincronización periódica si está habilitada
  useEffect(() => {
    if (!automaticSync || syncInterval <= 0) {
      return undefined;
    }

    const intervalId = setInterval(() => {
      if (isOnline && pendingOperations > 0) {
        syncPendingOperations();
      }
    }, syncInterval);

    return () => clearInterval(intervalId);
  }, [automaticSync, syncInterval, isOnline, pendingOperations]);

  // Limpiar caché expirada periódicamente
  useEffect(() => {
    const cleanupInterval = setInterval(() => {
      offlineDataManager.cleanExpiredCache();
    }, 30 * 60 * 1000); // Cada 30 minutos

    return () => clearInterval(cleanupInterval);
  }, []);

  return {
    fetchWithOfflineSupport,
    sendWithOfflineSupport,
    saveFormDraft,
    getFormDraft,
    deleteFormDraft,
    syncPendingOperations,
    isSyncing,
    pendingOperations,
    lastSyncTime
  };
}

import { useEffect, useState, useRef, useCallback } from 'react';
import { usePerformance } from '../contexts/PerformanceContext';

interface UseOptimizedDataOptions<T> {
  fetchFunction: () => Promise<T>;
  dependencies?: any[];
  cacheKey?: string;
  cacheDuration?: number; // en milisegundos
  fallbackData?: T;
  retry?: boolean;
  retryCount?: number;
  retryDelay?: number; // en milisegundos
  timeout?: number; // en milisegundos
}

/**
 * Hook para optimizar la carga de datos con estrategias avanzadas
 * 
 * Características:
 * - Caché local para reducir peticiones
 * - Timeout configurable
 * - Reintentos automáticos
 * - Adaptación a dispositivos/redes lentas
 * - Gestión de estados de carga
 */
export function useOptimizedData<T>({
  fetchFunction,
  dependencies = [],
  cacheKey,
  cacheDuration = 5 * 60 * 1000, // 5 minutos por defecto
  fallbackData,
  retry = true,
  retryCount = 3,
  retryDelay = 1000,
  timeout = 15000
}: UseOptimizedDataOptions<T>) {
  const [data, setData] = useState<T | undefined>(fallbackData);
  const [error, setError] = useState<Error | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const { isLowEndNetwork } = usePerformance();

  // Control de retries
  const retriesRef = useRef(0);
  const abortControllerRef = useRef<AbortController | null>(null);

  // Adaptación a dispositivos/redes lentas
  const adaptedTimeout = isLowEndNetwork ? timeout * 2 : timeout;
  const adaptedRetryDelay = isLowEndNetwork ? retryDelay * 2 : retryDelay;
  const adaptedRetryCount = isLowEndNetwork ? Math.min(2, retryCount) : retryCount;

  // Función para verificar caché
  const checkCache = useCallback(() => {
    if (!cacheKey) return null;

    try {
      const cachedItem = localStorage.getItem(`data_cache_${cacheKey}`);
      if (!cachedItem) return null;

      const { value, timestamp } = JSON.parse(cachedItem);
      const now = Date.now();

      if (now - timestamp < cacheDuration) {
        return value;
      }

      // Caché expirado
      localStorage.removeItem(`data_cache_${cacheKey}`);
      return null;
    } catch (e) {
      console.warn('Error al leer la caché:', e);
      return null;
    }
  }, [cacheKey, cacheDuration]);

  // Función para actualizar caché
  const updateCache = useCallback((newData: T) => {
    if (!cacheKey) return;

    try {
      const cacheItem = {
        value: newData,
        timestamp: Date.now()
      };

      localStorage.setItem(`data_cache_${cacheKey}`, JSON.stringify(cacheItem));
    } catch (e) {
      console.warn('Error al guardar en caché:', e);
    }
  }, [cacheKey]);

  // Función para cargar datos con timeout y retry
  const loadData = useCallback(async () => {
    // Comprobar caché primero
    const cachedData = checkCache();
    if (cachedData) {
      setData(cachedData);
      setLoading(false);
      return;
    }

    // Resetear estado
    setLoading(true);
    setError(null);

    // Cancelar petición anterior si existe
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }

    // Crear nuevo AbortController
    abortControllerRef.current = new AbortController();
    // const signal = abortControllerRef.current.signal; // Eliminado porque no se usa

    // Timeout
    const timeoutId = setTimeout(() => {
      if (abortControllerRef.current) {
        abortControllerRef.current.abort();
      }
    }, adaptedTimeout);

    try {
      // Envolver fetchFunction con AbortController si es posible
      const wrappedFetchFunction = async () => {
        try {
          // Asumimos que fetchFunction puede aceptar un signal
          // Esta es una simplificación, en la práctica necesitarías adaptar tu fetchFunction
          return await fetchFunction();
        } catch (error) {
          if ((error as any)?.name === 'AbortError') {
            throw new Error('La petición ha excedido el tiempo de espera');
          }
          throw error;
        }
      };

      const result = await wrappedFetchFunction();

      clearTimeout(timeoutId);

      // Actualizar estado y caché
      setData(result);
      setLoading(false);
      retriesRef.current = 0;

      // Actualizar caché
      updateCache(result);
    } catch (e) {
      clearTimeout(timeoutId);

      const error = e as Error;
      console.error('Error al cargar datos:', error);

      // Lógica de retry
      if (retry && retriesRef.current < adaptedRetryCount) {
        retriesRef.current += 1;

        setTimeout(() => {
          loadData();
        }, adaptedRetryDelay * retriesRef.current); // Backoff exponencial
      } else {
        setError(error);
        setLoading(false);
        retriesRef.current = 0;
      }
    }
  }, [fetchFunction, checkCache, updateCache, retry, adaptedRetryCount, adaptedRetryDelay, adaptedTimeout]);

  useEffect(() => {
    loadData();

    return () => {
      if (abortControllerRef.current) {
        abortControllerRef.current.abort();
      }
    };
  }, [...dependencies, loadData]);

  // Función para recargar datos manualmente
  const refresh = () => {
    retriesRef.current = 0;
    loadData();
  };

  return {
    data,
    loading,
    error,
    refresh
  };
}

export default useOptimizedData;

