import React, { createContext, useState, useContext, useEffect, ReactNode } from 'react';
import { en, es } from './translations';
import { languageService } from './languageService';

type Language = 'en' | 'es';
type Translations = typeof en | typeof es;

interface LanguageContextType {
  language: Language;
  setLanguage: (lang: Language) => void;
  t: (key: string) => string;
}

const defaultLanguage: Language = 'es';

// Create the context
const LanguageContext = createContext<LanguageContextType | undefined>(undefined);

// Create a provider component
export const LanguageProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  // Try to get the language from localStorage, or use default
  const [language, setLanguageState] = useState<Language>(() => {
    const savedLanguage = localStorage.getItem('language') as Language;
    return savedLanguage ? savedLanguage : defaultLanguage;
  });

  // Efecto para cargar el idioma del backend al iniciar la aplicación
  useEffect(() => {
    const fetchLanguage = async () => {
      try {
        const backendLanguage = await languageService.getLanguage();
        if (backendLanguage !== language) {
          setLanguageState(backendLanguage);
          localStorage.setItem('language', backendLanguage);
        }
      } catch (error) {
        console.error('Error al obtener el idioma del backend:', error);
      }
    };

    fetchLanguage();
  }, []);

  // Save language to localStorage when it changes
  useEffect(() => {
    localStorage.setItem('language', language);
  }, [language]);

  // Function to change the language
  const setLanguage = async (lang: Language) => {
    setLanguageState(lang);

    // Sincronizar con el backend
    try {
      await languageService.setLanguage(lang);
    } catch (error) {
      console.error('Error al sincronizar el idioma con el backend:', error);
    }
  };

  // Function to get translations
  const t = (key: string): string => {
    const translations: Translations = language === 'en' ? en : es;

    // Split the key by dots to access nested properties
    const keys = key.split('.');
    let value: any = translations;

    // Navigate through the object
    for (const k of keys) {
      if (value && typeof value === 'object' && k in value) {
        value = value[k];
      } else {
        console.warn(`Translation key not found: ${key}`);
        return key; // Return the key itself if translation not found
      }
    }

    return value;
  };

  return (
    <LanguageContext.Provider value={{ language, setLanguage, t }}>
      {children}
    </LanguageContext.Provider>
  );
};

// Hook to use the language context
export const useLanguage = (): LanguageContextType => {
  const context = useContext(LanguageContext);
  if (context === undefined) {
    throw new Error('useLanguage must be used within a LanguageProvider');
  }
  return context;
};

/**
 * PDF Processing Worker
 * Mueve el procesamiento de PDF a un web worker para evitar bloqueo del UI
 */

import { getDocument, GlobalWorkerOptions, PDFDocumentProxy } from 'pdfjs-dist';

// Configurar worker en runtime
GlobalWorkerOptions.workerSrc = `//cdnjs.cloudflare.com/ajax/libs/pdf.js/3.4.120/pdf.worker.min.js`;

export interface PDFProcessingResult {
  text: string;
  pages: number;
  metadata?: Record<string, unknown>;
}

export class PDFProcessor {
  private static instance: PDFProcessor;

  public static getInstance(): PDFProcessor {
    if (!PDFProcessor.instance) {
      PDFProcessor.instance = new PDFProcessor();
    }
    return PDFProcessor.instance;
  }

  async processPDF(file: File): Promise<PDFProcessingResult> {
    return new Promise((resolve, reject) => {
      const fileReader = new FileReader();

      fileReader.onload = async () => {
        try {
          const typedArray = new Uint8Array(fileReader.result as ArrayBuffer);
          const pdf = await getDocument(typedArray).promise;

          let fullText = '';
          const totalPages = pdf.numPages;

          // Procesar páginas en batches para mejor performance
          const batchSize = 3;
          for (let i = 1; i <= totalPages; i += batchSize) {
            const batchPromises = [];

            for (let j = i; j < Math.min(i + batchSize, totalPages + 1); j++) {
              batchPromises.push(this.extractPageText(pdf, j));
            }

            const batchResults = await Promise.all(batchPromises);
            fullText += batchResults.join(' ');
          }

          resolve({
            text: fullText.trim(),
            pages: totalPages,
            metadata: await pdf.getMetadata()
          });
        } catch (error) {
          reject(error);
        }
      };

      fileReader.onerror = () => reject(new Error('Error reading file'));
      fileReader.readAsArrayBuffer(file);
    });
  }

  private async extractPageText(pdf: PDFDocumentProxy, pageNumber: number): Promise<string> {
    const page = await pdf.getPage(pageNumber);
    const textContent = await page.getTextContent();
    // Solo extraer los items que tienen 'str' (TextItem)
    return textContent.items
      .map((item: any) => (typeof item.str === 'string' ? item.str : ''))
      .filter((str: string) => str.length > 0)
      .join(' ');
  }
}

