  const navigate = useNavigate();
  const jobId = searchParams.get('job');
  const [isLogin, setIsLogin] = useState(true); // Empezamos mostrando LOGIN
  const [isLoading, setIsLoading] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isRegistering, setIsRegistering] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [success, setSuccess] = useState(false);
  const { errors, setError, clearError, clearAllErrors, hasError } = useFormErrors();
  const { candidateLogin, refreshSession } = useAuth();

  // Estados para modales y flujos
  const [showValidationModal, setShowValidationModal] = useState(false);
  const [showManualForm, setShowManualForm] = useState(false);
  const [cvProcessingFailed, setCvProcessingFailed] = useState(false);

  // Estados para consentimiento GDPR
  const [gdprConsent, setGdprConsent] = useState(false);
  const [dataProcessingConsent, setDataProcessingConsent] = useState(false);

  // Estados para los formularios
  const [loginForm, setLoginForm] = useState({
    email: '',
    password: ''
  });

  const [registerForm, setRegisterForm] = useState({
    email: '',
    username: '',
    password: '',
    confirmPassword: '',
    cv: null as File | null,
    cvData: null as any, // Datos extraídos por OpenAI
    cvJsonFile: null as string | null, // Ruta del archivo JSON generado
    cvTextFile: null as string | null, // Ruta del archivo TXT generado
  });

  // Mostrar información del job si viene desde JobDetails
  useEffect(() => {
    if (jobId) {
      toast({
        title: 'Aplicando para un trabajo específico',
        description: `Te estás autenticando para aplicar al trabajo ID: ${jobId}`,
        variant: 'default'
      });
    }
  }, [jobId]);

  const handleLoginSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    clearAllErrors();

    if (!loginForm.email.trim()) {
      setError('email', 'El correo electrónico es obligatorio');
      return;
    }
    if (!loginForm.password.trim()) {
      setError('password', 'La contraseña es obligatoria');
      return;
    }

    setIsLoading(true);
    try {
      const success = await candidateLogin(loginForm.email, loginForm.password);
      if (success) {
        // Redirigir según el rol o al job específico usando React Router
        if (jobId) {
          navigate(`/jobs/apply?job=${jobId}`);
        } else {
          navigate('/dashboard/cddashboard');
        }
      } else {
        setError('general', 'Credenciales incorrectas. Verifica tu correo y contraseña.');
      }
    } catch (error) {
      setError('general', 'Error de conexión. Inténtalo nuevamente.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleRegisterChange = (field: string, value: string) => {
    setRegisterForm(prev => ({ ...prev, [field]: value }));
    if (hasError(field)) {
      clearError(field);
    }
  };

  const handleFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];

      // Solo PDF (alineado backend /api/cv/parse)
      if (file.type !== 'application/pdf') {
        setError('cv', 'Solo se permiten archivos PDF');
        return;
      }

      if (file.size > 5 * 1024 * 1024) { // 5MB limit (alineado backend)
        setError('cv', 'El archivo no puede superar los 5MB');
        return;
      }

      setRegisterForm(prev => ({ ...prev, cv: file }));
      clearError('cv');
    }
  };

  const validateRegisterForm = (): boolean => {
    clearAllErrors();
    let isValid = true;

    if (!registerForm.email.trim()) {
      setError('email', 'El correo electrónico es obligatorio');
      isValid = false;
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(registerForm.email)) {
      setError('email', 'Ingresa un correo electrónico válido');
      isValid = false;
    }

    if (!registerForm.password.trim()) {
      setError('password', 'La contraseña es obligatoria');
      isValid = false;
    } else if (registerForm.password.length < 8) {
      setError('password', 'La contraseña debe tener al menos 8 caracteres');
      isValid = false;
    }

    if (!registerForm.confirmPassword.trim()) {
      setError('confirmPassword', 'Confirma tu contraseña');
      isValid = false;
    } else if (registerForm.password !== registerForm.confirmPassword) {
      setError('confirmPassword', 'Las contraseñas no coinciden');
      isValid = false;
    }

    return isValid;
  };

  const handleProcessCV = async () => {
    if (!registerForm.cv) {
      setError('cv', 'Debes subir un archivo PDF o DOCX antes de procesar.');
      return;
    }

    // Validación GDPR crítica antes de procesamiento
    if (!gdprConsent || !dataProcessingConsent) {
      toast({
        title: 'Consentimiento requerido',
        description: 'Debes aceptar el tratamiento de tus datos personales según GDPR para continuar.',
        variant: 'destructive'
      });
      return;
    }

    setIsProcessing(true);
    clearError('cv');

    try {
      const formData = new FormData();
      // Nuevo endpoint espera campo 'file'
      formData.append('file', registerForm.cv);
      formData.append('user_email', registerForm.email);

      toast({
        title: 'Procesando CV...',
        description: 'Analizando y normalizando tu CV (IA).',
        variant: 'default'
      });

      const apiUrl = `${API_CONFIG.BASE_URL}${API_CONFIG.ENDPOINTS.PDF_PARSE}`;
      console.log('[CV_PARSE] POST =>', apiUrl);
      const response = await fetch(apiUrl, { method: 'POST', body: formData });
      const text = await response.text();
      let json: any = null;
      try { json = JSON.parse(text); } catch (e) {
        console.error('[CV_PARSE] Respuesta no JSON', text.slice(0, 400));
        setError('cv', `Respuesta inválida del servidor (${response.status})`);
        setCvProcessingFailed(true);
        setShowManualForm(true);
        return;
      }

      if (response.ok && json?.success && json.data) {
        toast({
          title: 'CV procesado',
          description: 'Datos extraídos y normalizados listos para validar.',
          variant: 'default'
        });
        setRegisterForm(prev => ({ ...prev, cvData: json.data }));
        setShowValidationModal(true);
        setCvProcessingFailed(false);
      } else {
        const errMsg = json?.error?.message || json?.error?.code || 'Fallo en el parseo';
        setError('cv', `Error procesando CV: ${errMsg}`);
        if (json?.error?.code === 'PARSE_FAILED') {
          console.warn('Hints:', json?.error?.hints);
        }
        setCvProcessingFailed(true);
        setShowManualForm(true);
      }
    } catch (err) {
      console.error('[CV_PARSE] Error fetch', err);
      setError('cv', 'Error de conexión con el servicio de parseo.');
      setCvProcessingFailed(true);
      setShowManualForm(true);
    } finally {
      setIsProcessing(false);
    }
  };

  // Función para guardar datos validados del CV procesado por IA
  const handleSaveValidatedData = async (validatedData: any) => {
    setIsSaving(true);

    try {
      const payload = {
        candidate_data: {
