          consent_version: '1.0',
          processing_purposes: [
            'cv_analysis',
            'recruitment_process',
            'openai_processing',
            'communication'
          ],
          user_ip: 'client_side', // Se capturará en backend
          user_agent: navigator.userAgent
        }
      };

      const response = await fetch(`${API_CONFIG.BASE_URL}${API_CONFIG.ENDPOINTS.SAVE_CANDIDATE}`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(payload),
      });

      const data = await response.json();

      if (response.ok && data.success) {
        toast({
          title: 'Datos guardados exitosamente',
          description: 'Tu información ha sido validada y guardada correctamente.',
          variant: 'default'
        });

        setShowValidationModal(false);
        setSuccess(true);

        // AUTO-LOGIN después del registro exitoso
        try {
          // Intentar auto-login con las credenciales del registro
          if (registerForm.email && registerForm.password) {
            console.log('Intentando auto-login después del registro...');
            const loginSuccess = await candidateLogin(registerForm.email, registerForm.password);

            if (loginSuccess) {
              console.log('Auto-login exitoso, redirigiendo...');
