  // Funciones de utilidad memoizadas
  const formatDate = useMemo(() => (date: string) => {
    return new Date(date).toLocaleDateString('es-ES', {
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    });
  }, []);

  const getProgressPercentage = useMemo(() => {
    if (!application?.history?.length) return 0;
    const totalSteps = 5; // Postulación + 4 pasos futuros
    return (application.history.length / totalSteps) * 100;
  }, [application?.history?.length]);

  // Check if user is logged in and find application
  useEffect(() => {

    // Producción: solo usar contexto de autenticación
    const authContext = useAuth();
    if (!authContext.isLoggedIn) {
      navigate('/auth/register'); // Candidatos van al registro/login de candidatos
      return;
    }
    loadApplicationData(authContext.user?.email);
  }, [id, navigate]);

  const loadApplicationData = async (userEmail?: string) => {
    try {
      setLoading(true);
      setError(null);
      if (!userEmail) {
        navigate('/auth/register'); // Candidatos van al registro/login de candidatos
        return;
      }
      // Get all applications and jobs
      const [applicationsResponse, jobsResponse] = await Promise.all([
        getApplications(),
        getJobs()
      ]);

      if (!applicationsResponse.success || !jobsResponse.success) {
        throw new Error('Error al cargar los datos');
      }

      const applications = applicationsResponse.data || [];
      const jobs = jobsResponse.data || [];

      // Find the specific application by ID and user email
      const foundApplication = applications.find((app: any) =>
        app.id === id && app.candidate_email === userEmail
      );

      if (!foundApplication) {
        navigate('/dashboard/cddashboard');
        return;
      }

      // Create application history from status changes
      const history: ApplicationHistory[] = [
        {
          status: 'Recibida',
          date: foundApplication.created_at || foundApplication.application_date,
          notes: 'Solicitud recibida correctamente.'
        }
      ];

      // Add current status if different from 'Recibida'
      if (foundApplication.status && foundApplication.status !== 'Recibida') {
        history.push({
          status: foundApplication.status,
          date: foundApplication.updated_at || foundApplication.created_at,
          notes: foundApplication.notes || 'Estado actualizado por el equipo de RRHH.'
        });
      }

      const applicationData: Application = {
        id: foundApplication.id,
        jobId: foundApplication.job_id,
        status: foundApplication.status || 'Recibida',
        appliedDate: foundApplication.created_at || foundApplication.application_date,
        history: history
      };

      setApplication(applicationData);

      // Find job details
      const jobDetails = jobs.find((job: any) => job.id === foundApplication.job_id);
      if (jobDetails) {
        const jobData: Job = {
          id: jobDetails.id,
          title: jobDetails.title,
          location: jobDetails.location || jobDetails.company_location || 'No especificado',
          type: jobDetails.employment_type || jobDetails.type || 'No especificado',
          department: jobDetails.department,
          salary: jobDetails.salary
        };
        setJob(jobData);
      }

    } catch (error) {
      console.error('Error cargando aplicación:', error);
      setError('Error al cargar los detalles de la aplicación');
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <Layout>
        <div className="container mx-auto px-4 py-8">
          <div className="text-center">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-[#FF4785] mx-auto"></div>
            <p className="mt-4 text-gray-600">Cargando detalles de la aplicación...</p>
          </div>
        </div>
      </Layout>
    );
  }

  if (error) {
    return (
      <Layout>
        <div className="container mx-auto px-4 py-8">
          <div className="text-center">
            <p className="text-red-600">{error}</p>
            <Button
              onClick={() => navigate('/dashboard/cddashboard')}
              className="mt-4"
            >
              Volver al panel
            </Button>
          </div>
        </div>
      </Layout>
    );
  }

  if (!application || !job) {
    return (
      <Layout>
        <div className="container mx-auto px-4 py-8">
          <div className="text-center">
            <p className="text-gray-600">Aplicación no encontrada</p>
            <Button
              onClick={() => navigate('/dashboard/cddashboard')}
              className="mt-4"
            >
              Volver al panel
            </Button>
          </div>
        </div>
      </Layout>
    );
  }

  return (
    <Layout>
      {/* Dashboard Header */}
      <DashboardHeader
        title={`Aplicación: ${job?.title || 'Cargando...'}`}
        subtitle="Detalles y progreso de tu aplicación"
        breadcrumbs={[
          { label: 'Dashboard', href: '/dashboard/cddashboard' },
          { label: 'Mis Aplicaciones', href: '/dashboard/cddashboard' },
          { label: job?.title || 'Detalle' }
        ]}
        actions={
          <Button
            variant="outline"
            onClick={() => navigate('/dashboard/cddashboard')}
            className="flex items-center gap-2"
          >
            <ChevronLeft size={16} />
            Volver al panel
          </Button>
        }
      />

      <div className="container mx-auto px-4 py-8">
        {/* Application Header */}
        <Card className="mb-6">
          <CardHeader>
            <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-4">
              <div className="flex-1">
                <CardTitle className="text-2xl font-bold text-[#2F2F2F] mb-2">
                  {job.title}
                </CardTitle>
                <div className="flex flex-wrap items-center gap-4 text-gray-600">
                  <div className="flex items-center gap-1">
                    <MapPin size={16} />
                    <span>{job.location}</span>
                  </div>
                  <div className="flex items-center gap-1">
                    <Briefcase size={16} />
                    <span>{job.type}</span>
                  </div>
                  {job.department && (
                    <div className="flex items-center gap-1">
                      <span>🏢</span>
                      <span>{job.department}</span>
                    </div>
                  )}
                </div>
              </div>
              <div className="flex items-center gap-4">
                <StatusBadge status={application.status} size="lg" />
              </div>
            </div>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 border-t pt-6">
              <div className="text-center md:text-left">
                <div className="flex items-center justify-center md:justify-start gap-2 mb-1">
                  <Calendar size={16} className="text-[#FF4785]" />
                  <h3 className="text-sm font-medium text-gray-500">Fecha de postulación</h3>
                </div>
                <p className="font-semibold">{formatDate(application.appliedDate)}</p>
              </div>
              <div className="text-center md:text-left">
                <div className="flex items-center justify-center md:justify-start gap-2 mb-1">
                  <Clock size={16} className="text-[#FF4785]" />
                  <h3 className="text-sm font-medium text-gray-500">Última actualización</h3>
                </div>
                {application?.history?.length ? (
                  <p className="font-semibold">{formatDate(application.history[application.history.length - 1]?.date ?? '')}</p>
                ) : (
                  <p className="font-semibold text-gray-400">Sin historial</p>
                )}
              </div>
              <div className="text-center md:text-left">
                <div className="flex items-center justify-center md:justify-start gap-2 mb-1">
                  <span className="text-[#FF4785]">#️⃣</span>
                  <h3 className="text-sm font-medium text-gray-500">Referencia</h3>
                </div>
                <p className="font-semibold">#{application.id}</p>
              </div>
            </div>

            {/* Progress Bar */}
            <div className="mt-6 pt-6 border-t border-gray-200">
              <div className="flex items-center justify-between mb-2">
                <span className="text-sm font-medium text-gray-700">Progreso general</span>
                <span className="text-sm text-gray-500">{Math.round(getProgressPercentage)}%</span>
              </div>
              <div className="w-full bg-gray-200 rounded-full h-2">
                <div
                  className="bg-gradient-to-r from-[#FF4785] to-[#FF3575] h-2 rounded-full transition-all duration-500 ease-out"
                  style={{ width: `${getProgressPercentage}%` }}
                ></div>
              </div>
            </div>
          </CardContent>
        </Card>

        {/* Application Progress */}
        <Card className="mb-6">
          <CardHeader>
            <CardTitle className="text-xl font-semibold text-[#2F2F2F] flex items-center gap-2">
              <span className="text-[#FF4785]">📈</span>
              Progreso de tu postulación
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="relative">
              <div className="absolute left-3 top-0 bottom-0 w-0.5 bg-gray-200"></div>

              {application?.history?.map((item, index) => (
                <div key={index} className="relative flex items-start mb-6 last:mb-0">
                  <div className={`absolute left-3 -translate-x-1/2 w-6 h-6 rounded-full flex items-center justify-center ${index === application.history.length - 1
                    ? 'bg-[#FF4785] shadow-lg shadow-[#FF4785]/25'
                    : 'bg-green-500'
                    } text-white`}>
                    {index === application.history.length - 1 ? (
                      <span className="text-xs font-bold">{index + 1}</span>
                    ) : (
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" />
                      </svg>
                    )}
                  </div>

                  <div className="ml-10">
                    <div className="flex flex-col sm:flex-row sm:items-center gap-2">
                      <h3 className="font-semibold text-[#2F2F2F]">{item.status}</h3>
                      <span className="text-sm text-gray-500 flex items-center gap-1">
                        <Calendar size={14} />
                        {formatDate(item.date)}
                      </span>
                    </div>
                    <p className="text-gray-600 mt-1">{item.notes}</p>
                  </div>
                </div>
              ))}

              {/* Future steps (disabled) */}
              {['Entrevista', 'Prueba técnica', 'Entrevista final', 'Decisión'].map((step, index) => {
                const stepIndex = index + application.history.length;
                return (
                  <div key={stepIndex} className="relative flex items-start mb-6 last:mb-0 opacity-50">
                    <div className="absolute left-3 -translate-x-1/2 w-6 h-6 rounded-full flex items-center justify-center bg-gray-300 text-white">
                      <span className="text-xs">{stepIndex + 1}</span>
                    </div>

                    <div className="ml-10">
                      <h3 className="font-semibold text-gray-500">{step}</h3>
                      <p className="text-gray-400 mt-1">Pendiente</p>
                    </div>
                  </div>
                );
              })}
            </div>
          </CardContent>
        </Card>

        {/* Application Actions */}
        <Card>
          <CardHeader>
            <CardTitle className="text-lg font-semibold text-[#2F2F2F] flex items-center gap-2">
              <span className="text-[#FF4785]">⚙️</span>
              ¿Quieres actualizar algo?
            </CardTitle>
            <p className="text-gray-600">Puedes modificar o retirar tu postulación en cualquier momento</p>
          </CardHeader>
          <CardContent>
            <div className="flex flex-col sm:flex-row gap-4">
              <Button
                variant="outline"
                className="border-[#FF4785] text-[#FF4785] hover:bg-[#FF4785] hover:text-white"
              >
                Actualizar CV
              </Button>
              <Button
                variant="outline"
                className="text-red-600 border-red-600 hover:bg-red-50"
              >
                Retirar postulación
              </Button>
            </div>

            {/* Status Change Form */}
            <div className="mt-6 pt-6 border-t border-gray-200">
              <h3 className="text-sm font-medium text-gray-700 mb-4">Formulario de cambio de estado (Solo para pruebas)</h3>
              <StatusChangeForm />
            </div>
          </CardContent>
        </Card>
      </div>
    </Layout>
  );
}

import { useEffect, useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import {
  getCandidates,
  getJobs,
  getCandidateSkills,
  getCandidateExperiences,
  getNotifications,
} from '../../lib/apiService';
import { Button } from '../../components/ui/button';
import { Input } from '../../components/ui/input';
import {
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
} from '../../components/ui/tabs';
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from '../../components/ui/card';
import UploadCV from '../../components/UploadCV';

// Mini componente Switch
function Switch({ checked }: { checked: boolean }) {
  return (
    <div
      className={`w-10 h-5 rounded-full p-1 transition-colors ${checked ? 'bg-[#FF4785]' : 'bg-gray-300'}`}
    >
      <div
        className={`w-3 h-3 rounded-full bg-white transform transition-transform ${checked ? 'translate-x-5' : ''}`}
      />
    </div>
  );
}

function Label({ htmlFor, children }: { htmlFor: string; children: React.ReactNode }) {
  return (
    <label htmlFor={htmlFor} className="block font-semibold text-[#FF4785] mb-1">
      {children}
    </label>
  );
}

export default function CDDashboard() {
  const navigate = useNavigate();
  const [tab, setTab] = useState('profile');
  const [userEmail, setUserEmail] = useState('');

  const [applicationsWithDetails, setApplicationsWithDetails] = useState<any[]>([]);
  const [skillsCandidato, setSkillsCandidato] = useState<string[]>([]);
  // Lista de experiencias profesionales del candidato
  const [experiences, setExperiences] = useState<any[]>([]);
  // Notificaciones recibidas por el candidato
  const [notificationsList, setNotificationsList] = useState<any[]>([]);
  const [coverLetter, setCoverLetter] = useState('');
  const [salary, setSalary] = useState('');
  const [successMsg, setSuccessMsg] = useState('');
  const [loading, setLoading] = useState(false);
  const [candidateData, setCandidateData] = useState<any>(null);

  useEffect(() => {
    const email = localStorage.getItem('userEmail') || 'usuario@ejemplo.com';
    setUserEmail(email);

    const loadCandidateData = async () => {
      try {
        setLoading(true);
        // Obtener candidatos y buscar el actual por email
        const candidatesResponse = await getCandidates();

        if (candidatesResponse.success && candidatesResponse.data) {
          const candidato = candidatesResponse.data.find((c: any) => c.email === email);
          if (candidato) {
            setCandidateData(candidato);
            // Obtener habilidades desde el nuevo endpoint de candidate_skills
            try {
              const skills = await getCandidateSkills(candidato.id);
              // Mapear al arreglo de strings, fallback si el endpoint devuelve claves distintas
              const mappedSkills = skills.map((s: any) => s.skill || s.skills || s.name || s);
              setSkillsCandidato(mappedSkills);
            } catch (err) {
              console.error('Error loading candidate skills:', err);
              // Fallback a skills del candidato si están disponibles en el registro base
              setSkillsCandidato(candidato.skills ? candidato.skills.split(', ') : []);
            }
            // Obtener experiencias profesionales desde el nuevo endpoint
            try {
              const exps = await getCandidateExperiences(candidato.id);
              setExperiences(exps || []);
            } catch (err) {
              console.error('Error loading candidate experiences:', err);
              setExperiences([]);
            }
            // Obtener notificaciones del candidato
            try {
              const notifs = await getNotifications(candidato.id);
              setNotificationsList(notifs || []);
            } catch (err) {
              console.error('Error loading candidate notifications:', err);
              setNotificationsList([]);
            }
            // Si tiene trabajo aplicado, obtener detalles
            if (candidato.appliedJobId) {
              try {
                const jobsResponse = await getJobs();
                if (jobsResponse && Array.isArray(jobsResponse)) {
                  const job = jobsResponse.find((j: any) => j.id === candidato.appliedJobId);
                  if (job) {
                    setApplicationsWithDetails([
                      {
                        id: job.id,
                        job,
                        status: candidato.status || 'Received',
                        appliedDate: candidato.dateApplied || new Date().toISOString().split('T')[0],
                        score: candidato.score || '',
                        jobLocation: job.location,
                        jobType: job.type,
                        jobCategory: job.category,
                        jobDescription: job.description,
                      }
                    ]);
                  }
                }
              } catch (jobError) {
                console.error('Error loading job details:', jobError);
              }
            }
          }
        }
      } catch (error) {
        console.error('Error loading candidate data:', error);
        setSuccessMsg('Error al cargar datos del candidato');
      } finally {
        setLoading(false);
      }
    };

    loadCandidateData();
  }, []);

  const handleSimulateSubmit = () => {
    setLoading(true);
    setTimeout(() => {
      setSuccessMsg('¡Tu postulación fue enviada exitosamente (simulado)!');
      setCoverLetter('');
      setSalary('');
      setLoading(false);
    }, 1200);
  };

  return (
    <section className="py-8">
      <div className="container mx-auto px-4">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center bg-[#FF4785] rounded-md p-5 font-poppins">
          <div>
            <h1 className="text-2xl font-bold text-[#2F2F2F]">Candidate Dashboard</h1>
            <p className="text-white">Bienvenido, {userEmail}</p>
          </div>
          <div className="flex gap-2 mt-4 md:mt-0">
            {tab === 'profile' && (
              <Button
                className="bg-[#2F2F2F] text-white"
                onClick={() => {
                  setTab('applications');
                  navigate('/dashboard#applications');
                }}
              >
                Go to Dashboard
              </Button>
            )}
            <Button
              className="bg-white text-[#FF4785]"
              onClick={() => {
                setTab('profile');
                navigate('/dashboard#profile');
              }}
            >
              My Profile
            </Button>
            <Button
              className="bg-white text-[#FF4785]"
              onClick={() => {
                setTab('notifications');
                navigate('/dashboard#notifications');
              }}
            >
              Notifications
            </Button>
          </div>
        </div>

        <div className="py-8">
          <Tabs value={tab} onValueChange={setTab} className="w-full">
            <TabsList className="flex gap-2 mb-6">
              <TabsTrigger value="applications">Applications</TabsTrigger>
              <TabsTrigger value="profile">Profile</TabsTrigger>
              <TabsTrigger value="notifications">Notifications</TabsTrigger>
            </TabsList>

            {/* Applications */}
            <TabsContent value="applications" className="space-y-6">
              <h2 className="header-small">Solicitudes recientes</h2>
              {applicationsWithDetails.length ? (
                <div className="grid md:grid-cols-2 gap-4">
                  {applicationsWithDetails.map((app) => (
                    <Card key={app.id}>
                      <CardHeader>
                        <CardTitle>{app.job?.title}</CardTitle>
                        <CardDescription>{app.status}</CardDescription>
                      </CardHeader>
                      <CardContent>
                        <div className="space-y-2 text-sm">
                          <div>Fecha de postulación: {app.appliedDate}</div>
                          <div>Score: <span className="font-bold text-[#FF4785]">{app.score}%</span></div>
                          <div>Ubicación: {app.jobLocation}</div>
                          <div>Tipo: {app.jobType}</div>
                          <div>Categoría: {app.jobCategory}</div>
                          <div>Descripción: {app.jobDescription}</div>
                          <div>Skills requeridas: {app.job?.skills?.join(', ')}</div>
                          <div>Tus skills: {skillsCandidato.join(', ')}</div>
                        </div>
                      </CardContent>
                      <CardFooter>
                        <Button variant="outline" size="sm" className="text-[#2F2F2F] border-[#FF4785]">
                          Ver detalles
                        </Button>
                      </CardFooter>
                    </Card>
                  ))}
                </div>
              ) : (
                <Card>
                  <CardContent className="py-12 text-center">
                    <h3 className="text-lg font-bold mb-2">Aún no tienes solicitudes</h3>
                    <p className="text-sm mb-6">Explora nuestras ofertas y postúlate</p>
                    <Button className="bg-[#FF4785] hover:bg-[#FF3575]">Ver empleos disponibles</Button>
                  </CardContent>
                </Card>
              )}
            </TabsContent>

            {/* Profile */}
            <TabsContent value="profile">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <Card className="md:col-span-2">
                  <CardHeader>
                    <CardTitle>Personal Information</CardTitle>
                    <CardDescription>Update your personal data</CardDescription>
                  </CardHeader>
                  <CardContent className="space-y-4">
                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <Label htmlFor="firstName">First Name</Label>
                        <Input id="firstName" defaultValue="User" />
                      </div>
                      <div>
                        <Label htmlFor="lastName">Last Name</Label>
                        <Input id="lastName" defaultValue="Example" />
                      </div>
                    </div>
                    <div>
                      <Label htmlFor="email">Email</Label>
                      <Input id="email" value={userEmail || ''} readOnly />
                    </div>
                    <div>
                      <Label htmlFor="phone">Phone</Label>
                      <Input id="phone" placeholder="Add your phone number" />
                    </div>
                  </CardContent>
                  <CardFooter>
                    <Button className="ml-auto bg-[#FF4785] hover:bg-[#FF3575]">
                      Save changes
                    </Button>
                  </CardFooter>
                </Card>
                <div className="space-y-6">
                  <Card>
                    <CardHeader>
                      <CardTitle>CV and Documents</CardTitle>
                    </CardHeader>
                    <CardContent>
                      <UploadCV onSuccess={(candidate) => {
                        console.log('Candidato actualizado:', candidate);
                        setSuccessMsg('¡Tu CV fue actualizado exitosamente!');
                      }} />
                      <div className="mt-8 space-y-4">
                        <label className="block font-semibold text-[#FF4785]" htmlFor="coverLetter">Carta de presentación</label>
                        <textarea
                          id="coverLetter"
                          name="coverLetter"
                          rows={4}
                          className="w-full border rounded px-3 py-2"
                          placeholder="Escribe una breve carta de presentación..."
                          value={coverLetter}
                          onChange={e => setCoverLetter(e.target.value)}
                        />
                        <label className="block font-semibold text-[#FF4785]" htmlFor="salary">Pretensión salarial (USD)</label>
                        <input
                          id="salary"
                          name="salary"
                          type="number"
                          className="w-full border rounded px-3 py-2"
                          placeholder="Ej: 1200"
                          min="0"
                          value={salary}
                          onChange={e => setSalary(e.target.value)}
                        />
                        <button
                          type="button"
                          className="w-full bg-[#FF4785] hover:bg-[#FF3575] text-white font-bold py-2 rounded"
                          onClick={handleSimulateSubmit}
                          disabled={loading}
                        >
                          {loading ? 'Enviando...' : 'Enviar postulación'}
                        </button>
                        {successMsg && (
                          <div className="text-green-600 font-semibold text-center mt-2">{successMsg}</div>
                        )}
                      </div>
                    </CardContent>
                  </Card>
                </div>
              </div>

              {/* Experiencias profesionales */}
              <div className="mt-6">
                <Card>
                  <CardHeader>
                    <CardTitle>Professional Experience</CardTitle>
                    <CardDescription>Historial laboral del candidato</CardDescription>
                  </CardHeader>
                  <CardContent className="space-y-4">
                    {experiences && experiences.length > 0 ? (
                      experiences.map((exp: any, idx: number) => (
                        <div key={idx} className="border-b pb-2 last:border-b-0 last:pb-0">
                          <div className="font-medium text-[#2F2F2F]">{exp.position} @ {exp.company}</div>
                          <div className="text-xs text-gray-500">
                            {exp.start_date} – {exp.end_date || (exp.current ? 'Present' : '')}
                            {exp.location ? ` • ${exp.location}` : ''}
                          </div>
                          {exp.description && (
                            <p className="text-sm text-gray-700 mt-1">{exp.description}</p>
                          )}
                        </div>
                      ))
                    ) : (
                      <p className="text-sm text-gray-600">No hay experiencias laborales registradas.</p>
                    )}
                  </CardContent>
                </Card>
              </div>
            </TabsContent>

            {/* Notifications */}
            <TabsContent value="notifications">
              <div className="space-y-6">
                {/* Lista de notificaciones reales */}
                <Card>
                  <CardHeader>
                    <CardTitle>Your Notifications</CardTitle>
                    <CardDescription>Últimas notificaciones recibidas</CardDescription>
                  </CardHeader>
                  <CardContent className="space-y-4">
                    {notificationsList && notificationsList.length > 0 ? (
                      notificationsList.map((notif: any, idx: number) => (
                        <div key={idx} className="border-b pb-2 last:border-b-0 last:pb-0">
                          <div className="font-medium text-[#2F2F2F]">{notif.message}</div>
                          {notif.created_at && (
                            <div className="text-xs text-gray-500">{new Date(notif.created_at).toLocaleString()}</div>
                          )}
                        </div>
                      ))
                    ) : (
                      <p className="text-sm text-gray-600">No tienes notificaciones recientes.</p>
                    )}
                  </CardContent>
                </Card>

                {/* Preferencias de notificación (estático por ahora) */}
                <Card>
                  <CardHeader>
                    <CardTitle>Notification Preferences</CardTitle>
                    <CardDescription>Ajusta cómo deseas recibir alertas</CardDescription>
                  </CardHeader>
                  <CardContent className="space-y-4">
                    {[
                      {
                        title: 'Application Updates',
                        description: 'Receive notifications when the status of your applications changes',
                        checked: true,
                      },
                      {
                        title: 'New Jobs',
                        description: 'Get alerts about new jobs that match your profile',
                        checked: false,
                      },
                      {
                        title: 'Reminders',
                        description: 'Receive reminders about interviews or events',
                        checked: true,
                      },
                    ].map((item, idx) => (
                      <div key={idx} className="flex items-center justify-between border-b pb-2 last:border-b-0 last:pb-0">
                        <div>
                          <div className="font-semibold">{item.title}</div>
                          <div className="text-sm text-muted-foreground">
                            {item.description}
                          </div>
                        </div>
                        <Switch checked={item.checked} />
                      </div>
                    ))}
                  </CardContent>
                  <CardFooter>
                    <Button className="ml-auto bg-[#FF4785] hover:bg-[#FF3575]">
                      Save preferences
                    </Button>
                  </CardFooter>
                </Card>
              </div>
            </TabsContent>
          </Tabs>
        </div>
      </div>
    </section>
  );
}

import { Layout } from '../../components/layout/Layout';
import { Card, CardHeader, CardTitle, CardContent } from '../../components/ui/card';
import { Button } from '../../components/ui/button';
import { getCandidates, getJobs, getHRDashboardStats } from '../../lib/apiService';
import { Bar, Pie } from 'react-chartjs-2';
import { Chart, CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend, ArcElement } from 'chart.js';
import { useMemo, useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { TrendingUp, Users, FileText, Clock, BarChart3, PieChart } from 'lucide-react';
import StatusChangeForm from '../../components/StatusChangeForm';
import { DashboardHeader } from '../../components/ui/dashboard-header';
import { StatusBadge } from '../../components/ui/status-badge';
import { Filters } from '../../components/ui/filters';

Chart.register(CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend, ArcElement);

export default function EstadisticasRRHH() {
    const navigate = useNavigate();
    const [candidates, setCandidates] = useState<any[]>([]);
    const [jobs, setJobs] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    // Estados para filtros
    const [searchTerm, setSearchTerm] = useState('');
    const [statusFilter, setStatusFilter] = useState('');
    const [departmentFilter, setDepartmentFilter] = useState('');
    const [dateRange, setDateRange] = useState('all'); // all, month, quarter, year

    // Estados calculados
    const [stats, setStats] = useState({
        totalApplications: 0,
        totalHired: 0,
        totalRejected: 0,
        totalInterview: 0,
        avgTimeToHire: '12 días'
    });

    useEffect(() => {
        const loadData = async () => {
            try {
                setLoading(true);
                const [candidatesResponse, jobsResponse] = await Promise.all([
                    getCandidates(),
                    getJobs()
                ]);

                if (candidatesResponse.success && candidatesResponse.data) {
                    setCandidates(candidatesResponse.data);
                }

                if (jobsResponse && Array.isArray(jobsResponse)) {
                    setJobs(jobsResponse);
                }

                // Calcular estadísticas mejoradas
                const candidatesData = candidatesResponse.data || [];
                const totalCandidates = candidatesData.length;
                const hired = candidatesData.filter((c: any) => c.status === 'Hired' || c.status === 'Offer Accepted').length;
                const rejected = candidatesData.filter((c: any) => c.status === 'Rejected').length;
                const interviews = candidatesData.filter((c: any) =>
                    c.status === 'Interview' ||
                    c.status === 'Second Interview' ||
                    c.status === 'Final Interview'
                ).length;

                setStats({
                    totalApplications: totalCandidates,
                    totalHired: hired,
                    totalRejected: rejected,
                    totalInterview: interviews,
                    avgTimeToHire: '12 días'
                });

            } catch (err) {
                console.error('Error loading data:', err);
                setError('Error al cargar los datos');
            } finally {
                setLoading(false);
            }
        };

        loadData();
    }, []);

    const APPLICATION_STATUS = ['Under Review', 'Interview', 'Technical Test', 'Offer Extended', 'Offer Accepted', 'Rejected'];

    // Datos filtrados basados en filtros
    const filteredCandidates = useMemo(() => {
        let filtered = candidates;

        if (searchTerm) {
            filtered = filtered.filter(c =>
                c.name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
                c.email?.toLowerCase().includes(searchTerm.toLowerCase())
            );
        }

        if (statusFilter) {
            filtered = filtered.filter(c => c.status === statusFilter);
        }

        if (departmentFilter) {
            filtered = filtered.filter(c => c.department === departmentFilter);
        }

        return filtered;
    }, [candidates, searchTerm, statusFilter, departmentFilter]);

    // Datos para gráficos actualizados con filtros
    const jobTitles = jobs.map(job => job.title);
    const applicationsByJob = jobTitles.map(title =>
        filteredCandidates.filter(c => c.jobPosition === title).length
    );
    const statusCounts = APPLICATION_STATUS.map(status =>
        filteredCandidates.filter(c => c.status === status).length
    );

    // Pie chart: distribución por nivel educativo
    const educationLevels = ["Primary", "Secondary", "Undergraduate", "Master's", "Doctorate", "Other"];
    const educationCounts = educationLevels.map(level =>
        filteredCandidates.filter(c => c.educationLevel === level).length
    );
    const barData = useMemo(() => ({
        labels: jobTitles,
        datasets: [
            {
                label: 'Aplicaciones por Puesto',
                data: applicationsByJob,
                backgroundColor: '#FF4785',
                borderColor: '#FF3575',
                borderWidth: 1,
                borderRadius: 4,
            },
        ],
    }), [jobTitles, applicationsByJob]);

    const statusData = useMemo(() => ({
        labels: APPLICATION_STATUS,
        datasets: [
            {
                label: 'Estado de Aplicaciones',
                data: statusCounts,
                backgroundColor: [
                    '#FCD34D', // Under Review - amarillo
                    '#60A5FA', // Interview - azul
                    '#A78BFA', // Technical Test - morado
                    '#34D399', // Offer Extended - verde
                    '#10B981', // Offer Accepted - verde oscuro
                    '#F87171', // Rejected - rojo
                ],
                borderWidth: 2,
                borderColor: '#FFFFFF',
            },
        ],
    }), [statusCounts]);

    const educationData = useMemo(() => ({
        labels: educationLevels,
        datasets: [
            {
                label: 'Distribución por Educación',
                data: educationCounts,
                backgroundColor: [
                    '#FF4785',
                    '#FF3575',
                    '#2F2F2F',
                    '#60A5FA',
                    '#A78BFA',
                    '#34D399',
                ],
                borderWidth: 2,
                borderColor: '#FFFFFF',
            },
        ],
    }), [educationCounts]);

    if (loading) {
        return (
            <Layout>
                <div className="flex justify-center items-center min-h-[400px]">
                    <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-500"></div>
                </div>
            </Layout>
        );
    }

    if (error) {
        return (
            <Layout>
                <div className="text-center text-red-600 min-h-[400px] flex items-center justify-center">
                    <p>{error}</p>
                </div>
            </Layout>
        );
    }

    return (
        <Layout>
            {/* Dashboard Header */}
            <DashboardHeader
                title="Estadísticas RRHH"
                subtitle="Análisis completo de procesos de selección y métricas de rendimiento"
                breadcrumbs={[
                    { label: 'Dashboard', href: '/dashboard/hrdashboard' },
                    { label: 'Estadísticas' }
                ]}
                actions={
                    <div className="flex gap-2">
                        <Button
                            variant="outline"
                            onClick={() => navigate('/dashboard/hrdashboard')}
                            className="border-[#FF4785] text-[#FF4785] hover:bg-[#FF4785] hover:text-white"
                        >
                            🏠 HR Dashboard
                        </Button>
                        <Button
                            variant="outline"
                            onClick={() => navigate('/dashboard/recruiter')}
                            className="border-[#FF4785] text-[#FF4785] hover:bg-[#FF4785] hover:text-white"
                        >
                            👨‍💼 Recruiter
                        </Button>
                    </div>
                }
            />

            <div className="container mx-auto px-4 py-8">
                {/* Filtros */}
                <Card className="mb-6">
                    <CardHeader>
                        <CardTitle className="flex items-center gap-2">
                            <BarChart3 size={20} className="text-[#FF4785]" />
                            Filtros de Análisis
                        </CardTitle>
                    </CardHeader>
                    <CardContent>
                        <Filters
                            searchTerm={searchTerm}
                            onSearchChange={setSearchTerm}
                            searchPlaceholder="🔍 Buscar candidatos..."
                            statusFilter={statusFilter}
                            onStatusChange={setStatusFilter}
                            departmentFilter={departmentFilter}
                            onDepartmentChange={setDepartmentFilter}
                            customFilters={[
                                {
                                    value: dateRange,
                                    onChange: setDateRange,
                                    options: [
                                        { value: 'all', label: 'Todo el tiempo', icon: '📅' },
                                        { value: 'month', label: 'Último mes', icon: '📅' },
                                        { value: 'quarter', label: 'Último trimestre', icon: '📅' },
                                        { value: 'year', label: 'Último año', icon: '📅' }
                                    ],
                                    placeholder: '📅 Periodo'
                                }
                            ]}
                            onClearFilters={() => {
                                setSearchTerm('');
                                setStatusFilter('');
                                setDepartmentFilter('');
                                setDateRange('all');
                            }}
                        />
                    </CardContent>
                </Card>

                {/* KPI Cards */}
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
                    <Card className="border-l-4 border-l-[#FF4785]">
                        <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                            <CardTitle className="text-sm font-medium">Total Aplicaciones</CardTitle>
                            <FileText className="h-4 w-4 text-[#FF4785]" />
                        </CardHeader>
                        <CardContent>
                            <div className="text-2xl font-bold text-[#FF4785]">{stats.totalApplications}</div>
                            <p className="text-xs text-gray-500 mt-1">
                                {filteredCandidates.length !== candidates.length &&
                                    `(${filteredCandidates.length} filtrados)`
                                }
                            </p>
                        </CardContent>
                    </Card>

                    <Card className="border-l-4 border-l-green-500">
                        <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                            <CardTitle className="text-sm font-medium">Contratados</CardTitle>
                            <Users className="h-4 w-4 text-green-500" />
                        </CardHeader>
                        <CardContent>
                            <div className="text-2xl font-bold text-green-600">{stats.totalHired}</div>
                            <p className="text-xs text-gray-500 mt-1">
                                {stats.totalApplications > 0 ?
                                    `${((stats.totalHired / stats.totalApplications) * 100).toFixed(1)}% éxito`
                                    : '0% éxito'
                                }
                            </p>
                        </CardContent>
                    </Card>

                    <Card className="border-l-4 border-l-blue-500">
                        <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                            <CardTitle className="text-sm font-medium">En Entrevista</CardTitle>
                            <Clock className="h-4 w-4 text-blue-500" />
                        </CardHeader>
                        <CardContent>
                            <div className="text-2xl font-bold text-blue-600">{stats.totalInterview}</div>
                            <p className="text-xs text-gray-500 mt-1">
                                {stats.totalApplications > 0 ?
                                    `${((stats.totalInterview / stats.totalApplications) * 100).toFixed(1)}% en proceso`
                                    : '0% en proceso'
                                }
                            </p>
                        </CardContent>
                    </Card>

                    <Card className="border-l-4 border-l-red-500">
                        <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                            <CardTitle className="text-sm font-medium">Rechazados</CardTitle>
                            <TrendingUp className="h-4 w-4 text-red-500" />
                        </CardHeader>
                        <CardContent>
                            <div className="text-2xl font-bold text-red-600">{stats.totalRejected}</div>
                            <p className="text-xs text-gray-500 mt-1">
                                {stats.totalApplications > 0 ?
                                    `${((stats.totalRejected / stats.totalApplications) * 100).toFixed(1)}% rechazados`
                                    : '0% rechazados'
                                }
                            </p>
                        </CardContent>
                    </Card>
                </div>

                {/* Charts */}
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 mb-8">
                    <Card>
                        <CardHeader>
                            <CardTitle className="flex items-center gap-2">
                                <BarChart3 size={20} className="text-[#FF4785]" />
                                Aplicaciones por Puesto
                            </CardTitle>
                        </CardHeader>
                        <CardContent>
                            <Bar
                                data={barData}
                                options={{
                                    responsive: true,
                                    plugins: {
                                        legend: {
                                            labels: { color: '#4B5563' }
                                        }
                                    },
                                    scales: {
                                        x: { ticks: { color: '#6B7280' } },
                                        y: { ticks: { color: '#6B7280' } }
                                    },
                                }}
                            />
                        </CardContent>
                    </Card>

                    <Card>
                        <CardHeader>
                            <CardTitle className="flex items-center gap-2">
                                <PieChart size={20} className="text-[#FF4785]" />
                                Estado de Aplicaciones
                            </CardTitle>
                        </CardHeader>
                        <CardContent>
                            <Pie
                                data={statusData}
                                options={{
                                    responsive: true,
                                    plugins: {
                                        legend: {
                                            position: 'bottom',
                                            labels: { color: '#4B5563', padding: 20 }
                                        }
                                    }
                                }}
                            />
                        </CardContent>
                    </Card>
                </div>

                {/* Education Distribution Chart */}
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 mb-8">
                    <Card>
                        <CardHeader>
                            <CardTitle className="flex items-center gap-2">
                                <PieChart size={20} className="text-[#FF4785]" />
                                Distribución por Educación
                            </CardTitle>
                        </CardHeader>
                        <CardContent>
                            <Pie
                                data={educationData}
                                options={{
                                    responsive: true,
                                    plugins: {
                                        legend: {
                                            position: 'bottom',
                                            labels: { color: '#4B5563', padding: 20 }
                                        }
                                    }
                                }}
                            />
                        </CardContent>
                    </Card>

                    {/* Summary Table */}
                    <Card>
                        <CardHeader>
                            <CardTitle className="flex items-center gap-2">
                                <FileText size={20} className="text-[#FF4785]" />
                                Resumen por Puesto
                            </CardTitle>
                        </CardHeader>
                        <CardContent>
                            <div className="overflow-x-auto">
                                <table className="w-full text-sm">
                                    <thead>
                                        <tr className="border-b">
                                            <th className="text-left py-2">Puesto</th>
                                            <th className="text-center py-2">Aplicaciones</th>
                                            <th className="text-center py-2">Contratados</th>
                                            <th className="text-center py-2">Tasa</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {jobs.map(job => {
                                            const total = filteredCandidates.filter((c: any) => c.jobPosition === job.title).length;
                                            const hired = filteredCandidates.filter((c: any) =>
                                                c.jobPosition === job.title &&
                                                (c.status === 'Hired' || c.status === 'Offer Accepted')
                                            ).length;
                                            const rate = total > 0 ? ((hired / total) * 100).toFixed(1) : '0';
                                            return (
                                                <tr key={job.id} className="border-b">
                                                    <td className="py-2 font-medium">{job.title}</td>
                                                    <td className="text-center py-2">{total}</td>
                                                    <td className="text-center py-2">{hired}</td>
                                                    <td className="text-center py-2">
                                                        <span className={`px-2 py-1 rounded text-xs ${parseFloat(rate) > 50 ? 'bg-green-100 text-green-800' :
                                                                parseFloat(rate) > 25 ? 'bg-yellow-100 text-yellow-800' :
                                                                    'bg-red-100 text-red-800'
                                                            }`}>
                                                            {rate}%
                                                        </span>
                                                    </td>
                                                </tr>
                                            );
                                        })}
                                    </tbody>
                                </table>
                            </div>
                        </CardContent>
                    </Card>
                </div>

                {/* Status Change Form (for testing) */}
                <Card>
                    <CardHeader>
                        <CardTitle className="text-sm text-gray-600">Herramientas de Prueba</CardTitle>
                    </CardHeader>
                    <CardContent>
                        <StatusChangeForm />
                    </CardContent>
                </Card>
            </div>
        </Layout>
    );
}

/**
 * Lazy Loading Component for Statistics Dashboard
 * Optimiza la carga inicial cargando charts solo cuando sea necesario
 */

import React, { lazy, Suspense } from 'react';
import LoadingSpinner from '../../components/ui/LoadingSpinner';

// Lazy load del componente Estadisticas pesado
const EstadisticasLazy = lazy(() =>
  import('./Estadisticas').then(module => ({ default: module.default }))
);

interface EstadisticasOptimizedProps {
  // Props del componente original si las hay
}

export const EstadisticasOptimized: React.FC<EstadisticasOptimizedProps> = (props) => {
  return (
    <Suspense
      fallback={
        <div className="flex flex-col items-center justify-center min-h-[400px]">
          <LoadingSpinner size="large" />
          <span className="ml-3 text-gray-600">Cargando estadísticas...</span>
          <p className="text-sm text-gray-500 mt-2">Preparando gráficos y datos</p>
        </div>
      }
    >
      <EstadisticasLazy {...props} />
    </Suspense>
  );
};

export default EstadisticasOptimized;

import React, { useEffect, useState, useMemo, useReducer } from 'react';
import { Button } from '../../components/ui/button';
import { Tabs, TabsList, TabsTrigger, TabsContent } from '../../components/ui/tabs';
import { Card, CardHeader, CardTitle, CardContent } from '../../components/ui/card';
import { ApplicationsTable, ApplicationDetailsDialog } from '../../components/dashboard/ApplicationsTable';
import { Plus, Menu, Bot } from 'lucide-react';
import ChatbotAdmin from '../../components/ChatBotManage';
import StatusChangeForm from '../../components/StatusChangeForm';
import { StatusBadge } from '../../components/ui/status-badge';
import { Filters } from '../../components/ui/filters';
import { DashboardHeader } from '../../components/ui/dashboard-header';
import {
  getHRDashboardStats,
  getApplications,
  getCandidates,
  getJobs,
  getRecruiters,
  getCandidateSkills,
  getCandidateExperiences,
} from '../../lib/apiService';
import { getCandidateDepartmentAssignment } from '@/lib/candidate-department-assignment';

import { useNavigate } from 'react-router-dom';
