// Definición de tipos
interface Candidate {
  id: string;
  name: string;
  email: string;
  location?: string;
  skills?: string[];
  department?: string;
  // Otros campos...
}

interface Job {
  id: string;
  title: string;
  location?: string;
  skills?: string[];
  department?: string;
  // Otros campos...
}

interface Application {
  id: string;
  candidate: Candidate;
