// src/pages/dashboard/RecruiterDashboard.tsx
import React, { useState, useEffect, useReducer, useMemo } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { Button } from '../../components/ui/button';
import { Tabs, TabsList, TabsTrigger, TabsContent } from '../../components/ui/tabs';
import { Card, CardHeader, CardTitle, CardContent } from '../../components/ui/card';
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from '../../components/ui/dropdown-menu';
import { StatusBadge } from '../../components/ui/status-badge';
import { Filters } from '../../components/ui/filters';
import { DashboardHeader } from '../../components/ui/dashboard-header';
import StatusChangeForm from '../../components/StatusChangeForm';
import { sendCandidateStatusUpdateNotification } from '../../lib/emailService';
import { toast } from '../../components/ui/use-toast';

interface Candidate {
    id: string;
    name: string;
    email: string;
    phone?: string;
    location?: string;
    skills?: string[];
    estado?: string;
    jobPosition?: string;
    assignedCategory?: string;
    categoria?: string;
    reclutador?: string;
    emailReclutador?: string;
    department?: string;
}

interface Job {
    id: string;
    title: string;
    location?: string;
    skills?: string[];
}

interface Application {
    id: string;
    candidateId: string;
    jobId: string;
    candidate: Candidate;
    job: Job;
    appliedDate: string;
    status: string;
    score: number;
}

interface Interview {
    id: string;
    candidateId: string;
    recruiterId: string;
    candidate: Candidate;
    recruiterName: string;
    recruiterEmail: string;
    date: string;
    time: string;
    duration: number; // en minutos
    location: string;
    type: 'presencial' | 'virtual' | 'telefónica';
    status: 'scheduled' | 'completed' | 'cancelled' | 'rescheduled';
    notes?: string;
    meetingLink?: string;
}

interface RecruiterDashboardProps {
    recruiterId?: string;
}

// Reducer para manejo de entrevistas
interface InterviewState {
    interviews: Interview[];
    loading: boolean;
    error: string | null;
}

type InterviewAction =
    | { type: 'SET_LOADING'; payload: boolean }
    | { type: 'SET_ERROR'; payload: string | null }
    | { type: 'LOAD_INTERVIEWS'; payload: Interview[] }
    | { type: 'ADD_INTERVIEW'; payload: Interview }
    | { type: 'UPDATE_INTERVIEW'; payload: { id: string; updates: Partial<Interview> } }
    | { type: 'CANCEL_INTERVIEW'; payload: string }
    | { type: 'DELETE_INTERVIEW'; payload: string };

const interviewReducer = (state: InterviewState, action: InterviewAction): InterviewState => {
    switch (action.type) {
        case 'SET_LOADING':
            return { ...state, loading: action.payload };
        case 'SET_ERROR':
            return { ...state, error: action.payload };
        case 'LOAD_INTERVIEWS':
            return { ...state, interviews: action.payload, loading: false, error: null };
        case 'ADD_INTERVIEW':
            const newInterviews = [...state.interviews, action.payload];
            // Guardar en localStorage
            localStorage.setItem('scheduledInterviews', JSON.stringify(newInterviews));
            return { ...state, interviews: newInterviews };
        case 'UPDATE_INTERVIEW':
            const updatedInterviews = state.interviews.map(interview =>
                interview.id === action.payload.id
                    ? { ...interview, ...action.payload.updates }
                    : interview
            );
            localStorage.setItem('scheduledInterviews', JSON.stringify(updatedInterviews));
            return { ...state, interviews: updatedInterviews };
        case 'CANCEL_INTERVIEW':
            const cancelledInterviews = state.interviews.map(interview =>
                interview.id === action.payload
                    ? { ...interview, status: 'cancelled' as const }
                    : interview
            );
            localStorage.setItem('scheduledInterviews', JSON.stringify(cancelledInterviews));
            return { ...state, interviews: cancelledInterviews };
        case 'DELETE_INTERVIEW':
            const filteredInterviews = state.interviews.filter(interview => interview.id !== action.payload);
            localStorage.setItem('scheduledInterviews', JSON.stringify(filteredInterviews));
            return { ...state, interviews: filteredInterviews };
        default:
            return state;
    }
};

const RecruiterDashboard: React.FC<RecruiterDashboardProps> = ({ recruiterId: propRecruiterId }) => {
    const { user } = useAuth();
    const recruiterId = propRecruiterId || user?.id || 'default-recruiter';

    // Componente de Filtros - usando componente reutilizable
    const CandidateFilters = React.memo(() => (
        <Filters
            searchTerm={searchTerm}
            onSearchChange={setSearchTerm}
            searchPlaceholder="🔍 Buscar candidatos por nombre..."
            statusFilter={statusFilter}
            onStatusChange={setStatusFilter}
            departmentFilter={departmentFilter}
            onDepartmentChange={setDepartmentFilter}
            onClearFilters={clearFiltersCallback}
        />
    ));

    // Componente Quick Actions Menu - memoizado
    const QuickActionsMenu = React.memo(({ candidate }: { candidate: any }) => (
        <DropdownMenu>
            <DropdownMenuTrigger asChild>
                <Button variant="ghost" size="sm" className="h-8 w-8 p-0">
                    <span className="text-lg">⋮</span>
                </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="w-48">
                <DropdownMenuItem
                    onClick={() => {
                        setInterviewForm(prev => ({ ...prev, candidateId: candidate.candidateId }));
                        setShowScheduleForm(true);
                        setActiveTab('interviews');
                    }}
                    className="cursor-pointer"
                >
                    📅 Programar Entrevista
                </DropdownMenuItem>
                <DropdownMenuItem
                    onClick={() => {
                        window.open(`mailto:${candidate.email || `candidate${candidate.candidateId}@example.com`}`, '_blank');
                    }}
                    className="cursor-pointer"
                >
                    ✉️ Enviar Email
                </DropdownMenuItem>
                <DropdownMenuItem
                    onClick={() => {
                        window.open(`tel:${candidate.phone || ''}`, '_blank');
                    }}
                    className="cursor-pointer"
                >
                    📞 Llamar
                </DropdownMenuItem>
                <DropdownMenuItem
                    onClick={() => {
                        // Aquí podrías abrir un modal con el CV o descargar el archivo
                        toast({
                            title: "CV del candidato",
                            description: `Abriendo CV de ${candidate.candidateName}`,
                            duration: 3000
                        });
                    }}
                    className="cursor-pointer"
                >
                    📄 Ver CV
                </DropdownMenuItem>
                <DropdownMenuItem
                    onClick={() => {
                        setSelectedCandidate({
                            id: candidate.candidateId,
                            name: candidate.candidateName,
                            email: candidate.email || `candidate${candidate.candidateId}@example.com`
                        });
                        // Scroll to status change form
                        document.getElementById('status-change-section')?.scrollIntoView({ behavior: 'smooth' });
                    }}
                    className="cursor-pointer"
                >
                    🔄 Cambiar Estado
                </DropdownMenuItem>
            </DropdownMenuContent>
        </DropdownMenu>
    ));

    // Componente CandidateCard memoizado
    const CandidateCard = React.memo(({ candidate }: { candidate: any }) => (
        <Card className="border hover:shadow-md transition-shadow">
            <CardContent className="p-4">
                <div className="flex justify-between items-start">
                    <div className="flex-1">
                        <div className="flex items-center gap-3 mb-2">
                            <h3 className="font-semibold text-lg text-[#2F2F2F]">{candidate.candidateName}</h3>
                            <StatusBadge status={candidate.status || 'Under Review'} />
                        </div>
                        <div className="space-y-1 text-sm">
                            <p className="text-gray-600 flex items-center gap-2">
                                <span className="font-medium">📍 Departamento:</span>
                                {candidate.candidateDepartment}
                            </p>
                            <p className="text-gray-500 flex items-center gap-2">
                                <span className="font-medium">📅 Asignado:</span>
                                {candidate.assignedDate}
                            </p>
                            {candidate.email && (
                                <p className="text-gray-500 flex items-center gap-2">
                                    <span className="font-medium">✉️ Email:</span>
                                    {candidate.email}
                                </p>
                            )}
                        </div>
                    </div>
                    <div className="flex gap-2 ml-4">
                        <Button
                            size="sm"
                            className="bg-[#FF4785] hover:bg-[#FF3575] text-white shadow-sm"
                            onClick={() => handleScheduleInterviewCallback(candidate.candidateId)}
                        >
                            📅 Programar Entrevista
                        </Button>
                        <QuickActionsMenu candidate={candidate} />
                    </div>
                </div>
            </CardContent>
        </Card>
    ));

    const [isLoading, setIsLoading] = useState(true);
    const [activeTab, setActiveTab] = useState('candidates'); // Empezar en candidatos, no overview

    // Estados para filtros y búsqueda
    const [searchTerm, setSearchTerm] = useState('');
    const [statusFilter, setStatusFilter] = useState('');
    const [departmentFilter, setDepartmentFilter] = useState('');

    // Estados para gestión de candidatos y entrevistas
    const [assignedCandidates, setAssignedCandidates] = useState<any[]>([]);
    const [applications, setApplications] = useState<Application[]>([]);

    // Manejo de entrevistas con useReducer
    const [interviewState, dispatchInterview] = useReducer(interviewReducer, {
        interviews: [],
        loading: false,
        error: null
    });

    const [selectedCandidate, setSelectedCandidate] = useState<Candidate | null>(null);
    const [selectedApplication, setSelectedApplication] = useState<Application | null>(null);

    // Estados para formularios
    const [statusForm, setStatusForm] = useState({ estado: '', notas: '' });
    const [interviewForm, setInterviewForm] = useState({
        candidateId: '',
        date: '',
        time: '',
        duration: 60,
        location: '',
        type: 'virtual' as 'presencial' | 'virtual' | 'telefónica',
        notes: '',
        meetingLink: ''
    });
    const [showScheduleForm, setShowScheduleForm] = useState(false);
    const [statusMsg, setStatusMsg] = useState('');

    useEffect(() => {
        const loadDashboardData = async () => {
            try {
                setIsLoading(true);

                // Cargar candidatos asignados (simulado)
                const recruiterEmail = user?.email || localStorage.getItem('userEmail');
                if (recruiterEmail) {
                    // Aquí normalmente cargarías desde la API
                    // Por ahora usamos datos mock
                    const mockAssignedCandidates = [
                        {
                            candidateId: '1',
                            candidateName: 'Juan Pérez',
                            candidateDepartment: 'Desarrollo',
                            assignedDate: '2025-01-01'
                        },
                        {
                            candidateId: '2',
                            candidateName: 'María García',
                            candidateDepartment: 'Marketing',
                            assignedDate: '2025-01-02'
                        }
                    ];
                    setAssignedCandidates(mockAssignedCandidates);
                }

                // Cargar entrevistas programadas desde localStorage
                const savedInterviews = localStorage.getItem('scheduledInterviews');
                if (savedInterviews) {
                    dispatchInterview({ type: 'LOAD_INTERVIEWS', payload: JSON.parse(savedInterviews) });
                }

            } catch (error) {
                console.error('Error al cargar el dashboard de reclutador:', error);
            } finally {
                setIsLoading(false);
            }
        };

        if (recruiterId) {
            loadDashboardData();
        }
    }, [recruiterId, user]);

    // Funciones para gestión de candidatos
    const handleStatusChange = async (candidateId: string, newStatus: string, notes: string) => {
        try {
            setStatusMsg('Actualizando estado del candidato...');

            // Buscar el candidato
            const candidate = assignedCandidates.find(c => c.candidateId === candidateId);
            if (!candidate) {
                setStatusMsg('Candidato no encontrado');
                return;
            }

            // Obtener datos del reclutador actual
            const recruiterName = user?.name || 'Reclutador';
            const recruiterEmail = user?.email || 'recruiter@bubblegum-agency.com';

            // Enviar notificación por email al candidato
            const emailResult = await sendCandidateStatusUpdateNotification(
                candidate.email || `candidate${candidateId}@example.com`, // Email del candidato
                candidate.candidateName,
                'Under Review', // Estado anterior
                newStatus,
                candidate.candidateDepartment || 'Posición no especificada',
                recruiterName,
                recruiterEmail,
                notes
            );

            if (emailResult.success) {
                toast({
                    title: "Estado actualizado",
                    description: `Se ha notificado a ${candidate.candidateName} sobre el cambio de estado.`,
                    duration: 5000
                });
                setStatusMsg('Estado actualizado y candidato notificado');
            } else {
                toast({
                    title: "Estado actualizado",
                    description: `Estado cambiado, pero hubo un problema con la notificación.`,
                    variant: "destructive",
                    duration: 5000
                });
                setStatusMsg('Estado actualizado, problema con notificación');
            }

            // Limpiar formulario
            setStatusForm({ estado: '', notas: '' });

        } catch (error) {
            console.error('Error al actualizar estado:', error);
            setStatusMsg('Error al actualizar estado del candidato');
        }

        setTimeout(() => setStatusMsg(''), 5000);
    };

    // Funciones para gestión de entrevistas
    const handleScheduleInterview = async (e: React.FormEvent) => {
        e.preventDefault();

        try {
            // Buscar datos del candidato
            const candidate = assignedCandidates.find(c => c.candidateId === interviewForm.candidateId);
            if (!candidate) return;

            // Obtener datos del reclutador actual
            const recruiterName = user?.name || 'Reclutador';
            const recruiterEmail = user?.email || 'recruiter@bubblegum-agency.com';

            // Crear nueva entrevista
            const newInterview: Interview = {
                id: `interview-${Date.now()}`,
                candidateId: interviewForm.candidateId,
                recruiterId: recruiterId,
                candidate: {
                    id: candidate.candidateId,
                    name: candidate.candidateName,
                    email: candidate.email || `candidate${candidate.candidateId}@example.com`,
                    department: candidate.candidateDepartment
                } as Candidate,
                recruiterName,
                recruiterEmail,
                date: interviewForm.date,
                time: interviewForm.time,
                duration: Number(interviewForm.duration),
                location: interviewForm.location,
                type: interviewForm.type,
                status: 'scheduled',
                notes: interviewForm.notes,
                meetingLink: interviewForm.meetingLink
            };

            // Actualizar estado local usando reducer
            dispatchInterview({ type: 'ADD_INTERVIEW', payload: newInterview });

            // Enviar notificación al candidato
            const emailResult = await sendCandidateStatusUpdateNotification(
                newInterview.candidate.email,
                newInterview.candidate.name,
                'Under Review',
                'Interview Scheduled',
                candidate.candidateDepartment || 'Posición no especificada',
                recruiterName,
                recruiterEmail,
                `Se ha programado una entrevista para el día ${interviewForm.date} a las ${interviewForm.time}. ${interviewForm.notes}`
            );

            if (emailResult.success) {
                toast({
                    title: "Entrevista programada",
                    description: `Se ha notificado a ${candidate.candidateName} sobre la entrevista.`,
                    duration: 5000
                });
            }

            // Reiniciar formulario
            setInterviewForm({
                candidateId: '',
                date: '',
                time: '',
                duration: 60,
                location: '',
                type: 'virtual',
                notes: '',
                meetingLink: ''
            });
            setShowScheduleForm(false);

        } catch (error) {
            console.error('Error al programar entrevista:', error);
            toast({
                title: "Error",
                description: "Hubo un problema al programar la entrevista.",
                variant: "destructive",
                duration: 5000
            });
        }
    };

    const handleCancelInterview = (interviewId: string) => {
        dispatchInterview({ type: 'CANCEL_INTERVIEW', payload: interviewId });

        toast({
            title: "Entrevista cancelada",
            description: "La entrevista ha sido cancelada.",
            duration: 3000
        });
    };

    // Función para filtrar candidatos con useMemo para optimización
    const filteredCandidates = useMemo(() => {
        return assignedCandidates.filter(candidate => {
            const matchesSearch = !searchTerm ||
                candidate.candidateName.toLowerCase().includes(searchTerm.toLowerCase());
            const matchesStatus = !statusFilter ||
                (candidate.status || 'Under Review') === statusFilter;
            const matchesDepartment = !departmentFilter ||
                candidate.candidateDepartment === departmentFilter;

            return matchesSearch && matchesStatus && matchesDepartment;
        });
    }, [assignedCandidates, searchTerm, statusFilter, departmentFilter]);    // Callbacks memoizados para optimización
    const handleScheduleInterviewCallback = React.useCallback((candidateId: string) => {
        setInterviewForm(prev => ({ ...prev, candidateId }));
        setShowScheduleForm(true);
        setActiveTab('interviews');
    }, []);

    const clearFiltersCallback = React.useCallback(() => {
        setSearchTerm('');
        setStatusFilter('');
        setDepartmentFilter('');
    }, []);

    if (isLoading) {
        return (
            <div className="min-h-screen bg-gray-50 p-6">
                <div className="container mx-auto">
                    <div className="text-center space-y-6 mt-20">
                        {/* Logo/Icon animado */}
                        <div className="flex justify-center">
                            <div className="relative">
                                <div className="animate-spin rounded-full h-16 w-16 border-4 border-[#FF4785] border-t-transparent"></div>
                                <div className="absolute inset-0 flex items-center justify-center">
                                    <span className="text-[#FF4785] font-bold text-sm">BT</span>
                                </div>
                            </div>
                        </div>

                        {/* Mensaje de carga */}
                        <div className="space-y-3">
                            <h2 className="text-xl font-semibold text-[#2F2F2F]">Preparando tu Dashboard</h2>
                            <p className="text-gray-600">Cargando candidatos asignados y entrevistas programadas...</p>
                        </div>

                        {/* Barra de progreso */}
                        <div className="max-w-md mx-auto">
                            <div className="w-full bg-gray-200 rounded-full h-2">
                                <div className="bg-gradient-to-r from-[#FF4785] to-[#FF3575] h-2 rounded-full animate-pulse" style={{ width: '70%' }}></div>
                            </div>
                            <p className="text-xs text-gray-500 mt-2">Esto puede tomar unos segundos...</p>
                        </div>
                    </div>
                </div>
            </div>
        );
    }

    return (
        <section className="py-8">
            <div className="container mx-auto px-4">
                {/* Breadcrumbs Navigation */}
                <nav className="flex items-center space-x-2 text-sm text-gray-600 mb-4" aria-label="Breadcrumb">
                    <span className="text-[#FF4785] font-medium">Dashboard</span>
                    <span>/</span>
                    <span className="capitalize font-medium">
                        {activeTab === 'candidates' ? 'Candidatos Asignados' : 'Gestión de Entrevistas'}
                    </span>
                </nav>

                {/* Header principal - estilo MVP con mejoras responsive */}
                <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center bg-[#FF4785] rounded-md p-4 lg:p-5 font-poppins mb-8">
                    <div className="mb-4 lg:mb-0">
                        <h1 className="text-xl md:text-2xl font-bold text-[#2F2F2F]">Recruiter Dashboard</h1>
                        <p className="text-white text-sm md:text-base">Gestiona tus candidatos y entrevistas</p>
                    </div>

                    {/* Navegación responsive */}
                    <div className="flex flex-col sm:flex-row gap-2 w-full lg:w-auto">
                        <Button
                            className={`flex-1 sm:flex-initial ${activeTab === 'candidates' ? 'bg-[#2F2F2F] text-white' : 'bg-white text-[#FF4785]'} transition-colors`}
                            onClick={() => setActiveTab('candidates')}
                        >
                            <span className="mr-2">👥</span>
                            <span className="hidden sm:inline">Candidatos Asignados</span>
                            <span className="sm:hidden">Candidatos</span>
                        </Button>
                        <Button
                            className={`flex-1 sm:flex-initial ${activeTab === 'interviews' ? 'bg-[#2F2F2F] text-white' : 'bg-white text-[#FF4785]'} transition-colors`}
                            onClick={() => setActiveTab('interviews')}
                        >
                            <span className="mr-2">📅</span>
                            <span className="hidden sm:inline">Entrevistas</span>
                            <span className="sm:hidden">Entrevistas</span>
                        </Button>
                    </div>
                </div>

                {/* Contenido principal */}
                <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
                    <TabsList className="hidden" />

                    {/* Tab: Candidatos Asignados */}
                    <TabsContent value="candidates" className="space-y-6">
                        {/* Filtros y Búsqueda */}
                        <CandidateFilters />

                        <Card>
                            <CardHeader>
                                <div className="flex justify-between items-center">
                                    <CardTitle className="text-[#FF4785]">
                                        Candidatos Asignados
                                        {filteredCandidates.length !== assignedCandidates.length && (
                                            <span className="text-sm text-gray-500 font-normal ml-2">
                                                ({filteredCandidates.length} de {assignedCandidates.length})
                                            </span>
                                        )}
                                    </CardTitle>
                                </div>
                            </CardHeader>
                            <CardContent>
                                {assignedCandidates.length === 0 ? (
                                    <div className="text-center py-16">
                                        <div className="max-w-sm mx-auto">
                                            <div className="text-6xl mb-4">👥</div>
                                            <h3 className="text-xl font-semibold text-gray-700 mb-2">No hay candidatos asignados</h3>
                                            <p className="text-gray-500 mb-4">Cuando HR te asigne candidatos, aparecerán aquí para tu gestión.</p>
                                            <div className="text-sm text-gray-400">
                                                💡 Tip: Puedes contactar a HR para recibir nuevas asignaciones
                                            </div>
                                        </div>
                                    </div>
                                ) : filteredCandidates.length === 0 ? (
                                    <div className="text-center py-16">
                                        <div className="max-w-sm mx-auto">
                                            <div className="text-6xl mb-4">🔍</div>
                                            <h3 className="text-xl font-semibold text-gray-700 mb-2">No se encontraron candidatos</h3>
                                            <p className="text-gray-500 mb-4">Intenta ajustar los filtros para encontrar lo que buscas.</p>
                                            <Button
                                                variant="outline"
                                                onClick={clearFiltersCallback}
                                            >
                                                ✕ Limpiar filtros
                                            </Button>
                                        </div>
                                    </div>
                                ) : (
                                    <div className="space-y-4">
                                        {filteredCandidates.map((candidate) => (
                                            <CandidateCard key={candidate.candidateId} candidate={candidate} />
                                        ))}
                                    </div>
                                )}
                            </CardContent>
                        </Card>

                        {/* Formulario de cambio de estado */}
                        <Card id="status-change-section">
                            <CardHeader>
                                <CardTitle className="text-[#FF4785]">Cambiar Estado del Candidato</CardTitle>
                            </CardHeader>
                            <CardContent>
                                <form onSubmit={(e) => {
                                    e.preventDefault();
                                    if (selectedCandidate && statusForm.estado) {
                                        handleStatusChange(selectedCandidate.id, statusForm.estado, statusForm.notas);
                                    }
                                }} className="space-y-4">
                                    <div>
                                        <label className="block mb-2 font-semibold text-[#FF4785]">Candidato:</label>
                                        <select
                                            value={selectedCandidate?.id || ''}
                                            onChange={(e) => {
                                                const candidate = assignedCandidates.find(c => c.candidateId === e.target.value);
                                                setSelectedCandidate(candidate ? {
                                                    id: candidate.candidateId,
                                                    name: candidate.candidateName,
                                                    email: candidate.email || `candidate${candidate.candidateId}@example.com`
                                                } as Candidate : null);
                                            }}
                                            className="border rounded px-3 py-2 w-full"
                                            required
                                        >
                                            <option value="">Seleccionar candidato</option>
                                            {assignedCandidates.map(candidate => (
                                                <option key={candidate.candidateId} value={candidate.candidateId}>
                                                    {candidate.candidateName}
                                                </option>
                                            ))}
                                        </select>
                                    </div>

                                    <div>
                                        <label className="block mb-2 font-semibold text-[#FF4785]">Nuevo Estado:</label>
                                        <select
                                            value={statusForm.estado}
                                            onChange={(e) => setStatusForm(prev => ({ ...prev, estado: e.target.value }))}
                                            className="border rounded px-3 py-2 w-full"
                                            required
                                        >
                                            <option value="">Seleccionar estado</option>
                                            <option value="Under Review">En revisión</option>
                                            <option value="Interview">Entrevista</option>
                                            <option value="Technical Test">Prueba técnica</option>
                                            <option value="Second Interview">Segunda entrevista</option>
                                            <option value="Final Interview">Entrevista final</option>
                                            <option value="Reference Check">Verificación de referencias</option>
                                            <option value="Offer Extended">Oferta extendida</option>
                                            <option value="Offer Accepted">Oferta aceptada</option>
                                            <option value="Offer Declined">Oferta rechazada</option>
                                            <option value="Rejected">No seleccionado</option>
                                            <option value="On Hold">En espera</option>
                                            <option value="Withdrawn">Candidato retirado</option>
                                        </select>
                                    </div>

                                    <div>
                                        <label className="block mb-2 font-semibold text-[#FF4785]">Notas del reclutador:</label>
                                        <textarea
                                            value={statusForm.notas}
                                            onChange={(e) => setStatusForm(prev => ({ ...prev, notas: e.target.value }))}
                                            className="border rounded px-3 py-2 w-full h-32"
                                            placeholder="Añade aquí tus observaciones sobre el candidato..."
                                        />
                                    </div>

                                    <div className="flex gap-3">
                                        <Button
                                            type="submit"
                                            className="bg-[#FF4785] hover:bg-[#FF3575]"
                                        >
                                            Actualizar Estado
                                        </Button>
                                    </div>

                                    {statusMsg && (
                                        <div className="mt-4 p-2 bg-green-100 text-green-800 rounded-md text-center">
                                            {statusMsg}
                                        </div>
                                    )}
                                </form>

                                {/* StatusChangeForm del MVP */}
                                <div className="mt-8">
                                    <StatusChangeForm />
                                </div>
                            </CardContent>
                        </Card>
                    </TabsContent>

                    {/* Tab: Entrevistas */}
                    <TabsContent value="interviews" className="space-y-6">
                        <Card>
                            <CardHeader className="flex flex-row justify-between items-center">
                                <CardTitle className="text-[#FF4785]">Entrevistas Programadas</CardTitle>
                                <Button
                                    className="bg-[#FF4785] hover:bg-[#FF3575]"
                                    onClick={() => setShowScheduleForm(!showScheduleForm)}
                                >
                                    {showScheduleForm ? 'Cancelar' : 'Programar Nueva Entrevista'}
                                </Button>
                            </CardHeader>
                            <CardContent>
                                {/* Formulario de programación de entrevistas */}
                                {showScheduleForm && (
                                    <div className="mb-8 p-4 border rounded-lg">
                                        <h3 className="text-lg font-semibold mb-4 text-[#FF4785]">Programar Nueva Entrevista</h3>
                                        <form onSubmit={handleScheduleInterview} className="space-y-4">
                                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                                <div>
                                                    <label className="block mb-1 text-sm font-medium text-[#FF4785]">Candidato:</label>
                                                    <select
                                                        value={interviewForm.candidateId}
                                                        onChange={(e) => setInterviewForm(prev => ({ ...prev, candidateId: e.target.value }))}
                                                        className="w-full border rounded p-2"
                                                        required
                                                    >
                                                        <option value="">Seleccionar candidato</option>
                                                        {assignedCandidates.map(candidate => (
                                                            <option key={candidate.candidateId} value={candidate.candidateId}>
                                                                {candidate.candidateName}
                                                            </option>
                                                        ))}
                                                    </select>
                                                </div>

                                                <div>
                                                    <label className="block mb-1 text-sm font-medium text-[#FF4785]">Tipo de entrevista:</label>
                                                    <select
                                                        value={interviewForm.type}
                                                        onChange={(e) => setInterviewForm(prev => ({ ...prev, type: e.target.value as any }))}
                                                        className="w-full border rounded p-2"
                                                        required
                                                    >
                                                        <option value="virtual">Virtual</option>
                                                        <option value="presencial">Presencial</option>
                                                        <option value="telefónica">Telefónica</option>
                                                    </select>
                                                </div>

                                                <div>
                                                    <label className="block mb-1 text-sm font-medium text-[#FF4785]">Fecha:</label>
                                                    <input
                                                        type="date"
                                                        value={interviewForm.date}
                                                        onChange={(e) => setInterviewForm(prev => ({ ...prev, date: e.target.value }))}
                                                        className="w-full border rounded p-2"
                                                        required
                                                    />
                                                </div>

                                                <div>
                                                    <label className="block mb-1 text-sm font-medium text-[#FF4785]">Hora:</label>
                                                    <input
                                                        type="time"
                                                        value={interviewForm.time}
                                                        onChange={(e) => setInterviewForm(prev => ({ ...prev, time: e.target.value }))}
                                                        className="w-full border rounded p-2"
                                                        required
                                                    />
                                                </div>

                                                <div>
                                                    <label className="block mb-1 text-sm font-medium text-[#FF4785]">Duración (minutos):</label>
                                                    <input
                                                        type="number"
                                                        value={interviewForm.duration}
                                                        onChange={(e) => setInterviewForm(prev => ({ ...prev, duration: parseInt(e.target.value) }))}
                                                        className="w-full border rounded p-2"
                                                        min="15"
                                                        max="240"
                                                        required
                                                    />
                                                </div>

                                                <div>
                                                    <label className="block mb-1 text-sm font-medium text-[#FF4785]">Ubicación/Enlace:</label>
                                                    <input
                                                        type="text"
                                                        value={interviewForm.location}
                                                        onChange={(e) => setInterviewForm(prev => ({ ...prev, location: e.target.value }))}
                                                        className="w-full border rounded p-2"
                                                        placeholder="Sala de reuniones o enlace de videollamada"
                                                        required
                                                    />
                                                </div>
                                            </div>

                                            <div>
                                                <label className="block mb-1 text-sm font-medium text-[#FF4785]">Notas adicionales:</label>
                                                <textarea
                                                    value={interviewForm.notes}
                                                    onChange={(e) => setInterviewForm(prev => ({ ...prev, notes: e.target.value }))}
                                                    className="w-full border rounded p-2 h-20"
                                                    placeholder="Instrucciones o información adicional para el candidato..."
                                                />
                                            </div>

                                            <div className="flex gap-3">
                                                <Button
                                                    type="submit"
                                                    className="bg-[#FF4785] hover:bg-[#FF3575]"
                                                >
                                                    Programar Entrevista
                                                </Button>
                                                <Button
                                                    type="button"
                                                    variant="outline"
                                                    onClick={() => setShowScheduleForm(false)}
                                                >
                                                    Cancelar
                                                </Button>
                                            </div>
                                        </form>
                                    </div>
                                )}

                                {/* Lista de entrevistas programadas */}
                                {interviewState.interviews.length === 0 && !showScheduleForm ? (
                                    <div className="text-center py-16">
                                        <div className="max-w-sm mx-auto">
                                            <div className="text-6xl mb-4">📅</div>
                                            <h3 className="text-xl font-semibold text-gray-700 mb-2">No hay entrevistas programadas</h3>
                                            <p className="text-gray-500 mb-4">Programa tu primera entrevista usando el botón de arriba.</p>
                                            <Button
                                                className="bg-[#FF4785] hover:bg-[#FF3575] text-white"
                                                onClick={() => setShowScheduleForm(true)}
                                            >
                                                📅 Programar Primera Entrevista
                                            </Button>
                                        </div>
                                    </div>
                                ) : (
                                    <div className="space-y-4">
                                        {interviewState.interviews.map((interview) => (
                                            <Card key={interview.id} className="border hover:shadow-md transition-shadow">
                                                <CardContent className="p-4">
                                                    <div className="flex justify-between items-start">
                                                        <div className="flex-1">
                                                            <div className="flex items-center gap-3 mb-3">
                                                                <h3 className="font-semibold text-lg text-[#2F2F2F]">{interview.candidate.name}</h3>
                                                                <StatusBadge status={interview.status === 'scheduled' ? 'Interview Scheduled' : interview.status} />
                                                            </div>

                                                            <div className="grid grid-cols-1 md:grid-cols-2 gap-2 text-sm">
                                                                <p className="text-gray-600 flex items-center gap-2">
                                                                    <span className="text-[#FF4785]">📅</span>
                                                                    <span className="font-medium">{interview.date}</span> a las <span className="font-medium">{interview.time}</span>
                                                                </p>
                                                                <p className="text-gray-600 flex items-center gap-2">
                                                                    <span className="text-[#FF4785]">📍</span>
                                                                    <span className="capitalize">{interview.type}</span> - {interview.location}
                                                                </p>
                                                                <p className="text-gray-600 flex items-center gap-2">
                                                                    <span className="text-[#FF4785]">⏱️</span>
                                                                    Duración: <span className="font-medium">{interview.duration} minutos</span>
                                                                </p>
                                                                {interview.meetingLink && (
                                                                    <p className="text-gray-600 flex items-center gap-2">
                                                                        <span className="text-[#FF4785]">�</span>
                                                                        <a href={interview.meetingLink} target="_blank" rel="noopener noreferrer"
                                                                            className="text-blue-600 hover:text-blue-800 underline">
                                                                            Enlace de reunión
                                                                        </a>
                                                                    </p>
                                                                )}
                                                            </div>

                                                            {interview.notes && (
                                                                <div className="mt-3 p-2 bg-gray-50 rounded text-sm">
                                                                    <span className="text-[#FF4785] font-medium">📝 Notas:</span>
                                                                    <p className="text-gray-700 mt-1">{interview.notes}</p>
                                                                </div>
                                                            )}
                                                        </div>
                                                        <div className="flex gap-2 ml-4">
                                                            {interview.status === 'scheduled' && (
                                                                <Button
                                                                    size="sm"
                                                                    variant="outline"
                                                                    className="text-red-600 border-red-200 hover:bg-red-50"
                                                                    onClick={() => handleCancelInterview(interview.id)}
                                                                >
                                                                    ❌ Cancelar
                                                                </Button>
                                                            )}
                                                        </div>
                                                    </div>
                                                </CardContent>
                                            </Card>
                                        ))}
                                    </div>
                                )}
                            </CardContent>
                        </Card>
                    </TabsContent>
                </Tabs>
            </div>
        </section>
    );
};

export default RecruiterDashboard;

// src/pages/dashboard/RecruiterDashboard.tsx
import React, { useState, useEffect } from 'react';
import { getRecruiterDashboardStats, getCandidates, getJobs } from '../../lib/apiService';
import { Link } from 'react-router-dom';
import { useAuth } from '../../contexts/AuthContextSimple';
import { Button } from '../../components/ui/button';
import { Tabs, TabsList, TabsTrigger, TabsContent } from '../../components/ui/tabs';
import { Card, CardHeader, CardTitle, CardContent } from '../../components/ui/card';
import { ApplicationsTable, ApplicationDetailsDialog } from '../../components/dashboard/ApplicationsTable';
import StatusChangeForm from '../../components/StatusChangeForm';
import { sendCandidateStatusUpdateNotification } from '../../lib/emailService';
import { toast } from '../../components/ui/use-toast';
import { Calendar, Users, Clock, TrendingUp, UserCheck, MessageCircle } from 'lucide-react';

interface RecruiterDashboardStats {
    assignedJobs: number;
    pendingApplications: number;
    interviewsScheduled: number;
    candidatesInProcess: number;
    conversionRate: number;
    upcomingInterviews: Array<{
        id: string;
        candidateName: string;
        jobTitle: string;
        dateTime: string;
        status: 'pending' | 'confirmed' | 'rescheduled' | 'cancelled';
    }>;
    recentApplications: Array<{
        id: string;
        candidateName: string;
        jobTitle: string;
        appliedDate: string;
        status: string;
    }>;
    applicationsByStage: Array<{
        stage: string;
        count: number;
    }>;
    activityTimeline: Array<{
        id: string;
        date: string;
        activity: string;
        candidateName?: string;
        jobTitle?: string;
    }>;
}

interface Candidate {
    id: string;
    name: string;
    email: string;
    phone?: string;
    location?: string;
    skills?: string[];
    estado?: string;
    jobPosition?: string;
    assignedCategory?: string;
    categoria?: string;
    reclutador?: string;
    emailReclutador?: string;
    department?: string;
}

interface Job {
    id: string;
    title: string;
    location?: string;
    skills?: string[];
}

interface Application {
    id: string;
    candidateId: string;
    jobId: string;
    candidate: Candidate;
    job: Job;
    appliedDate: string;
    status: string;
    score: number;
}

interface Interview {
    id: string;
    candidateId: string;
    recruiterId: string;
    candidate: Candidate;
    recruiterName: string;
    recruiterEmail: string;
    date: string;
    time: string;
    duration: number; // en minutos
    location: string;
    type: 'presencial' | 'virtual' | 'telefónica';
    status: 'scheduled' | 'completed' | 'cancelled' | 'rescheduled';
    notes?: string;
    meetingLink?: string;
}

interface RecruiterDashboardProps {
    recruiterId?: string;
}

const RecruiterDashboard: React.FC<RecruiterDashboardProps> = ({ recruiterId: propRecruiterId }) => {
    const { user } = useAuth();
    const recruiterId = propRecruiterId || user?.id || 'default-recruiter';

    const [stats, setStats] = useState<RecruiterDashboardStats | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [activeTab, setActiveTab] = useState('overview');

    // Estados para gestión de candidatos y entrevistas
    const [assignedCandidates, setAssignedCandidates] = useState<any[]>([]);
    const [applications, setApplications] = useState<Application[]>([]);
    const [interviews, setInterviews] = useState<Interview[]>([]);
    const [selectedCandidate, setSelectedCandidate] = useState<Candidate | null>(null);
    const [selectedApplication, setSelectedApplication] = useState<Application | null>(null);

    // Estados para formularios
    const [statusForm, setStatusForm] = useState({ estado: '', notas: '' });
    const [interviewForm, setInterviewForm] = useState({
        candidateId: '',
        date: '',
        time: '',
        duration: 60,
        location: '',
        type: 'virtual' as 'presencial' | 'virtual' | 'telefónica',
        notes: '',
        meetingLink: ''
    });
    const [showScheduleForm, setShowScheduleForm] = useState(false);
    const [statusMsg, setStatusMsg] = useState('');

    useEffect(() => {
        const loadDashboardData = async () => {
            try {
                setIsLoading(true);

                // Cargar estadísticas del dashboard
                const response = await getRecruiterDashboardStats(recruiterId);
                if (response.success && response.data) {
                    setStats(response.data);
                } else {
                    // Fallback con datos por defecto
                    setStats({
                        assignedJobs: 3,
                        pendingApplications: 12,
                        interviewsScheduled: 5,
                        candidatesInProcess: 18,
                        conversionRate: 65,
                        upcomingInterviews: [],
                        recentApplications: [],
                        applicationsByStage: [
                            { stage: 'Received', count: 8 },
                            { stage: 'Under Review', count: 5 },
                            { stage: 'Interview', count: 3 },
                            { stage: 'Hired', count: 2 }
                        ],
                        activityTimeline: []
                    });
                }

                // Cargar candidatos asignados (simulado)
                const recruiterEmail = user?.email || localStorage.getItem('userEmail');
                if (recruiterEmail) {
                    // Aquí normalmente cargarías desde la API
                    // Por ahora usamos datos mock
                    const mockAssignedCandidates = [
                        {
                            candidateId: '1',
                            candidateName: 'Juan Pérez',
                            candidateDepartment: 'Desarrollo',
                            assignedDate: '2025-01-01'
                        },
                        {
                            candidateId: '2',
                            candidateName: 'María García',
                            candidateDepartment: 'Marketing',
                            assignedDate: '2025-01-02'
                        }
                    ];
                    setAssignedCandidates(mockAssignedCandidates);
                }

                // Cargar entrevistas programadas desde localStorage
                const savedInterviews = localStorage.getItem('scheduledInterviews');
                if (savedInterviews) {
                    setInterviews(JSON.parse(savedInterviews));
                }

            } catch (error) {
                console.error('Error al cargar el dashboard de reclutador:', error);
                setError('Error de conexión, intenta más tarde');
            } finally {
                setIsLoading(false);
            }
        };

        if (recruiterId) {
            loadDashboardData();
        }
    }, [recruiterId, user]);

    // Funciones para gestión de candidatos
    const handleStatusChange = async (candidateId: string, newStatus: string, notes: string) => {
        try {
            setStatusMsg('Actualizando estado del candidato...');

            // Buscar el candidato
            const candidate = assignedCandidates.find(c => c.candidateId === candidateId);
            if (!candidate) {
                setStatusMsg('Candidato no encontrado');
                return;
            }

            // Obtener datos del reclutador actual
            const recruiterName = user?.name || 'Reclutador';
            const recruiterEmail = user?.email || 'recruiter@bubblegum-agency.com';

            // Enviar notificación por email al candidato
            const emailResult = await sendCandidateStatusUpdateNotification(
                `candidate${candidateId}@example.com`, // Email del candidato
                candidate.candidateName,
                'Under Review', // Estado anterior
                newStatus,
                candidate.candidateDepartment || 'Posición no especificada',
                recruiterName,
                recruiterEmail,
                notes
            );

            if (emailResult.success) {
                toast({
                    title: "Estado actualizado",
                    description: `Se ha notificado a ${candidate.candidateName} sobre el cambio de estado.`,
                    duration: 5000
                });
                setStatusMsg('Estado actualizado y candidato notificado');
            } else {
                toast({
                    title: "Estado actualizado",
                    description: `Estado cambiado, pero hubo un problema con la notificación.`,
                    variant: "destructive",
                    duration: 5000
                });
                setStatusMsg('Estado actualizado, problema con notificación');
            }

            // Limpiar formulario
            setStatusForm({ estado: '', notas: '' });

        } catch (error) {
            console.error('Error al actualizar estado:', error);
            setStatusMsg('Error al actualizar estado del candidato');
        }

        setTimeout(() => setStatusMsg(''), 5000);
    };

    // Funciones para gestión de entrevistas
    const handleScheduleInterview = async (e: React.FormEvent) => {
        e.preventDefault();

        try {
            // Buscar datos del candidato
            const candidate = assignedCandidates.find(c => c.candidateId === interviewForm.candidateId);
            if (!candidate) return;

            // Obtener datos del reclutador actual
            const recruiterName = user?.name || 'Reclutador';
            const recruiterEmail = user?.email || 'recruiter@bubblegum-agency.com';

            // Crear nueva entrevista
            const newInterview: Interview = {
                id: `interview-${Date.now()}`,
                candidateId: interviewForm.candidateId,
                recruiterId: recruiterId,
                candidate: {
                    id: candidate.candidateId,
                    name: candidate.candidateName,
                    email: `candidate${candidate.candidateId}@example.com`,
                    department: candidate.candidateDepartment
                } as Candidate,
                recruiterName,
                recruiterEmail,
                date: interviewForm.date,
                time: interviewForm.time,
                duration: Number(interviewForm.duration),
                location: interviewForm.location,
                type: interviewForm.type,
                status: 'scheduled',
                notes: interviewForm.notes,
                meetingLink: interviewForm.meetingLink
            };

            // Actualizar estado local
            const updatedInterviews = [...interviews, newInterview];
            setInterviews(updatedInterviews);

            // Guardar en localStorage
            localStorage.setItem('scheduledInterviews', JSON.stringify(updatedInterviews));

            // Enviar notificación al candidato
            const emailResult = await sendCandidateStatusUpdateNotification(
                newInterview.candidate.email,
                newInterview.candidate.name,
                'Under Review',
                'Interview Scheduled',
                candidate.candidateDepartment || 'Posición no especificada',
                recruiterName,
                recruiterEmail,
                `Se ha programado una entrevista para el día ${interviewForm.date} a las ${interviewForm.time}. ${interviewForm.notes}`
            );

            if (emailResult.success) {
                toast({
                    title: "Entrevista programada",
                    description: `Se ha notificado a ${candidate.candidateName} sobre la entrevista.`,
                    duration: 5000
                });
            }

            // Reiniciar formulario
            setInterviewForm({
                candidateId: '',
                date: '',
                time: '',
                duration: 60,
                location: '',
                type: 'virtual',
                notes: '',
                meetingLink: ''
            });
            setShowScheduleForm(false);

        } catch (error) {
            console.error('Error al programar entrevista:', error);
            toast({
                title: "Error",
                description: "Hubo un problema al programar la entrevista.",
                variant: "destructive",
                duration: 5000
            });
        }
    };

    const handleCancelInterview = (interviewId: string) => {
        const updatedInterviews = interviews.map(interview =>
            interview.id === interviewId
                ? { ...interview, status: 'cancelled' as const }
                : interview
        );

        setInterviews(updatedInterviews);
        localStorage.setItem('scheduledInterviews', JSON.stringify(updatedInterviews));

        toast({
            title: "Entrevista cancelada",
            description: "La entrevista ha sido cancelada.",
            duration: 3000
        });
    };

    if (isLoading) {
        return (
            <div className="min-h-screen bg-gray-50 p-6">
                <div className="text-center">Cargando dashboard...</div>
            </div>
        );
    }

    if (error || !stats) {
        return (
            <div className="min-h-screen bg-gray-50 p-6">
                <div className="bg-red-50 p-4 rounded-md text-red-600 mb-4">
                    {error || 'No se pudieron cargar los datos del dashboard'}
                </div>
                <button
                    onClick={() => window.location.reload()}
                    className="px-4 py-2 bg-[#F24495] text-white rounded-md shadow-sm"
                >
                    Reintentar
                </button>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-gray-50 p-6">
            <h1 className="text-2xl font-bold text-gray-900 mb-6">Dashboard de Reclutador</h1>

            {/* Tarjetas de resumen */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
                <div className="bg-white p-6 rounded-lg shadow-sm">
                    <div className="flex items-center justify-between">
                        <div>
                            <p className="text-sm font-medium text-gray-500">Vacantes Asignadas</p>
                            <p className="text-2xl font-semibold text-gray-900">{stats.assignedJobs}</p>
                        </div>
                        <div className="p-3 bg-blue-50 rounded-full">
                            <svg className="w-6 h-6 text-blue-500" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 13.255A23.931 23.931 0 0112 15c-3.183 0-6.22-.62-9-1.745M16 6V4a2 2 0 00-2-2h-4a2 2 0 00-2 2v2m4 6h.01M5 20h14a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" />
                            </svg>
                        </div>
                    </div>
                    <div className="mt-4">
                        <Link to="/recruiter/jobs" className="text-sm text-[#F24495] hover:underline">
                            Ver mis vacantes →
                        </Link>
                    </div>
                </div>

                <div className="bg-white p-6 rounded-lg shadow-sm">
                    <div className="flex items-center justify-between">
                        <div>
                            <p className="text-sm font-medium text-gray-500">Postulaciones Pendientes</p>
                            <p className="text-2xl font-semibold text-gray-900">{stats.pendingApplications}</p>
                        </div>
                        <div className="p-3 bg-yellow-50 rounded-full">
                            <svg className="w-6 h-6 text-yellow-500" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" />
                            </svg>
                        </div>
                    </div>
                    <div className="mt-4">
                        <Link to="/recruiter/applications" className="text-sm text-[#F24495] hover:underline">
                            Revisar postulaciones →
                        </Link>
                    </div>
                </div>

                <div className="bg-white p-6 rounded-lg shadow-sm">
                    <div className="flex items-center justify-between">
                        <div>
                            <p className="text-sm font-medium text-gray-500">Entrevistas Programadas</p>
                            <p className="text-2xl font-semibold text-gray-900">{stats.interviewsScheduled}</p>
                        </div>
                        <div className="p-3 bg-purple-50 rounded-full">
                            <svg className="w-6 h-6 text-purple-500" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" />
                            </svg>
                        </div>
                    </div>
                    <div className="mt-4">
                        <Link to="/recruiter/calendar" className="text-sm text-[#F24495] hover:underline">
                            Ver mi calendario →
                        </Link>
                    </div>
                </div>

                <div className="bg-white p-6 rounded-lg shadow-sm">
                    <div className="flex items-center justify-between">
                        <div>
                            <p className="text-sm font-medium text-gray-500">Candidatos en Proceso</p>
                            <p className="text-2xl font-semibold text-gray-900">{stats.candidatesInProcess}</p>
                        </div>
                        <div className="p-3 bg-green-50 rounded-full">
                            <svg className="w-6 h-6 text-green-500" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0z" />
                            </svg>
                        </div>
                    </div>
                    <div className="mt-4">
                        <Link to="/recruiter/candidates" className="text-sm text-[#F24495] hover:underline">
                            Ver todos los candidatos →
                        </Link>
                    </div>
                </div>
            </div>

            {/* Tasa de conversión */}
            <div className="bg-white p-6 rounded-lg shadow-sm mb-8">
                <h3 className="text-lg font-medium text-gray-900 mb-4">Tasa de conversión</h3>
                <div className="flex items-end mb-4">
                    <p className="text-3xl font-bold text-[#F24495]">{stats.conversionRate}%</p>
                    <p className="ml-2 text-sm text-gray-500">este mes</p>
                </div>
                <div className="w-full bg-gray-200 rounded-full h-2.5">
                    <div
                        className="bg-[#F24495] h-2.5 rounded-full"
                        style={{ width: `${stats.conversionRate}%` }}
                    ></div>
                </div>
                <p className="mt-2 text-sm text-gray-600">
                    Porcentaje de candidatos que pasan a la siguiente etapa del proceso
                </p>
            </div>

            {/* Próximas entrevistas y postulaciones recientes */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
                <div className="bg-white p-6 rounded-lg shadow-sm">
                    <h3 className="text-lg font-medium text-gray-900 mb-4">Próximas Entrevistas</h3>
                    <div className="space-y-4">
                        {stats.upcomingInterviews.length > 0 ? (
                            stats.upcomingInterviews.map(interview => (
                                <div key={interview.id} className="p-3 bg-gray-50 rounded-md">
                                    <div className="flex justify-between items-start">
                                        <div>
                                            <p className="text-sm font-medium text-gray-900">{interview.candidateName}</p>
                                            <p className="text-xs text-gray-500">{interview.jobTitle}</p>
                                        </div>
                                        <div className={`px-2 py-1 rounded-full text-xs font-medium ${interview.status === 'confirmed' ? 'bg-green-100 text-green-800' :
                                            interview.status === 'pending' ? 'bg-yellow-100 text-yellow-800' :
                                                interview.status === 'rescheduled' ? 'bg-blue-100 text-blue-800' :
                                                    'bg-red-100 text-red-800'
                                            }`}>
                                            {interview.status === 'confirmed' ? 'Confirmada' :
                                                interview.status === 'pending' ? 'Pendiente' :
                                                    interview.status === 'rescheduled' ? 'Reprogramada' :
                                                        'Cancelada'
                                            }
                                        </div>
                                    </div>
                                    <div className="mt-2 flex items-center">
                                        <svg className="w-4 h-4 text-gray-400 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
                                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                                        </svg>
                                        <p className="text-xs text-gray-600">
                                            {new Date(interview.dateTime).toLocaleString()}
                                        </p>
                                    </div>
                                </div>
                            ))
                        ) : (
                            <p className="text-sm text-gray-500">No hay entrevistas próximas programadas</p>
                        )}
                    </div>
                    <div className="mt-4">
                        <Link to="/recruiter/interviews" className="text-sm text-[#F24495] hover:underline">
                            Ver todas las entrevistas →
                        </Link>
                    </div>
                </div>

                <div className="bg-white p-6 rounded-lg shadow-sm">
                    <h3 className="text-lg font-medium text-gray-900 mb-4">Postulaciones Recientes</h3>
                    <div className="space-y-4">
                        {stats.recentApplications.length > 0 ? (
                            stats.recentApplications.map(application => (
                                <div key={application.id} className="p-3 border-l-2 border-[#F24495] bg-gray-50 rounded-r-md">
                                    <div className="flex justify-between items-start">
                                        <div>
                                            <p className="text-sm font-medium text-gray-900">{application.candidateName}</p>
                                            <p className="text-xs text-gray-500">{application.jobTitle}</p>
                                        </div>
                                        <p className="text-xs text-gray-400">
                                            {new Date(application.appliedDate).toLocaleDateString()}
                                        </p>
                                    </div>
                                    <div className="mt-2">
                                        <span className="px-2 py-1 bg-gray-100 text-gray-800 text-xs rounded-full">
                                            {application.status}
                                        </span>
                                    </div>
                                </div>
                            ))
                        ) : (
                            <p className="text-sm text-gray-500">No hay postulaciones recientes</p>
                        )}
                    </div>
                    <div className="mt-4">
                        <Link to="/recruiter/applications" className="text-sm text-[#F24495] hover:underline">
                            Ver todas las postulaciones →
                        </Link>
                    </div>
                </div>
            </div>

            {/* Aplicaciones por etapa y línea de tiempo */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="bg-white p-6 rounded-lg shadow-sm">
                    <h3 className="text-lg font-medium text-gray-900 mb-4">Postulaciones por Etapa</h3>
                    <div className="grid grid-cols-2 gap-4">
                        {stats.applicationsByStage.map(item => (
                            <div key={item.stage} className="p-4 bg-gray-50 rounded-md text-center">
                                <p className="text-xl font-semibold text-gray-900">{item.count}</p>
                                <p className="text-sm text-gray-600 mt-1">{item.stage}</p>
                            </div>
                        ))}
                    </div>
                </div>

                <div className="bg-white p-6 rounded-lg shadow-sm">
                    <h3 className="text-lg font-medium text-gray-900 mb-4">Actividad Reciente</h3>
                    <div className="space-y-6 relative before:absolute before:inset-0 before:ml-5 before:-translate-x-px md:before:mx-auto md:before:translate-x-0 before:h-full before:w-0.5 before:bg-gradient-to-b before:from-transparent before:via-gray-300 before:to-transparent">
                        {stats.activityTimeline.map((activity, index) => (
                            <div key={activity.id} className="relative flex items-center justify-between md:justify-normal md:odd:flex-row-reverse group">
                                <div className="flex items-center justify-center w-10 h-10 rounded-full border border-white bg-[#F24495] text-white shadow shrink-0 md:order-1 md:group-odd:-translate-x-1/2 md:group-even:translate-x-1/2">
                                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
                                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                                    </svg>
                                </div>
                                <div className="w-[calc(100%-4rem)] md:w-[calc(50%-2.5rem)] p-3 bg-gray-50 rounded-md shadow-sm">
                                    <div className="font-medium text-gray-900 text-sm">{activity.activity}</div>
                                    {(activity.candidateName || activity.jobTitle) && (
                                        <div className="text-xs text-gray-500 mt-1">
                                            {activity.candidateName && <span>{activity.candidateName}</span>}
                                            {activity.candidateName && activity.jobTitle && <span> - </span>}
                                            {activity.jobTitle && <span>{activity.jobTitle}</span>}
                                        </div>
                                    )}
                                    <div className="text-xs text-gray-400 mt-1">
                                        {new Date(activity.date).toLocaleString()}
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default RecruiterDashboard;

/**
 * Production-Ready Apply Page - Refactored to use JobApplicationForm
 * 
 * Enhanced job application page with extracted form component,
 * accessibility, validation, error handling, and security features.
 * 
 * @package Jobs
 * @author Bubble Talents Development Team
 * @version 3.0.0
 * @since 2025-01-05
 */

import React, { useState, useCallback, useEffect } from 'react';
import { ErrorBoundary } from '../../components/ErrorBoundary';
import { JobApplicationData } from '../../components/forms/JobApplicationForm';
import { FormValidator, JobApplicationSchema } from '../../utils/validation';
import { Input } from '../../components/ui/input';
import { Textarea } from '../../components/ui/textarea';
import { Select } from '../../components/ui/select';
import { Button } from '../../components/ui/button';
import { useSkipLinks, useAnnouncer } from '../../utils/accessibility';
import { useDebounce } from '../../utils/performance';
import UploadCV from '../../components/UploadCV';

/**
 * Application status enum
 */
enum ApplicationStatus {
    IDLE = 'idle',
    SUBMITTING = 'submitting',
    SUCCESS = 'success',
    ERROR = 'error'
}

export default function ApplyPage(): JSX.Element {
    // Skip links for accessibility
    useSkipLinks();

    // Screen reader announcements
    const announce = useAnnouncer();

    // Form state
    const [formData, setFormData] = useState<JobApplicationData>({
        firstName: '',
        lastName: '',
        email: '',
        phone: '',
        location: '',
        coverLetter: '',
        salaryExpectation: '',
        availabilityDate: '',
        workPreference: 'remote',
        experience: '',
        portfolio: '',
        linkedinProfile: ''
    });

    // Form validation and UI state
    type Errors = Partial<Record<keyof JobApplicationData | 'general', string>>;
    const [errors, setErrors] = useState<Errors>({});
    const [status, setStatus] = useState<ApplicationStatus>(ApplicationStatus.IDLE);
    const [submitAttempted, setSubmitAttempted] = useState(false);
    const [successMessage, setSuccessMessage] = useState('');

    // Debounced form data for validation
    const debouncedFormData = useDebounce(formData, 300);

    // Form validator instance
    // Para evitar error de restricción, extendemos JobApplicationData con un índice string temporalmente
    type JobApplicationDataWithIndex = JobApplicationData & { [key: string]: unknown };
    const validator = new FormValidator<JobApplicationDataWithIndex>(JobApplicationSchema as any);

    // Work preference options
    const workPreferenceOptions = [
        { value: 'remote', label: 'Trabajo remoto' },
        { value: 'onsite', label: 'Trabajo presencial' },
        { value: 'hybrid', label: 'Trabajo híbrido' },
    ];

    /**
     * Validate form data and update errors
     */
    const validateForm = useCallback(async (data: JobApplicationDataWithIndex) => {
        try {
            const result = await validator.validateAll(data);
            if (!result.success) {
                const formErrors: Errors = {};
                result.errors.forEach((error) => {
                    formErrors[error.field as keyof JobApplicationData] = error.message;
                });
                setErrors(formErrors);
                return false;
            }
            setErrors({});
            return true;
        } catch (error) {
            console.error('Validation error:', error);
            setErrors({ general: 'Error de validación. Intente nuevamente.' });
            return false;
        }
    }, [validator]);

    // Validar formulario cuando cambian los datos (debounced)
    useEffect(() => {
        if (submitAttempted) {
            validateForm(debouncedFormData as JobApplicationDataWithIndex);
        }
    }, [debouncedFormData, submitAttempted, validateForm]);

    /**
     * Update form field value
     */
    const updateField = useCallback((field: keyof JobApplicationData, value: string) => {
        setFormData(prev => ({ ...prev, [field]: value }));

        // Clear field error when user starts typing
        if (errors[field]) {
            setErrors(prev => ({ ...prev, [field]: '' }));
        }
    }, [errors]);

    /**
     * Handle field blur events for immediate validation
     */
    const handleFieldBlur = useCallback(async (field: keyof JobApplicationData) => {
        if (formData[field]) {
            const error = await validator.validateField(field, formData[field]);

            if (error) {
                setErrors(prev => ({ ...prev, [field]: error }));
            } else {
                setErrors(prev => ({ ...prev, [field]: '' }));
            }
        }
    }, [formData, validator]);    /**
     * Handle CV upload success
     */
    const handleCVUploadSuccess = useCallback(() => {
        announce('CV procesado y guardado exitosamente', 'polite');
        setSuccessMessage('¡Tu CV fue procesado y guardado exitosamente!');
        setTimeout(() => setSuccessMessage(''), 5000);
    }, [announce]);

    /**
     * Submit form data
     */
    const handleSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
        event.preventDefault();
        setSubmitAttempted(true);
        setStatus(ApplicationStatus.SUBMITTING);

        try {
            // Validate form
            const isValid = await validateForm(formData as JobApplicationDataWithIndex);
            if (!isValid) {
                setStatus(ApplicationStatus.ERROR);
                announce('Por favor, corrige los errores en el formulario', 'assertive');
                return;
            }

            // Simulate API call
            await new Promise(resolve => setTimeout(resolve, 1200));

            // Success
            setStatus(ApplicationStatus.SUCCESS);
            setSuccessMessage('¡Tu postulación fue enviada exitosamente!');
            announce('Postulación enviada exitosamente', 'polite');

            // Reset form
            setFormData({
                firstName: '',
                lastName: '',
                email: '',
                phone: '',
                location: '',
                coverLetter: '',
                salaryExpectation: '',
                availabilityDate: '',
                workPreference: 'remote',
                experience: '',
                portfolio: '',
                linkedinProfile: ''
            });
            setSubmitAttempted(false);

            // Clear success message after 5 seconds
            setTimeout(() => {
                setSuccessMessage('');
                setStatus(ApplicationStatus.IDLE);
            }, 5000);

        } catch (error) {
            console.error('Error submitting application:', error);
            setStatus(ApplicationStatus.ERROR);
            setErrors({ general: 'Error al enviar la postulación. Intente nuevamente.' });
            announce('Error al enviar la postulación', 'assertive');
        }
    };

    const isSubmitting = status === ApplicationStatus.SUBMITTING;


    return (
        <ErrorBoundary>
            <div className="container mx-auto px-4 py-8 max-w-4xl">
                {/* Skip to main content target */}
                <div id="main-content" tabIndex={-1}>
                    <header className="mb-8">
                        <h1 className="text-3xl font-bold text-gray-900 mb-2">
                            Postulación a Vacante
                        </h1>
                        <p className="text-gray-600">
                            Completa tu información para postularte a esta oportunidad laboral.
                        </p>
                    </header>

                    {/* Success message */}
                    {successMessage && (
                        <div
                            className="mb-6 p-4 bg-green-50 border border-green-200 rounded-md"
                            role="alert"
                            aria-live="polite"
                        >
                            <div className="flex">
                                <div className="flex-shrink-0">
                                    <svg className="h-5 w-5 text-green-400" viewBox="0 0 20 20" fill="currentColor">
                                        <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" />
                                    </svg>
                                </div>
                                <div className="ml-3">
                                    <p className="text-green-700 font-medium">{successMessage}</p>
                                </div>
                            </div>
                        </div>
                    )}

                    {/* General error message */}
                    {errors.general && (
                        <div
                            className="mb-6 p-4 bg-red-50 border border-red-200 rounded-md"
                            role="alert"
                            aria-live="assertive"
                        >
                            <div className="flex">
                                <div className="flex-shrink-0">
                                    <svg className="h-5 w-5 text-red-400" viewBox="0 0 20 20" fill="currentColor">
                                        <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" clipRule="evenodd" />
                                    </svg>
                                </div>
                                <div className="ml-3">
                                    <p className="text-red-700 font-medium">{errors.general}</p>
                                </div>
                            </div>
                        </div>
                    )}

                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                        {/* CV Upload Section */}
                        <section className="lg:col-span-2">
                            <h2 className="text-xl font-semibold text-gray-900 mb-4">
                                Subir Curriculum Vitae
                            </h2>
                            <div className="bg-gray-50 p-6 rounded-lg">
                                <UploadCV onSuccess={handleCVUploadSuccess} />
                            </div>
                        </section>

                        {/* Application Form */}
                        <section className="lg:col-span-2">
                            <h2 className="text-xl font-semibold text-gray-900 mb-6">
                                Información de Postulación
                            </h2>

                            <form onSubmit={handleSubmit} noValidate>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                    <div className="md:col-span-2">
                                        <Textarea
                                            placeholder="Carta de Presentación"
                                            value={formData.coverLetter}
                                            onChange={e => updateField('coverLetter', e.target.value)}
                                            onBlur={() => handleFieldBlur('coverLetter')}
                                            className="w-full"
                                            rows={4}
                                            maxLength={2000}
                                        />
                                        {errors.coverLetter && <span className="text-red-600 text-sm">{errors.coverLetter}</span>}
                                    </div>
                                    <div>
                                        <Input
                                            type="text"
                                            placeholder="Pretensión Salarial (USD)"
                                            value={formData.salaryExpectation}
                                            onChange={e => updateField('salaryExpectation', e.target.value)}
                                            onBlur={() => handleFieldBlur('salaryExpectation')}
                                            className="w-full"
                                        />
                                        {errors.salaryExpectation && <span className="text-red-600 text-sm">{errors.salaryExpectation}</span>}
                                    </div>
                                    <div>
                                        <Input
                                            type="text"
                                            placeholder="Fecha de Disponibilidad"
                                            value={formData.availabilityDate}
                                            onChange={e => updateField('availabilityDate', e.target.value)}
                                            onBlur={() => handleFieldBlur('availabilityDate')}
                                            className="w-full"
                                        />
                                        {errors.availabilityDate && <span className="text-red-600 text-sm">{errors.availabilityDate}</span>}
                                    </div>
                                    <div>
                                        <Select
                                            value={formData.workPreference}
                                            onValueChange={value => updateField('workPreference', value as 'remote' | 'hybrid' | 'onsite')}
                                        >
                                            {workPreferenceOptions.map(opt => (
                                                <option key={opt.value} value={opt.value}>{opt.label}</option>
                                            ))}
                                        </Select>
                                        {errors.workPreference && <span className="text-red-600 text-sm">{errors.workPreference}</span>}
                                    </div>
                                    <div>
                                        <Input
                                            type="url"
                                            placeholder="https://linkedin.com/in/tu-perfil"
                                            value={formData.linkedinProfile}
                                            onChange={e => updateField('linkedinProfile', e.target.value)}
                                            onBlur={() => handleFieldBlur('linkedinProfile')}
                                            className="w-full"
                                        />
                                        {errors.linkedinProfile && <span className="text-red-600 text-sm">{errors.linkedinProfile}</span>}
                                    </div>
                                    <div>
                                        <Input
                                            type="url"
                                            placeholder="https://tu-portafolio.com"
                                            value={formData.portfolio}
                                            onChange={e => updateField('portfolio', e.target.value)}
                                            onBlur={() => handleFieldBlur('portfolio')}
                                            className="w-full"
                                        />
                                        {errors.portfolio && <span className="text-red-600 text-sm">{errors.portfolio}</span>}
                                    </div>
                                </div>

                                {/* Submit Button */}
                                <div className="mt-8 flex flex-col sm:flex-row gap-4">
                                    <Button
                                        type="submit"
                                        disabled={isSubmitting}
                                        className="flex-1 sm:flex-none sm:min-w-[200px]"
                                        data-testid="submit-button"
                                    >
                                        {isSubmitting ? 'Enviando...' : 'Enviar Postulación'}
                                    </Button>
                                    <Button
                                        type="button"
                                        disabled={isSubmitting}
                                        onClick={() => {
                                            setFormData({
                                                firstName: '',
                                                lastName: '',
                                                email: '',
                                                phone: '',
                                                location: '',
                                                coverLetter: '',
                                                salaryExpectation: '',
                                                availabilityDate: '',
                                                workPreference: 'remote',
                                                experience: '',
                                                portfolio: '',
                                                linkedinProfile: ''
                                            });
                                            setErrors({});
                                            setSubmitAttempted(false);
                                            announce('Formulario reiniciado', 'polite');
                                        }}
                                        data-testid="reset-button"
                                    >
                                        Limpiar Formulario
                                    </Button>
                                </div>
                            </form>
                        </section>
                    </div>
                </div>
            </div>
        </ErrorBoundary>
    );
}

