/**
 * XSS Protection and Input Sanitization
 * 
 * Provides comprehensive protection against Cross-Site Scripting (XSS) attacks
 * through input sanitization, output encoding, and content validation.
 * 
 * @package Security
 * @author Bubble of Talents Development Team
 * @version 1.0.0
 * @since 2025-01-05
 */

import DOMPurify from 'dompurify';

/**
 * DOMPurify configuration for different contexts
 */
export const SANITIZE_CONFIG = {
    // Strict configuration for user input
    STRICT: {
        ALLOWED_TAGS: ['b', 'i', 'em', 'strong', 'br'] as string[],
        ALLOWED_ATTR: [] as string[],
        KEEP_CONTENT: false,
        ALLOW_DATA_ATTR: false,
    },

    // Basic HTML configuration for rich text
    BASIC_HTML: {
        ALLOWED_TAGS: [
            'p', 'br', 'strong', 'b', 'i', 'em', 'u', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6',
            'ul', 'ol', 'li', 'blockquote', 'a'
        ] as string[],
        ALLOWED_ATTR: ['href', 'title', 'target'] as string[],
        KEEP_CONTENT: true,
        ALLOW_DATA_ATTR: false,
    },

    // Text-only configuration
    TEXT_ONLY: {
        ALLOWED_TAGS: [] as string[],
        ALLOWED_ATTR: [] as string[],
        KEEP_CONTENT: true,
        ALLOW_DATA_ATTR: false,
    },
};

/**
 * Sanitize HTML content to prevent XSS attacks
 */
export function sanitizeHtml(
    content: string,
    config: keyof typeof SANITIZE_CONFIG = 'STRICT'
): string {
    if (!content || typeof content !== 'string') {
        return '';
    }

    return DOMPurify.sanitize(content, SANITIZE_CONFIG[config]);
}

/**
 * Sanitize plain text input
 */
export function sanitizeText(input: string): string {
    if (!input || typeof input !== 'string') {
        return '';
    }

    return input
        .trim()
        .replace(/[\u0000-\u001F\u007F-\u009F]/g, '') // Remove control characters
        .replace(/[\u2000-\u200F\u2028-\u202F\u205F-\u206F\uFEFF]/g, '') // Remove unicode spaces
        .replace(/\s+/g, ' ') // Normalize whitespace
        .slice(0, 10000); // Limit length
}

/**
 * Validate and sanitize URL
 */
export function sanitizeUrl(url: string): string {
    if (!url || typeof url !== 'string') {
        return '';
    }

    try {
        const urlObj = new URL(url);

        // Only allow http and https protocols
        if (!['http:', 'https:'].includes(urlObj.protocol)) {
            return '';
        }

        return urlObj.toString();
    } catch {
        return '';
    }
}

/**
 * Sanitize email address
 */
export function sanitizeEmail(email: string): string {
    if (!email || typeof email !== 'string') {
        return '';
    }

    const sanitized = email.toLowerCase().trim();
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

    return emailRegex.test(sanitized) ? sanitized : '';
}

/**
 * Escape HTML characters for safe output
 */
export function escapeHtml(text: string): string {
    if (!text || typeof text !== 'string') {
        return '';
    }

    const htmlEscapes: Record<string, string> = {
        '&': '&amp;',
        '<': '&lt;',
        '>': '&gt;',
        '"': '&quot;',
        "'": '&#x27;',
        '/': '&#x2F;',
    };

    return text.replace(/[&<>"'\/]/g, (match) => htmlEscapes[match] || match);
}

/**
 * Validate and sanitize file name
 */
export function sanitizeFileName(fileName: string): string {
    if (!fileName || typeof fileName !== 'string') {
        return '';
    }

    return fileName
        .trim()
        .replace(/[^a-zA-Z0-9\-_\.\s]/g, '') // Remove special characters
        .replace(/\s+/g, '_') // Replace spaces with underscores
        .replace(/\.+/g, '.') // Remove multiple dots
        .slice(0, 255); // Limit length
}

/**
 * Validate if content is safe for rendering
 */
export function isContentSafe(content: string): boolean {
    if (!content || typeof content !== 'string') {
        return true;
    }

    // Check for common XSS patterns
    const dangerousPatterns = [
        /<script[\s\S]*?>[\s\S]*?<\/script>/gi,
        /javascript:/gi,
        /vbscript:/gi,
        /data:text\/html/gi,
        /on\w+\s*=/gi,
        /<iframe[\s\S]*?>/gi,
        /<object[\s\S]*?>/gi,
        /<embed[\s\S]*?>/gi,
        /<form[\s\S]*?>/gi,
    ];

    return !dangerousPatterns.some(pattern => pattern.test(content));
}

/**
 * Create safe innerHTML replacement
 */
export function createSafeInnerHTML(content: string): { __html: string } {
    return {
        __html: sanitizeHtml(content, 'BASIC_HTML')
    };
}

/**
 * Validate and sanitize form data
 */
export function sanitizeFormData<T extends Record<string, unknown>>(
    data: T
): Partial<T> {
    const sanitized: Partial<T> = {};

    Object.entries(data).forEach(([key, value]) => {
        if (typeof value === 'string') {
            sanitized[key as keyof T] = sanitizeText(value) as T[keyof T];
        } else if (typeof value === 'number' && !isNaN(value)) {
            sanitized[key as keyof T] = value as T[keyof T];
        } else if (typeof value === 'boolean') {
            sanitized[key as keyof T] = value as T[keyof T];
        } else if (Array.isArray(value)) {
            sanitized[key as keyof T] = value
                .filter(item => typeof item === 'string')
                .map(item => sanitizeText(item as string)) as T[keyof T];
        }
    });

    return sanitized;
}

/**
 * Validate input against common injection patterns
 */
export function detectInjectionAttempt(input: string): boolean {
    if (!input || typeof input !== 'string') {
        return false;
    }

    const injectionPatterns = [
        // SQL injection patterns
        /('|\\')|(;)|(\s*(union|select|insert|update|delete|drop|create|alter|exec|execute)\s+)/gi,

        // NoSQL injection patterns
        /(\$where|\$ne|\$gt|\$lt|\$gte|\$lte|\$in|\$nin|\$exists|\$regex)/gi,

        // Command injection patterns
        /(;|\||&|`|\$\(|\$\{)/gi,

        // Path traversal patterns
        /(\.\.\/|\.\.\\|\.\.|%2e%2e|%2f|%5c)/gi,

        // XSS patterns
        /(<script|<iframe|<object|<embed|javascript:|vbscript:|data:)/gi,
    ];

    return injectionPatterns.some(pattern => pattern.test(input));
}

/**
 * Rate limiting based on client fingerprint
 */
class RateLimiter {
    private attempts = new Map<string, { count: number; timestamp: number }>();
    private readonly maxAttempts: number;
    private readonly windowMs: number;

    constructor(maxAttempts = 10, windowMs = 60000) {
        this.maxAttempts = maxAttempts;
        this.windowMs = windowMs;
    }

    isAllowed(identifier: string): boolean {
        const now = Date.now();
        const attempt = this.attempts.get(identifier);

        if (!attempt) {
            this.attempts.set(identifier, { count: 1, timestamp: now });
            return true;
        }

        if (now - attempt.timestamp > this.windowMs) {
            this.attempts.set(identifier, { count: 1, timestamp: now });
            return true;
        }

        if (attempt.count >= this.maxAttempts) {
            return false;
        }

        attempt.count++;
        return true;
    }

    reset(identifier: string): void {
        this.attempts.delete(identifier);
    }

    cleanup(): void {
        const now = Date.now();
        const keysToDelete: string[] = [];
        this.attempts.forEach((attempt, key) => {
            if (now - attempt.timestamp > this.windowMs) {
                keysToDelete.push(key);
            }
        });
        keysToDelete.forEach(key => this.attempts.delete(key));
    }
}

// Global rate limiter instances
export const formSubmissionLimiter = new RateLimiter(5, 60000); // 5 submissions per minute
export const apiRequestLimiter = new RateLimiter(100, 60000); // 100 requests per minute

/**
 * Generate client fingerprint for rate limiting
 */
export function generateClientFingerprint(): string {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    if (ctx) {
        ctx.textBaseline = 'top';
        ctx.font = '14px Arial';
        ctx.fillText('Bubble of Talents', 2, 2);
    }

    const fingerprint = [
        navigator.userAgent,
        navigator.language,
        screen.width + 'x' + screen.height,
        new Date().getTimezoneOffset().toString(),
        canvas.toDataURL(),
    ].join('|');

    // Simple hash function
    let hash = 0;
    for (let i = 0; i < fingerprint.length; i++) {
        const char = fingerprint.charCodeAt(i);
        hash = ((hash << 5) - hash) + char;
        hash = hash & hash; // Convert to 32-bit integer
    }

    return Math.abs(hash).toString(36);
}

/**
 * Initialize XSS protection
 */
export function initXSSProtection(): void {
    // Set up CSP violation reporting
    document.addEventListener('securitypolicyviolation', (event) => {
        console.warn('CSP Violation:', event.violatedDirective, event.blockedURI);
    });

    // Clean up rate limiters periodically
    setInterval(() => {
        formSubmissionLimiter.cleanup();
        apiRequestLimiter.cleanup();
    }, 300000); // Every 5 minutes
}

/// <reference lib="webworker" />
// src/serviceWorker.ts
// Service Worker para almacenamiento en caché y capacidades offline

const CACHE_NAME = 'bubble-talents-cache-v1';
const RUNTIME_CACHE = 'runtime-cache';

// Recursos para precache
const PRECACHE_URLS = [
  '/',
  '/index.html',
  '/favicon.ico',
  '/favicon.svg',
  '/assets/css/critical.css',
  '/assets/images/logo.svg'
];


// Polyfill para SyncEvent si no está en el tipo global
export { };
declare global {
  // Solo si no existe
   
  interface SyncEvent extends ExtendableEvent {
    tag: string;
  }
}

// Instalación del Service Worker
self.addEventListener('install', (event) => {
  const swEvent = event as ExtendableEvent;
  swEvent.waitUntil(
    caches.open(CACHE_NAME)
      .then(cache => {
        // ...eliminado console.log para producción...
        return cache.addAll(PRECACHE_URLS);
      })
      .then(() => (self as unknown as ServiceWorkerGlobalScope).skipWaiting())
  );
});

// Activación y limpieza de caches antiguos
self.addEventListener('activate', (event) => {
  const swEvent = event as ExtendableEvent;
  const currentCaches = [CACHE_NAME, RUNTIME_CACHE];
  swEvent.waitUntil(
    caches.keys().then(cacheNames => {
      return cacheNames.filter(cacheName => !currentCaches.includes(cacheName));
    }).then(cachesToDelete => {
      return Promise.all(cachesToDelete.map(cacheToDelete => {
        return caches.delete(cacheToDelete);
      }));
    }).then(() => (self as unknown as ServiceWorkerGlobalScope).clients.claim())
  );
});

// Estrategia de caché: Cache First, Network Fallback
self.addEventListener('fetch', (event) => {
  const fetchEvent = event as FetchEvent;
  // Evitar cachear llamadas a la API
  if (fetchEvent.request.url.includes('/api/')) {
    return;
  }

  // No cachear peticiones POST u otras no GET
  if (fetchEvent.request.method !== 'GET') {
    return;
  }

  fetchEvent.respondWith(
    (async () => {
      const cachedResponse = await caches.match(fetchEvent.request);
      if (cachedResponse) {
        // Recurso encontrado en caché
        return cachedResponse;
      }
      // No está en caché, buscarlo en la red
      try {
        const cache = await caches.open(RUNTIME_CACHE);
        const response = await fetch(fetchEvent.request);
        if (response.status === 200) {
          cache.put(fetchEvent.request, response.clone());
        }
        return response;
      } catch (err) {
        // Si la red falla, intentar servir una página fallback para HTML
        if (fetchEvent.request.headers.get('accept')?.includes('text/html')) {
          const offline = await caches.match('/offline.html');
          if (offline) return offline;
        }
        return new Response('Error de conexión', {
          status: 503,
          statusText: 'Service Unavailable',
          headers: new Headers({
            'Content-Type': 'text/plain'
          })
        });
      }
    })()
  );
});

// Notificaciones push (opcional)
self.addEventListener('push', (event) => {
  const pushEvent = event as PushEvent;
  const data = pushEvent.data ? pushEvent.data.json() : { title: 'Notificación', body: '' };
  const options = {
    body: data.body,
    icon: '/assets/images/logo.svg',
    badge: '/assets/images/badge.png',
    vibrate: [100, 50, 100],
    data: {
      dateOfArrival: Date.now(),
      primaryKey: '1'
    },
    actions: [
      {
        action: 'explore',
        title: 'Ver detalles',
      },
      {
        action: 'close',
        title: 'Cerrar',
      },
    ]
  };

  pushEvent.waitUntil(
    (self as unknown as ServiceWorkerGlobalScope).registration.showNotification(data.title, options)
  );
});

// Manejo de sincronización en segundo plano
self.addEventListener('sync', (event) => {
  const syncEvent = event as SyncEvent;
  if (syncEvent.tag === 'sync-applications') {
    syncEvent.waitUntil(syncApplicationData());
  }
});

// Función de sincronización de datos
async function syncApplicationData() {
  try {
    // Lógica para sincronizar datos de aplicaciones
    // idb es una extensión personalizada en self
    const dataToSync = await (self as any).idb?.get('syncQueue');
    if (dataToSync && dataToSync.length) {
      // Enviar datos al servidor
      await Promise.all(dataToSync.map(async (item: Record<string, unknown>) => {
        try {
          const response = await fetch('/api/sync', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(item)
          });
          if (response.ok) {
            // Eliminar de la cola si se sincronizó correctamente
            // idb es una extensión personalizada en self
            await (self as any).idb?.delete('syncQueue', item.id);
          }
        } catch (error) {
          console.error('Error syncing item:', error);
        }
      }));
    }
  } catch (error) {
    console.error('Sync failed:', error);
  }
}

import { Candidate, Education, WorkExperience } from '../types';
import type { CVAnalysisResult } from '../types';

export interface CVAnalysisRequest {
  fileContent: string;
  fileName: string;
  fileType: 'pdf' | 'doc' | 'docx' | 'txt';
  options?: AnalysisOptions;
}

export interface AnalysisOptions {
  extractSkills?: boolean;
  extractExperience?: boolean;
  extractEducation?: boolean;
  extractContact?: boolean;
  analyzeQuality?: boolean;
  language?: 'es' | 'en';
}

export interface QualityAnalysis {
  overall: number;
  completeness: number;
  clarity: number;
  relevance: number;
  formatting: number;
  details: {
    hasContact: boolean;
    hasObjective: boolean;
    hasExperience: boolean;
    hasEducation: boolean;
    hasSkills: boolean;
    hasAchievements: boolean;
  };
}

export interface ExtractedSection {
  type: string;
  content: string;
  confidence: number;
  startIndex: number;
  endIndex: number;
}

export class CVAnalysisService {
  private readonly skillsKeywords = {
    technical: [
      'javascript', 'typescript', 'react', 'vue', 'angular', 'node.js',
      'python', 'java', 'c++', 'c#', 'php', 'ruby', 'go', 'rust',
      'html', 'css', 'sass', 'less', 'bootstrap', 'tailwind',
      'mysql', 'postgresql', 'mongodb', 'redis', 'elasticsearch',
      'aws', 'azure', 'gcp', 'docker', 'kubernetes', 'terraform',
      'git', 'jenkins', 'gitlab', 'github', 'jira', 'confluence'
    ],
    soft: [
      'leadership', 'communication', 'teamwork', 'problem solving',
      'critical thinking', 'creativity', 'adaptability', 'time management',
      'project management', 'analytical thinking', 'decision making'
    ]
  };

  private readonly experiencePatterns = [
    /(\d{4})\s*[-–]\s*(\d{4}|present|current|actual)/gi,
    /(\d{1,2}\/\d{4})\s*[-–]\s*(\d{1,2}\/\d{4}|present|current|actual)/gi,
    /(\d{1,2})\s*(year|año|month|mes|week|semana)s?\s*(of\s*)?experience/gi
  ];

  async analyzeCV(request: CVAnalysisRequest): Promise<CVAnalysisResult> {
    const startTime = Date.now();

    try {
      // Extract text content based on file type
      const textContent = await this.extractTextContent(request);

      // Perform parallel analysis
      const [
        extractedData,
        qualityAnalysis,
        sections,
        metadata
      ] = await Promise.all([
        this.extractCandidateData(textContent, request.options),
        this.analyzeQuality(textContent),
        this.extractSections(textContent),
        this.extractMetadata(textContent, request.fileName)
      ]);

      const analysis = this.generateAnalysis(extractedData, qualityAnalysis);
      const confidence = this.calculateConfidence(extractedData, qualityAnalysis);

      return {
        extractedData: {
          personalInfo: {
            name: extractedData.name || '',
            email: extractedData.email || '',
            phone: extractedData.phone,
            location: extractedData.location,
            linkedin_url: extractedData.resume_url,
            website: extractedData.resume_url
          },
          skills: extractedData.skills || [],
          languages: extractedData.languages,
          summary: extractedData.summary,
          totalExperience: extractedData.experience_years || 0,
          education: extractedData.education || [],
          workExperience: extractedData.work_experience || []
        },
        candidate: extractedData,
        analysis,
        confidence,
        overallScore: analysis.overallScore,
        aiAnalysis: {
          strengths: analysis.strengths,
          weaknesses: analysis.weaknesses,
          recommendations: analysis.recommendations
        },
        processingTime: Date.now() - startTime,
        metadata: {
          ...metadata,
          sections: sections.map(s => s.type)
        }
      };
    } catch (error) {
      console.error('CV Analysis failed:', error);
      throw new Error('Failed to analyze CV');
    }
  }

  private async extractTextContent(request: CVAnalysisRequest): Promise<string> {
    switch (request.fileType) {
      case 'txt':
        return request.fileContent;
      case 'pdf':
        return this.extractFromPDF(request.fileContent);
      case 'doc':
      case 'docx':
        return this.extractFromWord(request.fileContent);
      default:
        throw new Error(`Unsupported file type: ${request.fileType}`);
    }
  }

  private async extractFromPDF(content: string): Promise<string> {
    // In a real implementation, use PDF parsing library like pdf-parse
    // For now, return the content as-is (assuming it's already extracted)
    return content;
  }

  private async extractFromWord(content: string): Promise<string> {
    // In a real implementation, use Word parsing library like mammoth
    // For now, return the content as-is (assuming it's already extracted)
    return content;
  }

  private async extractCandidateData(
    text: string,
    options: AnalysisOptions = {}
  ): Promise<Partial<Candidate>> {
    const candidate: Partial<Candidate> = {};

    if (options.extractContact !== false) {
      candidate.email = this.extractEmail(text);
      candidate.phone = this.extractPhone(text);
      candidate.location = this.extractLocation(text);
    }

    if (options.extractSkills !== false) {
      candidate.skills = this.extractSkills(text);
    }

    if (options.extractExperience !== false) {
      candidate.experience = this.extractExperience(text);
    }

    if (options.extractEducation !== false) {
      candidate.education = this.extractEducation(text);
    }

    // Extract name (usually at the beginning)
    candidate.firstName = this.extractFirstName(text);
    candidate.lastName = this.extractLastName(text);

    return candidate;
  }

  private extractEmail(text: string): string | undefined {
    const emailRegex = /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b/g;
    const matches = text.match(emailRegex);
    return matches?.[0];
  }

  private extractPhone(text: string): string | undefined {
    const phoneRegex = /(?:\+?1[-.\s]?)?\(?([0-9]{3})\)?[-.\s]?([0-9]{3})[-.\s]?([0-9]{4})/g;
    const matches = text.match(phoneRegex);
    return matches?.[0];
  }

  private extractLocation(text: string): string | undefined {
    // Simple location extraction - could be improved with NLP
    const locationPatterns = [
      /(?:live|located|based|residing)\s+(?:in\s+)?([A-Za-z\s,]+)/gi,
      /address[:\s]+([A-Za-z\s,]+)/gi,
      /([A-Za-z\s]+),\s*([A-Z]{2})\s*\d{5}/gi
    ];

    for (const pattern of locationPatterns) {
      const matches = text.match(pattern);
      if (matches) {
        return matches[0].replace(/(?:live|located|based|residing|address)[:\s]+/gi, '').trim();
      }
    }

    return undefined;
  }

  private extractSkills(text: string): string[] {
    const skills: string[] = [];
    const lowerText = text.toLowerCase();

    // Extract technical skills
    for (const skill of this.skillsKeywords.technical) {
      if (lowerText.includes(skill.toLowerCase())) {
        skills.push(skill);
      }
    }

    // Extract soft skills
    for (const skill of this.skillsKeywords.soft) {
      if (lowerText.includes(skill.toLowerCase())) {
        skills.push(skill);
      }
    }

    // Look for skills sections
    const skillsSectionRegex = /(?:skills|competencies|technologies|tools)[:\s]+([\s\S]*?)(?:\n\n|\n[A-Z]|$)/gi;
    const skillsMatches = text.match(skillsSectionRegex);

    if (skillsMatches) {
      skillsMatches.forEach(match => {
        const skillsText = match.replace(/(?:skills|competencies|technologies|tools)[:\s]+/gi, '');
        const extractedSkills = skillsText
          .split(/[,\n•\-\*]/)
          .map(s => s.trim())
          .filter(s => s.length > 1 && s.length < 30);

        skills.push(...extractedSkills);
      });
    }

    return [...new Set(skills)]; // Remove duplicates
  }

  private extractExperience(text: string): any[] {
    const experiences: any[] = [];
    const lines = text.split('\n');

    // Look for experience patterns
    lines.forEach((line, index) => {
      const firstPattern = this.experiencePatterns[0];
      if (!firstPattern) return;

      const timeMatch = line.match(firstPattern);
      if (timeMatch && timeMatch[1] && timeMatch[2]) {
        const startYear = parseInt(timeMatch[1]);
        const endYear = timeMatch[2].toLowerCase().includes('present') ?
          new Date().getFullYear() : parseInt(timeMatch[2]);

        // Look for job title and company in surrounding lines
        const context = lines.slice(Math.max(0, index - 2), index + 3).join(' ');

        experiences.push({
          title: this.extractJobTitle(context),
          company: this.extractCompany(context),
          startDate: `${startYear}`,
          endDate: timeMatch[2].toLowerCase().includes('present') ? 'Present' : `${endYear}`,
          duration: endYear - startYear,
          description: this.extractJobDescription(context)
        });
      }
    });

    return experiences;
  }

  private extractEducation(text: string): any[] {
    const education: any[] = [];
    const educationKeywords = ['university', 'college', 'degree', 'bachelor', 'master', 'phd', 'diploma'];

    const lines = text.split('\n');
    lines.forEach(line => {
      const lowerLine = line.toLowerCase();
      if (educationKeywords.some(keyword => lowerLine.includes(keyword))) {
        education.push({
          degree: this.extractDegree(line),
          institution: this.extractInstitution(line),
          year: this.extractYear(line)
        });
      }
    });

    return education;
  }

  private extractFirstName(text: string): string | undefined {
    const lines = text.split('\n').slice(0, 5); // Check first 5 lines
    for (const line of lines) {
      const words = line.trim().split(/\s+/);
      if (words.length >= 2 && words[0] && words[0].length > 1) {
        return words[0];
      }
    }
    return undefined;
  }

  private extractLastName(text: string): string | undefined {
    const lines = text.split('\n').slice(0, 5); // Check first 5 lines
    for (const line of lines) {
      const words = line.trim().split(/\s+/);
      if (words.length >= 2 && words[1] && words[1].length > 1) {
        return words[1];
      }
    }
    return undefined;
  }

  private analyzeQuality(text: string): QualityAnalysis {
    const sections = this.detectSections(text);

    const details = {
      hasContact: this.hasContactInfo(text),
      hasObjective: sections.includes('objective') || sections.includes('summary'),
      hasExperience: sections.includes('experience') || sections.includes('work'),
      hasEducation: sections.includes('education'),
      hasSkills: sections.includes('skills') || sections.includes('competencies'),
      hasAchievements: sections.includes('achievements') || sections.includes('accomplishments')
    };

    const completeness = Object.values(details).filter(Boolean).length / Object.keys(details).length;
    const clarity = this.analyzeClarity(text);
    const relevance = this.analyzeRelevance(text);
    const formatting = this.analyzeFormatting(text);

    const overall = (completeness + clarity + relevance + formatting) / 4;

    return {
      overall,
      completeness,
      clarity,
      relevance,
      formatting,
      details
    };
  }

  private extractSections(text: string): ExtractedSection[] {
    const sections: ExtractedSection[] = [];
    const sectionHeaders = [
      'experience', 'education', 'skills', 'objective', 'summary',
      'achievements', 'projects', 'certifications', 'languages'
    ];

    sectionHeaders.forEach(header => {
      const regex = new RegExp(`^\\s*${header}\\s*$`, 'gmi');
      const matches = Array.from(text.matchAll(regex));

      matches.forEach(match => {
        sections.push({
          type: header,
          content: this.extractSectionContent(text, match.index || 0),
          confidence: 0.8,
          startIndex: match.index || 0,
          endIndex: (match.index || 0) + 100 // Simplified
        });
      });
    });

    return sections;
  }

  private extractMetadata(text: string, fileName: string): any {
    return {
      wordCount: text.split(/\s+/).length,
      language: this.detectLanguage(text),
      format: fileName.split('.').pop() || 'unknown'
    };
  }

  private generateAnalysis(
    candidate: Partial<Candidate>,
    quality: QualityAnalysis
  ): any {
    const strengths: string[] = [];
    const weaknesses: string[] = [];
    const recommendations: string[] = [];

    // Analyze strengths
    if (quality.details.hasExperience && candidate.experience?.length) {
      strengths.push('Has relevant work experience');
    }
    if (candidate.skills?.length && candidate.skills.length > 5) {
      strengths.push('Diverse skill set');
    }
    if (quality.details.hasEducation) {
      strengths.push('Educational background provided');
    }

    // Analyze weaknesses
    if (!quality.details.hasContact) {
      weaknesses.push('Missing contact information');
      recommendations.push('Add complete contact details including email and phone');
    }
    if (!quality.details.hasObjective) {
      weaknesses.push('No professional summary or objective');
      recommendations.push('Include a professional summary highlighting key strengths');
    }
    if (quality.formatting < 0.5) {
      weaknesses.push('Poor formatting and structure');
      recommendations.push('Improve document formatting and organization');
    }

    return {
      quality,
      strengths,
      weaknesses,
      recommendations
    };
  }

  private calculateConfidence(candidate: Partial<Candidate>, quality: QualityAnalysis): number {
    let confidence = 0;

    // Base confidence on data extraction success
    if (candidate.email) confidence += 0.2;
    if (candidate.skills?.length) confidence += 0.3;
    if (candidate.experience?.length) confidence += 0.3;
    if (candidate.firstName && candidate.lastName) confidence += 0.2;

    // Adjust based on quality
    confidence *= quality.overall;

    return Math.min(confidence, 1);
  }

  // Helper methods
  private detectSections(text: string): string[] {
    const sections: string[] = [];
    const sectionPatterns = [
      /^(experience|work history)/gmi,
      /^(education|academic)/gmi,
      /^(skills|competencies)/gmi,
      /^(objective|summary)/gmi,
      /^(achievements|accomplishments)/gmi
    ];

    sectionPatterns.forEach(pattern => {
      if (pattern.test(text)) {
        const match = pattern.exec(text);
        if (match && match[1]) sections.push(match[1].toLowerCase());
      }
    });

    return sections;
  }

  private hasContactInfo(text: string): boolean {
    return !!(this.extractEmail(text) || this.extractPhone(text));
  }

  private analyzeClarity(text: string): number {
    const sentences = text.split(/[.!?]+/).filter(s => s.trim().length > 0);
    const avgSentenceLength = sentences.reduce((sum, s) => sum + s.split(' ').length, 0) / sentences.length;

    // Ideal sentence length is 15-20 words
    if (avgSentenceLength >= 15 && avgSentenceLength <= 20) return 1;
    if (avgSentenceLength >= 10 && avgSentenceLength <= 25) return 0.8;
    return 0.5;
  }

  private analyzeRelevance(text: string): number {
    const professionalKeywords = [
      'experience', 'skills', 'project', 'manage', 'develop', 'design',
      'implement', 'lead', 'collaborate', 'achieve', 'deliver'
    ];

    const lowerText = text.toLowerCase();
    const relevantWords = professionalKeywords.filter(keyword =>
      lowerText.includes(keyword)
    ).length;

    return Math.min(relevantWords / professionalKeywords.length, 1);
  }

  private analyzeFormatting(text: string): number {
    let score = 0;

    // Check for consistent formatting
    const hasHeaders = /^[A-Z\s]+$/gm.test(text);
    if (hasHeaders) score += 0.3;

    // Check for bullet points or lists
    const hasBullets = /^[\s]*[•\-\*]/gm.test(text);
    if (hasBullets) score += 0.3;

    // Check for consistent spacing
    const lines = text.split('\n');
    const hasConsistentSpacing = lines.filter(line => line.trim()).length / lines.length > 0.3;
    if (hasConsistentSpacing) score += 0.4;

    return score;
  }

  private extractJobTitle(context: string): string {
    // Simplified job title extraction
    const words = context.split(/\s+/);
    return words.slice(0, 3).join(' ');
  }

  private extractCompany(context: string): string {
    // Simplified company extraction
    const lines = context.split('\n');
    return lines[1] || '';
  }

  private extractJobDescription(context: string): string {
    return context.substring(0, 200);
  }

  private extractDegree(line: string): string {
    const degreePatterns = [
      /bachelor[^\w]*([^,\n]+)/gi,
      /master[^\w]*([^,\n]+)/gi,
      /phd[^\w]*([^,\n]+)/gi,
      /degree[^\w]*([^,\n]+)/gi
    ];

    for (const pattern of degreePatterns) {
      const match = line.match(pattern);
      if (match) return match[0];
    }

    return line.substring(0, 50);
  }

  private extractInstitution(line: string): string {
    // Simplified institution extraction
    return line.split(',')[1]?.trim() || '';
  }

  private extractYear(line: string): string {
    const yearMatch = line.match(/\b(19|20)\d{2}\b/);
    return yearMatch?.[0] || '';
  }

  private extractSectionContent(text: string, startIndex: number): string {
    return text.substring(startIndex, startIndex + 500);
  }

  private detectLanguage(text: string): string {
    const spanishKeywords = ['experiencia', 'educación', 'habilidades', 'trabajo'];
    const englishKeywords = ['experience', 'education', 'skills', 'work'];

    const lowerText = text.toLowerCase();
    const spanishCount = spanishKeywords.filter(word => lowerText.includes(word)).length;
    const englishCount = englishKeywords.filter(word => lowerText.includes(word)).length;

    return spanishCount > englishCount ? 'es' : 'en';
  }
}

export default CVAnalysisService;

import { Candidate, Job, Company } from './types';
import type { RecommendationResult as BaseRecommendationResult, RecommendationFilters as BaseRecommendationFilters } from './types';

export interface RecommendationRequest {
  candidateId?: string;
  jobId?: string;
  companyId?: string;
  filters?: RecommendationFilters;
  limit?: number;
}

export interface RecommendationFilters {
  experience?: string[];
  skills?: string[];
  location?: string[];
  salaryRange?: { min: number; max: number };
  remote?: boolean;
  industry?: string[];
}

export interface RecommendationResult {
  id: string;
  type: 'candidate' | 'job' | 'company';
  score: number;
  reasons: string[];
  data: Candidate | Job | Company;
  matchScore: number;
  confidence: number;
  algorithm: string;
  factors: RecommendationFactor[];
}

export interface RecommendationFactor {
  name: string;
  weight: number;
  value: number;
  description: string;
}

export class RecommendationEngine {
  private readonly weights = {
    skills: 0.4,
    experience: 0.25,
    culture: 0.15,
    location: 0.1,
    salary: 0.1
  };

  async getJobRecommendations(
    candidateId: string,
    options: RecommendationRequest = {}
  ): Promise<RecommendationResult[]> {
    try {
      const candidate = await this.fetchCandidate(candidateId);
      const jobs = await this.fetchJobs(options.filters);

      const recommendations = jobs.map(job =>
        this.calculateJobMatch(candidate, job)
      );

      return recommendations
        .sort((a, b) => b.score - a.score)
        .slice(0, options.limit || 20);
    } catch (error) {
      console.error('Error getting job recommendations:', error);
      throw new Error('Failed to generate job recommendations');
    }
  }

  async getCandidateRecommendations(
    jobId: string,
    options: RecommendationRequest = {}
  ): Promise<RecommendationResult[]> {
    try {
      const job = await this.fetchJob(jobId);
      const candidates = await this.fetchCandidates(options.filters);

      const recommendations = candidates.map(candidate =>
        this.calculateCandidateMatch(candidate, job)
      );

      return recommendations
        .sort((a, b) => b.score - a.score)
        .slice(0, options.limit || 20);
    } catch (error) {
      console.error('Error getting candidate recommendations:', error);
      throw new Error('Failed to generate candidate recommendations');
    }
  }

  private calculateJobMatch(candidate: Candidate, job: Job): RecommendationResult {
    const factors: RecommendationFactor[] = [];
    let totalScore = 0;

    // Skills matching
    const skillsScore = this.calculateSkillsMatch(
      candidate.skills || [],
      job.requiredSkills || []
    );
    factors.push({
      name: 'Skills Match',
      weight: this.weights.skills,
      value: skillsScore,
      description: `${Math.round(skillsScore * 100)}% skills alignment`
    });
    totalScore += skillsScore * this.weights.skills;

    // Experience matching
    const experienceScore = this.calculateExperienceMatch(
      candidate.experience || [],
      job.experienceLevel || 'entry'
    );
    factors.push({
      name: 'Experience Level',
      weight: this.weights.experience,
      value: experienceScore,
      description: `Experience level compatibility: ${Math.round(experienceScore * 100)}%`
    });
    totalScore += experienceScore * this.weights.experience;

    // Location matching
    const locationScore = this.calculateLocationMatch(
      candidate.location,
      job.location,
      job.remote
    );
    factors.push({
      name: 'Location',
      weight: this.weights.location,
      value: locationScore,
      description: `Location compatibility: ${Math.round(locationScore * 100)}%`
    });
    totalScore += locationScore * this.weights.location;

    // Salary matching
    const salaryScore = this.calculateSalaryMatch(
      candidate.expectedSalary,
      job.salaryRange
    );
    factors.push({
      name: 'Salary Expectations',
      weight: this.weights.salary,
      value: salaryScore,
      description: `Salary alignment: ${Math.round(salaryScore * 100)}%`
    });
    totalScore += salaryScore * this.weights.salary;

    const reasons = this.generateJobReasons(factors, candidate, job);

    return {
      id: job.id,
      type: 'job',
      score: Math.round(totalScore * 100) / 100,
      reasons,
      data: job,
      matchScore: Math.round(totalScore * 100) / 100,
      confidence: this.calculateConfidence(factors),
      algorithm: 'weighted_scoring_v1',
      factors
    };
  }

  private calculateCandidateMatch(candidate: Candidate, job: Job): RecommendationResult {
    const factors: RecommendationFactor[] = [];
    let totalScore = 0;

    // Skills matching
    const skillsScore = this.calculateSkillsMatch(
      candidate.skills || [],
      job.requiredSkills || []
    );
    factors.push({
      name: 'Skills Match',
      weight: this.weights.skills,
      value: skillsScore,
      description: `${Math.round(skillsScore * 100)}% skills alignment`
    });
    totalScore += skillsScore * this.weights.skills;

    // Experience matching
    const experienceScore = this.calculateExperienceMatch(
      candidate.experience || [],
      job.experienceLevel || 'entry'
    );
    factors.push({
      name: 'Experience Level',
      weight: this.weights.experience,
      value: experienceScore,
      description: `Experience level compatibility: ${Math.round(experienceScore * 100)}%`
    });
    totalScore += experienceScore * this.weights.experience;

    const reasons = this.generateCandidateReasons(factors, candidate, job);

    return {
      id: candidate.id,
      type: 'candidate',
      score: Math.round(totalScore * 100) / 100,
      reasons,
      data: candidate,
      matchScore: Math.round(totalScore * 100) / 100,
      confidence: this.calculateConfidence(factors),
      algorithm: 'weighted_scoring_v1',
      factors
    };
  }

  private calculateSkillsMatch(candidateSkills: string[], requiredSkills: string[]): number {
    if (requiredSkills.length === 0) return 1;

    const matchedSkills = candidateSkills.filter(skill =>
      requiredSkills.some(required =>
        skill.toLowerCase().includes(required.toLowerCase()) ||
        required.toLowerCase().includes(skill.toLowerCase())
      )
    );

    return matchedSkills.length / requiredSkills.length;
  }

  private calculateExperienceMatch(
    candidateExperience: any[],
    requiredLevel: string
  ): number {
    const totalYears = candidateExperience.reduce((sum, exp) => {
      const years = exp.duration || 0;
      return sum + years;
    }, 0);

    const levelRequirements: Record<string, { min: number; max: number }> = {
      'entry': { min: 0, max: 2 },
      'mid': { min: 2, max: 5 },
      'senior': { min: 5, max: 10 },
      'lead': { min: 8, max: 15 }
    };

    const requirement = levelRequirements[requiredLevel] || levelRequirements['entry'];

    if (!requirement) return 0;

    if (totalYears >= requirement.min && totalYears <= requirement.max) {
      return 1;
    } else if (totalYears < requirement.min) {
      return totalYears / requirement.min;
    } else {
      return Math.max(0.7, 1 - (totalYears - requirement.max) / 10);
    }
  }

  private calculateLocationMatch(
    candidateLocation: string,
    jobLocation: string,
    isRemote: boolean
  ): number {
    if (isRemote) return 1;
    if (!candidateLocation || !jobLocation) return 0.5;

    const candidate = candidateLocation.toLowerCase();
    const job = jobLocation.toLowerCase();

    if (candidate === job) return 1;
    if (candidate.includes(job) || job.includes(candidate)) return 0.8;

    return 0.3;
  }

  private calculateSalaryMatch(
    expectedSalary: number,
    salaryRange: { min: number; max: number }
  ): number {
    if (!expectedSalary || !salaryRange) return 0.5;

    if (expectedSalary >= salaryRange.min && expectedSalary <= salaryRange.max) {
      return 1;
    }

    if (expectedSalary < salaryRange.min) {
      const diff = (salaryRange.min - expectedSalary) / salaryRange.min;
      return Math.max(0, 1 - diff);
    } else {
      const diff = (expectedSalary - salaryRange.max) / salaryRange.max;
      return Math.max(0, 1 - diff);
    }
  }

  private calculateConfidence(factors: RecommendationFactor[]): number {
    const avgScore = factors.reduce((sum, factor) => sum + factor.value, 0) / factors.length;
    const variance = factors.reduce((sum, factor) =>
      sum + Math.pow(factor.value - avgScore, 2), 0
    ) / factors.length;

    return Math.max(0.1, 1 - variance);
  }

  private generateJobReasons(
    factors: RecommendationFactor[],
