// Types for test utilities
interface CustomRenderOptions extends Omit<RenderOptions, 'wrapper'> {
    initialEntries?: string[];
    withRouter?: boolean;
    mockUser?: {
        id: string;
        email: string;
        role: 'candidate' | 'recruiter' | 'admin';
        name: string;
    };
